/* =====================================================================
   MEMBERSHIP SWITCH
   true  = live site: Join the Chase, paid tiers, VIP pricing, item cap.
   false = review copy (for Riot / TCGplayer): no memberships or payments
           anywhere; every feature is free and unlimited for everyone.
   ===================================================================== */
const MEMBERSHIP_ENABLED = true;

/* =========================================================
   Local storage compatibility shim
   ---------------------------------------------------------
   The rest of this app was originally built calling window.storage
   (get/set/list/delete), an API that only exists when this page is
   rendered inside Claude.ai's own artifact preview. On a real deployed
   page (like this one embedded in Squarespace), window.storage doesn't
   exist at all — every call to it was silently failing (wrapped in
   try/catch), meaning nothing was actually persisting for visitors on
   the live site.
   This shim defines window.storage using real localStorage whenever
   the Claude-provided version isn't present, matching the exact same
   method signatures — so none of the app's existing persistence code
   below needs to change at all; it just starts actually working.
   ========================================================= */
if (typeof window.storage === 'undefined') {
  window.storage = {
    async get(key, shared){
      const raw = localStorage.getItem('cb:'+key);
      if(raw === null){ throw new Error('key not found: '+key); }
      return { key, value: raw, shared: !!shared };
    },
    async set(key, value, shared){
      localStorage.setItem('cb:'+key, value);
      return { key, value, shared: !!shared };
    },
    async delete(key, shared){
      localStorage.removeItem('cb:'+key);
      return { key, deleted: true, shared: !!shared };
    },
    async list(prefix, shared){
      const keys = [];
      for(let i=0;i<localStorage.length;i++){
        const k = localStorage.key(i);
        if(k && k.startsWith('cb:')){
          const bare = k.slice(3);
          if(!prefix || bare.startsWith(prefix)) keys.push(bare);
        }
      }
      return { keys, prefix, shared: !!shared };
    }
  };
}

// The Promos & Collectibles catalog is served by the get-promos Supabase
// Edge Function (same pattern as get-cards): 200 items per call, rate-limited
// per IP, from a table browsers can't read directly. It is no longer embedded
// in this page. Records use short keys / bare Google Drive file IDs, which are
// expanded below, so the rest of the app is unaffected.
// Promo pictures are either a Google Drive file ID (older items) or a full
// link to the picture on GitHub (items added from November 2026 on).
function driveThumb(fileId){
  if(!fileId) return '';
  if(/^https?:\/\//i.test(fileId)) return fileId;
  return `https://drive.google.com/thumbnail?id=${fileId}&sz=w1200`;
}

function promoApiUrl(){ return `${SUPABASE_URL}/functions/v1/get-promos`; }

// Signed-in members send their login so get-promos returns the full research;
// visitors get the public fields only (picture, name, set, type, tags, rarity, language).
async function promoSession(){
  try{
    if(typeof sb === 'undefined' || !sb || !sb.auth) return null;
    const { data } = await sb.auth.getSession();
    return (data && data.session) || null;
  }catch(e){ return null; }
}
async function fetchPromoPage(offset, token){
  for(let attempt=0; attempt<4; attempt++){
    const res = await fetch(`${promoApiUrl()}?offset=${offset}`, {
      headers: { 'Authorization': `Bearer ${token || SUPABASE_ANON_KEY}`, 'apikey': SUPABASE_ANON_KEY },
      cache: 'no-store'
    });
    if(res.ok) return res.json();
    if(res.status === 429){
      await new Promise(r=>setTimeout(r, 1500));
      continue;
    }
    throw new Error(`HTTP ${res.status}`);
  }
  throw new Error('rate limited');
}

async function fetchAllPromos(token){
  const first = await fetchPromoPage(0, token);
  const pageSize = (first.data && first.data.length) || 200;
  const total = first.total || first.data.length;
  const jobs = [];
  for(let off = pageSize; off < total; off += pageSize) jobs.push(fetchPromoPage(off, token));
  const rest = await Promise.all(jobs);
  const items = [first, ...rest].flatMap(p => p.data);
  items.full = !!first.full;
  return items;
}

// Browser cache so repeat visits show promos instantly. One copy per account
// ('anon' for visitors), so a member's full copy is never shown to someone else
// on the same browser; it's cleared on log out.
const PROMO_CACHE_KEY = 'cb_promos_cache_v5'; // v5: everyone's saved copy is dropped so new pictures show without any manual clearing
const PROMO_CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // an older copy still shows instantly; a fresh one is fetched right behind it
function cbPromoCacheKey(userId){ return PROMO_CACHE_KEY + ':' + (userId || 'anon'); }
function cbReadPromoCache(userId){
  try{
    const o = JSON.parse(localStorage.getItem(cbPromoCacheKey(userId)) || 'null');
    return (o && Array.isArray(o.items) && o.items.length) ? o : null;
  }catch(e){ return null; }
}
function cbWritePromoCache(userId, items){
  try{ localStorage.setItem(cbPromoCacheKey(userId), JSON.stringify({ t: Date.now(), full: !!items.full, items })); }
  catch(e){ try{ localStorage.removeItem(cbPromoCacheKey(userId)); }catch(_){} }
}
function cbClearMemberPromoCaches(){
  try{
    Object.keys(localStorage).forEach(k=>{
      if((k.startsWith(PROMO_CACHE_KEY + ':') && !k.endsWith(':anon')) || k === 'cb_promos_cache_v1') localStorage.removeItem(k);
    });
  }catch(e){}
}
let promosAreFull = false;
let promosFromCache = false; // shown from this browser's saved copy; a fresh copy is fetched right after

async function loadItems(forceFresh){
  const session = await promoSession();
  const userId = session && session.user ? session.user.id : null;
  const cached = forceFresh ? null : cbReadPromoCache(userId);
  let rawItems;
  promosFromCache = false;
  if(cached && (Date.now() - cached.t) < PROMO_CACHE_TTL_MS){
    rawItems = cached.items;
    promosAreFull = !!cached.full;
    promosFromCache = true;
  }else{
    try{
      rawItems = await fetchAllPromos(session ? session.access_token : null);
      promosAreFull = !!rawItems.full;
      if(rawItems.length) cbWritePromoCache(userId, rawItems);
    }catch(e){
      console.error('Failed to load promos', e);
      if(cached){
        rawItems = cached.items; // offline / server busy: use the last copy
      }else{
        document.getElementById('results').innerHTML =
          '<div class="empty-state">The promo catalog couldn\'t load right now. '
          + 'Please refresh the page in a moment.</div>';
        rawItems = [];
      }
    }
  }

  // A small number of cards had low-quality source images; higher-quality
  // replacements are embedded separately (base64 JPEG, keyed by item id)
  // and swapped in here so the rest of the app needs no changes.
  let imageOverrides = {};
  try{
    const overridesEl = document.getElementById('imgOverridesJson');
    if(overridesEl){
      imageOverrides = JSON.parse(overridesEl.textContent.replace(/\s+/g, ''));
    }
  }catch(e){ /* non-fatal: just keep the original images */ }

  return rawItems.map(r => ({
    row: r.r,
    status: r.st,
    category: r.cat,
    name: r.nm,
    event: r.ev,
    set: r.se,
    itemType: r.ty,
    tags: r.tg,
    domain: r.do,
    rarity: r.ra,
    collectorNum: r.cn,
    info: r.inf,
    hasNotes: !!(r.inf || r.hn),
    language: r.la,
    img: imageOverrides[r.id] ? `data:image/jpeg;base64,${imageOverrides[r.id]}` : driveThumb(r.img),
    id: r.id,
    infoImg: driveThumb(r.ii),
    packagingImg: driveThumb(r.pi),
    packagingText: r.pt,
    tournament: r.tn,
    metal: r.me,
    nexusNight: r.nn,
    foil: r.fo,
    flagMix: r.lf || '',
    bestOfMetal: r.bm,
    prizeWall: r.pw,
    serialMax: (r.sx|0) > 0 ? (r.sx|0) : 0, // serialized item: members list each numbered card they own
    serialCards: r.sc || '',
    serialNote: r.sn || '',
    eventList: r.evl || '' // VIP: the specific events behind "Multiple Events/Cons ..."
  }));
}

let ITEMS = [];
let promosLoaded = false; // false until the first promo list has arrived

const state = {
  search: '',
  status: '',
  category: '',
  language: '',
  rarity: '',
  domain: '',
  event: '',
  special: '', // 'metal' | 'nexusNight' | 'tournament' — set by the side-panel chips
  set: '',     // set code from the Promos "All sets" dropdown
  sort: 'row',
  view: 'grid',
  owned: {},
  qty: {}
};

let currentModalId = null;
let currentModalKind = 'promo'; // 'promo' | 'card'

function escapeHtml(str){
  return (str||'').toString()
    .replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')
    .replaceAll('"','&quot;');
}

function domainList(d){
  if(!d || String(d).trim() === 'N/A') return [];
  return d.split(/\n|\//).map(s=>s.trim()).filter(Boolean).filter(s=>s!=='N/A');
}

async function loadOwned(){
  try{
    const res = await window.storage.list('owned:');
    const owned = {};
    if(res && res.keys){
      for(const k of res.keys){
        try{
          const r = await window.storage.get(k, false);
          if(r && r.value === '1'){
            owned[k.replace('owned:','')] = true;
          }
        }catch(e){}
      }
    }
    state.owned = owned;
  }catch(e){ /* storage unavailable */ }
}

// Promos merged into one entry (the same promo had been listed twice). The
// removed id's check mark moves to the kept id, counted ONCE. If someone had
// marked both, the binder asks whether they really own two copies instead of
