// Merged entries that stood for one version: the kept entry remembers it.
const MERGED_VERSION = { 'item-319':'Second Print' };
const MERGE_ASK_KEY = 'cb_merge_ask_v1';
function mergeAskList(){ try{ return JSON.parse(localStorage.getItem(MERGE_ASK_KEY) || '[]'); }catch(e){ return []; } }
function setMergeAskList(a){ try{ a.length ? localStorage.setItem(MERGE_ASK_KEY, JSON.stringify(a)) : localStorage.removeItem(MERGE_ASK_KEY); }catch(e){} }
// Products that became one entry with a print-run picker: owners keep their check, and the version is set.
const MERGED_PRODUCTS = { 'prod-109-en':'prod-20-en', 'prod-109-ch':'prod-20-ch', 'prod-109-fr':'prod-20-fr', 'prod-109-ko':'prod-20-ko' };
const MERGED_PRODUCT_VERSION = { 'prod-109-en':'Second Print', 'prod-109-ch':'Second Print', 'prod-109-fr':'Second Print', 'prod-109-ko':'Second Print' };
async function migrateMergedProducts(){
  let changed = false;
  for(const [from, to] of Object.entries(MERGED_PRODUCTS)){
    if(!productState.owned[from] && !(productState.qty[from] > 0)) continue;
    const hadTo = !!productState.owned[to];
    productState.owned[to] = true; try{ await window.storage.set('prodowned:'+to, '1', false); }catch(e){}
    // First and second print were separate boxes, so owning both means 2 copies.
    productState.qty[to] = hadTo ? (productState.qty[to] || 1) + (productState.qty[from] || 1) : Math.max(productState.qty[from] || 0, 1);
    try{ await window.storage.set('prodqty:'+to, String(productState.qty[to]), false); }catch(e){}
    if(!hadTo && typeof setExtra === 'function') await setExtra('prod:' + to, { v: MERGED_PRODUCT_VERSION[from] });
    const e = typeof getExtra === 'function' ? getExtra('prod:' + from) : {};
    if(e && e.p !== undefined && !hadTo) await setExtra('prod:' + to, { p: e.p, d: e.d });
    delete productState.owned[from]; delete productState.qty[from];
    try{ await window.storage.delete('prodowned:'+from, false); await window.storage.delete('prodqty:'+from, false); }catch(e){}
    changed = true;
  }
  if(changed && typeof queueCloudSave === 'function') queueCloudSave();
}
// Entries that were split in two: anyone who had the old combined entry also gets the new one.
const SPLIT_PROMOS = { 'item-10644':'item-10653' }; // Korea launch coin + Teemo card
async function migrateSplitPromos(){
  let done = {}; try{ done = JSON.parse(localStorage.getItem('cb_split_done_v1') || '{}'); }catch(e){}
  let changed = false;
  for(const [from, to] of Object.entries(SPLIT_PROMOS)){
    if(done[from]) continue;
    if(!ITEMS.some(i => i.id === to)) continue;   // new entry not live yet: try again next visit
    done[from] = 1;
    if(state.owned[from] && !state.owned[to]){
      state.owned[to] = true; try{ await window.storage.set('owned:'+to, '1', false); }catch(e){}
      const q = state.qty[from] || 1; state.qty[to] = q; try{ await window.storage.set('qty:'+to, String(q), false); }catch(e){}
      changed = true;
    }
  }
  try{ localStorage.setItem('cb_split_done_v1', JSON.stringify(done)); }catch(e){}
  if(changed && typeof queueCloudSave === 'function') queueCloudSave();
}
async function migrateMergedPromos(){
  await migrateSplitPromos();
  let changed = false; const ask = mergeAskList();
  for(const [from, to] of Object.entries(MERGED_PROMOS)){
    const hadFrom = !!state.owned[from] || (state.qty[from] || 0) > 0;
    if(!hadFrom) continue;
    const hadTo = !!state.owned[to] || (state.qty[to] || 0) > 0;
    if(!state.owned[to]){ state.owned[to] = true; try{ await window.storage.set('owned:'+to, '1', false); }catch(e){} }
    const q = Math.max(state.qty[to] || 0, state.qty[from] || 0, 1);
    state.qty[to] = q; try{ await window.storage.set('qty:'+to, String(q), false); }catch(e){}
    if(MERGED_VERSION[from] && !hadTo && typeof setExtra === 'function') await setExtra('promo:' + to, { v: MERGED_VERSION[from] });
    delete state.owned[from]; try{ await window.storage.delete('owned:'+from, false); }catch(e){}
    delete state.qty[from]; try{ await window.storage.delete('qty:'+from, false); }catch(e){}
    if(hadTo && !ask.includes(to)) ask.push(to);
    changed = true;
  }
  setMergeAskList(ask);
  if(changed && typeof queueCloudSave === 'function') queueCloudSave();
}
// Shown on the My Binder tab: "these were listed twice, do you own 2?"
function maybeShowMergeNotice(){
  const ask = mergeAskList().filter(id => state.owned[id]);
  if(!ask.length || document.getElementById('mergeNotice')) { if(!ask.length) setMergeAskList([]); return; }
  const items = ask.map(id => ITEMS.find(i => i.id === id)).filter(Boolean);
  if(!items.length) return;
  const box = document.createElement('div');
  box.id = 'mergeNotice'; box.className = 'patch-notice-backdrop';
  box.innerHTML = `
    <div class="patch-notice" role="dialog" aria-modal="true" aria-labelledby="mergeTitle">
      <div class="patch-notice-tag">Binder update</div>
      <h3 id="mergeTitle">Do you own two of these?</h3>
      <p>We found ${items.length === 1 ? 'a promo' : 'promos'} that had been listed more than once (for example once per event), and you had marked more than one copy. ${items.length === 1 ? 'It is' : 'They are'} now one entry, counted as <b>1 copy</b>. If you really own two, tap <b>I have 2</b>.</p>
      <div class="merge-list">${items.map(i => `<div class="merge-row"><span class="merge-who">${i.img ? `<img class="merge-thumb" src="${escapeHtml(i.img)}" alt="" loading="lazy">` : ''}<span class="merge-name">${escapeHtml(i.name)}<small>${escapeHtml([i.language, i.set, i.collectorNum && i.collectorNum !== 'N/A' ? '#' + i.collectorNum : ''].filter(Boolean).join(' · '))}</small></span></span>
        <span class="merge-btns"><button type="button" class="pn-secondary" onclick="answerMerge('${i.id}',1)">Just 1</button><button type="button" class="pn-primary" onclick="answerMerge('${i.id}',2)">I have 2</button></span></div>`).join('')}</div>
    </div>`;
  (document.getElementById('collectBoundApp') || document.body).appendChild(box);
}
async function answerMerge(id, n){
  await setQty(id, n);
  setMergeAskList(mergeAskList().filter(x => x !== id));
  const el = document.getElementById('mergeNotice'); if(el) el.remove();
  maybeShowMergeNotice();
  if(typeof renderBinder === 'function') renderBinder();
}
async function loadQty(){
  try{
    const res = await window.storage.list('qty:');
    const qty = {};
    if(res && res.keys){
      for(const k of res.keys){
        try{
          const r = await window.storage.get(k, false);
          const n = r && r.value ? parseInt(r.value, 10) : 0;
          if(n > 0){
            qty[k.replace('qty:','')] = n;
          }
        }catch(e){}
      }
    }
    state.qty = qty;
  }catch(e){ /* storage unavailable */ }
}

function getQty(id){
  return state.qty[id] || 0;
}

async function setQty(id, next){
  // Free accounts can track promos too (they count toward the 75-item limit).
  next = Math.max(0, next|0);
  state.qty[id] = next;
  try{
    await window.storage.set('qty:'+id, String(next), false);
  }catch(e){}
  const el = document.getElementById('qtyValue-'+id);
  if(el) el.textContent = next;
  queueCloudSave();
}

/* =========================================================
   My Binder — a live view of everything marked HAVE, pulled
   from both the promo catalog and the card sets.
   ========================================================= */

const binderState = { search: '', kind: '', lang: '', special: '' };

// "×3" bubble next to the check mark when someone owns more than one copy.
function qtyBubbleHtml(n){
  n = n|0;
  return n > 1 ? `<span class="qty-bubble" title="${n} copies in your collection">&times;${n}</span>` : '';
}
/* =========================================================
   Graded copies, serialized cards and owner photos
   ---------------------------------------------------------
   * Any owned card printing or promo can be marked "Sent for grading" or
     "Graded", with the grading company, grade and cert number.
   * Items with a serial range (data key sx, e.g. the T1 Serialized Signature
     Card) let members list each serialized card they own: which card,
     its number (1 to sx), plus grading.
   * Owners can add a photo of their copy (handy while it's away being
     graded). Photos go to the private Supabase Storage bucket
     "collection-photos", in a folder only that member can read.
   Saved locally as grade:<key> and serial:<promoId>, and in the cloud copy
   as data.grading / data.serials.
   ========================================================= */
const GRADERS = ['PSA', 'BGS (Beckett)', 'CGC', 'SGC', 'TAG', 'ACE', 'ARS', 'Other'];
const GRADES = ['10', '9.5', '9', '8.5', '8', '7.5', '7', '6.5', '6', '5.5', '5', '4.5', '4', '3.5', '3', '2.5', '2', '1.5', '1', 'Authentic'];
const GRADE_STATUS = { submitted: 'Sent for grading', graded: 'Graded' };
const PHOTO_BUCKET = 'collection-photos';
let gradeState = {};   // { 'card:<id>:<Normal|Foil>' | 'promo:<id>': { s, by, g, cert, ph } }
let serialState = {};  // { '<promoId>': [ { c, n, s, by, g, cert, ph } ] }

function gradeKeyCard(id, style){ return 'card:' + id + ':' + style; }
function gradeKeyPromo(id){ return 'promo:' + id; }
function cleanGrade(v){
  if(!v || typeof v !== 'object') return null;
  if(!GRADE_STATUS[v.s]) return v.ph ? { ph: String(v.ph).slice(0, 200) } : null; // just a photo of the copy
  const out = { s: v.s };
  if(v.by && GRADERS.includes(v.by)) out.by = v.by;
  if(v.s === 'graded' && v.g && GRADES.includes(String(v.g))) out.g = String(v.g);
  if(v.cert) out.cert = String(v.cert).slice(0, 40);
  if(v.ph) out.ph = String(v.ph).slice(0, 200);
  return out;
}
function cleanSerial(e, max){
  if(!e || typeof e !== 'object') return null;
  const n = parseInt(e.n, 10), c = parseInt(e.c, 10);
  if(!(n >= 1 && n <= (max || 99999)) || !(c >= 0 && c < 20)) return null;
  const out = { c, n };
  if(GRADE_STATUS[e.s]){
    out.s = e.s;
    if(e.by && GRADERS.includes(e.by)) out.by = e.by;
    if(e.s === 'graded' && e.g && GRADES.includes(String(e.g))) out.g = String(e.g);
    if(e.cert) out.cert = String(e.cert).slice(0, 40);
  }
  if(e.ph) out.ph = String(e.ph).slice(0, 200);
  return out;
}

async function loadGrading(){
  try{
    const g = await window.storage.list('grade:');
    const gs = {};
    for(const k of (g && g.keys) || []){
      try{ const r = await window.storage.get(k, false); const v = cleanGrade(JSON.parse(r.value)); if(v) gs[k.slice(6)] = v; }catch(e){}
    }
    gradeState = gs;
    const s = await window.storage.list('serial:');
    const ss = {};
    for(const k of (s && s.keys) || []){
      try{
        const r = await window.storage.get(k, false);
        const arr = (JSON.parse(r.value) || []).map(e => cleanSerial(e)).filter(Boolean);
        if(arr.length) ss[k.slice(7)] = arr;
      }catch(e){}
    }
    serialState = ss;
  }catch(e){ /* storage unavailable */ }
}
async function saveGrade(key){
  const v = cleanGrade(gradeState[key]);
  try{
    if(v){ gradeState[key] = v; await window.storage.set('grade:' + key, JSON.stringify(v), false); }
    else { delete gradeState[key]; await window.storage.delete('grade:' + key, false); }
  }catch(e){}
  queueCloudSave();
}
async function saveSerials(promoId){
  const arr = serialState[promoId] || [];
  try{
    if(arr.length) await window.storage.set('serial:' + promoId, JSON.stringify(arr), false);
    else { delete serialState[promoId]; await window.storage.delete('serial:' + promoId, false); }
  }catch(e){}
  // The item counts as owned once a serialized card is listed; copies = how many are listed.
  if(arr.length){
    if(!state.owned[promoId]){ state.owned[promoId] = true; try{ await window.storage.set('owned:' + promoId, '1', false); }catch(e){} }
    state.qty[promoId] = arr.length; try{ await window.storage.set('qty:' + promoId, String(arr.length), false); }catch(e){}
  } else if(state.qty[promoId]){
    state.qty[promoId] = 0; try{ await window.storage.set('qty:' + promoId, '0', false); }catch(e){}
  }
  queueCloudSave();
  renderAll();
  refreshBinderIfVisible();
}
function reopenCurrentModal(){
  if(!currentModalId) return;
  const y = (document.querySelector('.modal') || {}).scrollTop;
  openModal(currentModalId);
  const m = document.querySelector('.modal'); if(m && y) m.scrollTop = y;
}

// ---- short label used on tiles and lists, e.g. "PSA 10" or "At PSA"
function gradeLabel(v){
  if(!v || !v.s) return '';
  const by = v.by ? v.by.replace(' (Beckett)', '') : '';
  if(v.s === 'graded') return [by, v.g].filter(Boolean).join(' ') || 'Graded';
  return by ? 'At ' + by : 'Grading';
}
function gradeBubbleHtml(labels){
  labels = (labels || []).filter(Boolean);
  if(!labels.length) return '';
  const text = labels.length > 1 ? labels[0] + ' +' + (labels.length - 1) : labels[0];
  return `<span class="grade-bubble" title="${escapeHtml(labels.join(', '))}">${escapeHtml(text)}</span>`;
}
function promoGradeLabels(id){
  const out = [];
  const g = gradeLabel(gradeState[gradeKeyPromo(id)]); if(g) out.push(g);
  (serialState[id] || []).slice().sort((a, b) => (a.s === 'graded' ? 0 : 1) - (b.s === 'graded' ? 0 : 1))
    .forEach(e => { const l = gradeLabel(e); out.push(l ? `#${e.n} ${l}` : `#${e.n}`); });
  return out;
}
function cardGradeLabels(id){
  // graded copies first, then ones away being graded
  return ['Normal', 'Foil'].map(s => gradeState[gradeKeyCard(id, s)]).filter(v => v && v.s)
    .sort((a, b) => (a.s === 'graded' ? 0 : 1) - (b.s === 'graded' ? 0 : 1)).map(gradeLabel);
}

// ---- the grading controls (status, company, grade, cert, photo)
function gradeControlsHtml(v, onField, onPhoto, onPhotoRemove, label){
  v = v || {};
  const st = v.s || '';
  const sel = (opts, cur, field, first) => `<select class="gr-sel" onchange="${onField}('${field}', this.value)">${first ? `<option value="">${first}</option>` : ''}${opts.map(o => `<option value="${escapeHtml(o)}"${String(cur || '') === o ? ' selected' : ''}>${escapeHtml(o)}</option>`).join('')}</select>`;
  return `
    <div class="gr-line">
      ${label ? `<span class="gr-label">${escapeHtml(label)}</span>` : ''}
      <select class="gr-sel" onchange="${onField}('s', this.value)">
        <option value="">Not graded</option>
        <option value="submitted"${st === 'submitted' ? ' selected' : ''}>Sent for grading</option>
        <option value="graded"${st === 'graded' ? ' selected' : ''}>Graded</option>
      </select>
      ${st ? sel(GRADERS, v.by, 'by', 'Grading company') : ''}
      ${st === 'graded' ? sel(GRADES, v.g, 'g', 'Grade') : ''}
      ${st ? `<input class="gr-cert" type="text" maxlength="40" placeholder="Cert # (optional)" value="${escapeHtml(v.cert || '')}" onchange="${onField}('cert', this.value)">` : ''}
    </div>
    <div class="gr-photo-line">${photoControlHtml(v.ph, onPhoto, onPhotoRemove)}</div>`;
}
function photoControlHtml(path, onPhoto, onPhotoRemove){
  if(path){
    return `<span class="gr-photo"><img data-photo-path="${escapeHtml(path)}" alt="Your photo" onclick="openOwnerPhoto(this)"/><button type="button" class="gr-photo-x" title="Remove photo" onclick="${onPhotoRemove}()">&times;</button></span>`;
  }
  return `<label class="gr-photo-add">&#128247; Add your photo<input type="file" accept="image/jpeg,image/png,image/webp" hidden onchange="${onPhoto}(this)"></label>`;
}

// Card Sets: one grading line per owned printing.
function cardGradingSectionHtml(card){
  const owned = card.printings.filter(s => getCardOwned(card.id, s));
  if(!owned.length) return '';
  bindCardGradeHandlers(card);
  return `<div class="grade-box"><div class="grade-title">Graded copies <span class="grade-hint">Optional. Track a copy that's graded or away being graded.</span></div>
    ${owned.map(s => `<div class="gr-item">${gradeControlsHtml(gradeState[gradeKeyCard(card.id, s)],
        `cbGradeCard_${cssId(card.id)}_${s}`, `cbGradePhotoCard_${cssId(card.id)}_${s}`, `cbGradePhotoDelCard_${cssId(card.id)}_${s}`,
        owned.length > 1 || card.printings.length > 1 ? printingLabel(s) : '')}</div>`).join('')}
  </div>`;
}
// Promos: one grading line when owned (serialized items use the serial list instead).
function promoGradingSectionHtml(item){
  if(item.serialMax || !state.owned[item.id]) return '';
  const k = `cbGradePromo_${cssId(item.id)}`;
  bindGradeHandlers(gradeKeyPromo(item.id), k);
  return `<div class="grade-box"><div class="grade-title">Graded copy <span class="grade-hint">Optional. Track a copy that's graded or away being graded.</span></div>
    <div class="gr-item">${gradeControlsHtml(gradeState[gradeKeyPromo(item.id)], k, k + '_photo', k + '_photodel', '')}</div></div>`;
}
// "Multiple Events/Cons ..." promos: VIP members see the specific events.
function eventListHtml(item){
  const multi = /multiple events/i.test(item.event || '');
  const list = String(item.eventList || '').split('\n').map(x => x.trim().replace(/^[•\-]\s*/, '')).filter(Boolean);
  if(list.length){
    return `<details class="ev-list" open><summary>Given out at (${list.length})</summary><ul>${list.map(x => `<li>${escapeHtml(x)}</li>`).join('')}</ul></details>`;
  }
  if(multi && MEMBERSHIP_ENABLED && !isVipTier()){
    return `<div class="ev-list-lock">&#128274; VIP members see the specific events. <a href="#" onclick="event.preventDefault(); closeModal(); openMembershipChooser('tier2');">Go VIP &rarr;</a></div>`;
  }
  return '';
}
function cssId(id){ return String(id).replace(/[^A-Za-z0-9]/g, '_'); }

// The inline handlers above call per-item functions; make them on demand so the
// HTML stays simple (no quoting of ids inside attribute strings).
function bindGradeHandlers(key, prefix){
  window[prefix] = (field, value) => setGradeField(key, field, value);
  window[prefix + '_photo'] = input => addGradePhoto(key, input);
  window[prefix + '_photodel'] = () => removeGradePhoto(key);
}
function bindCardGradeHandlers(card){
  card.printings.forEach(s => {
    const key = gradeKeyCard(card.id, s);
    window[`cbGradeCard_${cssId(card.id)}_${s}`] = (field, value) => setGradeField(key, field, value);
    window[`cbGradePhotoCard_${cssId(card.id)}_${s}`] = input => addGradePhoto(key, input);
    window[`cbGradePhotoDelCard_${cssId(card.id)}_${s}`] = () => removeGradePhoto(key);
  });
}
async function setGradeField(key, field, value){
  const v = Object.assign({}, gradeState[key] || {});
  v[field] = value;
  if(field === 's' && !value){ delete v.by; delete v.g; delete v.cert; } // back to "Not graded" (a photo stays)
  if(field === 's' && value === 'submitted') delete v.g;
  gradeState[key] = v;
  await saveGrade(key);
  if(typeof renderAll === 'function') renderAll();
  if(typeof renderSetAll === 'function') renderSetAll();
  refreshBinderIfVisible();
  if(field === 's') reopenCurrentModal();
}
async function addGradePhoto(key, input){
  const path = await uploadOwnerPhoto(input && input.files && input.files[0]);
  if(!path) return;
  gradeState[key] = Object.assign({}, gradeState[key] || {}, { ph: path });
  await saveGrade(key);
  reopenCurrentModal();
}
async function removeGradePhoto(key){
  const v = gradeState[key]; if(!v || !v.ph) return;
  if(!confirmRemovePhoto()) return;
  await deleteOwnerPhoto(v.ph);
  delete v.ph;
  await saveGrade(key);
  reopenCurrentModal();
}
function confirmRemovePhoto(){ return window.confirm('Remove this photo?'); }

// ---- serialized cards (items with sx, e.g. T1 Serialized Signature Card)
function serialCardNames(item){ return String(item.serialCards || '').split('\n').map(s => s.trim()).filter(Boolean); }
function padSerial(n, max){ return String(n).padStart(String(max || n).length, '0'); }
function serialSectionHtml(item){
  if(!item.serialMax) return '';
  const max = item.serialMax, list = serialState[item.id] || [];
  const names = serialCardNames(item).length ? serialCardNames(item) : [item.name];
  const k = cssId(item.id);
  const rows = list.map((e, i) => {
    const pfx = `cbSerial_${k}_${i}`;
    window[pfx] = (field, value) => setSerialField(item.id, i, field, value);
    window[pfx + '_photo'] = input => addSerialPhoto(item.id, i, input);
    window[pfx + '_photodel'] = () => removeSerialPhoto(item.id, i);
    return `<div class="gr-item serial-item">
      <div class="serial-head"><span><b>#${padSerial(e.n, max)}</b>&nbsp;/&nbsp;${max} &middot; ${escapeHtml(names[e.c] || 'Card')}</span>
        <button type="button" class="serial-del" onclick="removeSerial('${item.id}', ${i})">Remove</button></div>
      ${gradeControlsHtml(e, pfx, pfx + '_photo', pfx + '_photodel', '')}
    </div>`;
  }).join('');
  return `<div class="grade-box serial-box">
    <div class="grade-title">${names.length > 1 ? 'Your serialized cards' : 'Your numbered copies'}</div>
    ${item.serialNote ? `<div class="serial-how"><b>How it works:</b> ${escapeHtml(item.serialNote)}</div>` : ''}
    ${(names.length > 1 ? rows : rows.replace(/Add your photo/g, 'Add certificate photo')) || `<div class="serial-empty">${names.length > 1 ? 'None listed yet. Add the serialized card you own below.' : 'None listed yet. Add the number on yours below, then upload a photo of its certificate.'}</div>`}
    <div class="serial-add">
      <select id="serialCard-${k}" class="gr-sel" aria-label="Which card"${names.length > 1 ? '' : ' hidden'}>${names.map((n, i) => `<option value="${i}">${escapeHtml(n)}</option>`).join('')}</select>
      <input id="serialNum-${k}" class="gr-cert serial-num" type="number" inputmode="numeric" min="1" max="${max}" placeholder="Serial # (1-${max})" list="serialList-${k}" aria-label="Serial number">
      <datalist id="serialList-${k}">${Array.from({ length: max }, (_, i) => `<option value="${i + 1}">`).join('')}</datalist>
      <button type="button" class="serial-add-btn" onclick="addSerial('${item.id}')">Add</button>
      <span class="serial-msg" id="serialMsg-${k}"></span>
    </div>
  </div>`;
}
async function addSerial(promoId){
  const item = ITEMS.find(i => i.id === promoId); if(!item) return;
  const k = cssId(promoId);
  const n = parseInt((document.getElementById('serialNum-' + k) || {}).value, 10);
  const c = parseInt((document.getElementById('serialCard-' + k) || {}).value, 10) || 0;
  const msg = document.getElementById('serialMsg-' + k);
  if(!(n >= 1 && n <= item.serialMax)){ if(msg) msg.textContent = `Enter a number from 1 to ${item.serialMax}.`; return; }
  const list = serialState[promoId] || [];
  if(list.some(e => e.c === c && e.n === n)){ if(msg) msg.textContent = 'That one is already listed.'; return; }
  if(!list.length && !state.owned[promoId] && !canAddMoreItems(true)) return;
  list.push({ c, n }); serialState[promoId] = list;
  await saveSerials(promoId);
  reopenCurrentModal();
}
async function removeSerial(promoId, i){
  const list = serialState[promoId] || []; const e = list[i]; if(!e) return;
  if(!window.confirm(`Remove #${e.n} from your list?`)) return;
  if(e.ph) await deleteOwnerPhoto(e.ph);
  list.splice(i, 1); serialState[promoId] = list;
  await saveSerials(promoId);
  reopenCurrentModal();
}
async function setSerialField(promoId, i, field, value){
  const e = (serialState[promoId] || [])[i]; if(!e) return;
  e[field] = value;
  if(field === 's'){ if(!value){ delete e.s; delete e.by; delete e.g; delete e.cert; } else if(value === 'submitted') delete e.g; }
  await saveSerials(promoId);
  if(field === 's') reopenCurrentModal();
}
async function addSerialPhoto(promoId, i, input){
  const e = (serialState[promoId] || [])[i]; if(!e) return;
  const path = await uploadOwnerPhoto(input && input.files && input.files[0]); if(!path) return;
  e.ph = path; await saveSerials(promoId); reopenCurrentModal();
}
async function removeSerialPhoto(promoId, i){
  const e = (serialState[promoId] || [])[i]; if(!e || !e.ph) return;
  if(!confirmRemovePhoto()) return;
  await deleteOwnerPhoto(e.ph); delete e.ph; await saveSerials(promoId); reopenCurrentModal();
}

// ---- owner photos (private Supabase Storage)
const photoUrlCache = new Map();
async function shrinkImage(file){
  const url = URL.createObjectURL(file);
  try{
    const img = await new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = url; });
    const scale = Math.min(1, 1600 / Math.max(img.naturalWidth, img.naturalHeight));
    const cv = document.createElement('canvas');
    cv.width = Math.round(img.naturalWidth * scale); cv.height = Math.round(img.naturalHeight * scale);
    cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
    return await new Promise(res => cv.toBlob(res, 'image/jpeg', 0.85));
  } finally { URL.revokeObjectURL(url); }
}
async function uploadOwnerPhoto(file){
  if(!file) return null;
  if(!sb || !currentUser){ alert('Sign in to add photos of your cards.'); return null; }
  if(!/^image\//.test(file.type)){ alert('Please choose a picture (JPG, PNG or WEBP).'); return null; }
  if(file.size > 20 * 1024 * 1024){ alert('That picture is too large. Please use one under 20 MB.'); return null; }
  try{
    setSyncStatus('Uploading photo…');
    const blob = await shrinkImage(file);
    const path = `${currentUser.id}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.jpg`;
    const { error } = await sb.storage.from(PHOTO_BUCKET).upload(path, blob, { contentType: 'image/jpeg', upsert: false });
    if(error){ console.error('photo upload failed', error); setSyncStatus('Photo upload failed'); alert("Your photo couldn't be uploaded. Please try again."); return null; }
    setSyncStatus('Photo saved'); setTimeout(() => setSyncStatus(''), 1500);
    return path;
  }catch(e){ console.error(e); setSyncStatus(''); alert("Your photo couldn't be uploaded. Please try again."); return null; }
}
async function deleteOwnerPhoto(path){
  if(!sb || !currentUser || !path) return;
  try{ await sb.storage.from(PHOTO_BUCKET).remove([path]); }catch(e){}
  photoUrlCache.delete(path);
}
async function ownerPhotoUrl(path){
  const c = photoUrlCache.get(path);
  if(c && c.exp > Date.now()) return c.url;
  if(!sb || !currentUser) return '';
  const { data, error } = await sb.storage.from(PHOTO_BUCKET).createSignedUrl(path, 3600);
  if(error || !data) return '';
  photoUrlCache.set(path, { url: data.signedUrl, exp: Date.now() + 50 * 60 * 1000 });
  return data.signedUrl;
}
function hydrateOwnerPhotos(root){
  (root || document).querySelectorAll('img[data-photo-path]').forEach(async img => {
    const u = await ownerPhotoUrl(img.getAttribute('data-photo-path'));
    if(u) img.src = u; else img.closest('.gr-photo') && img.closest('.gr-photo').classList.add('gr-photo-missing');
  });
}
function openOwnerPhoto(img){ if(img && img.src) window.open(img.src, '_blank', 'noopener'); }

/* ---------- Tournament play (ban list) ----------
   tracker-data/legality.json lists Riot's bans. Cards match by SET-number so
   every language and printing shares a status; card promos match by name. */
let LEGALITY = null;
function loadLegality(){
  return fetch(ghUrl('tracker-data/legality.json')).then(r => r.ok ? r.json() : null).then(d => {
    if(!d) return;
    const byKey = new Map(), byName = new Map();
    (d.banned || []).forEach(b => {
      (b.cards || []).forEach(k => {
        const i = k.indexOf('-');
        byKey.set(k.slice(0,i).toUpperCase() + '-' + String(k.slice(i+1)).toLowerCase().replace(/^0+(?=\d)/,''), b);
      });
      byName.set(csvNorm(b.name), b);
    });
    LEGALITY = { byKey, byName, formats: d.formats || ['Standard','2v2'], updated: d.updated };
    if(typeof renderSetAll === 'function') renderSetAll();
    refreshBinderIfVisible();
  }).catch(e => console.warn('[Collection-Bound] legality failed', e));
}
function legalityOf(x, kind){
  if(!LEGALITY) return null;
  if(kind === 'card'){
    if(isTokenCard(x)) return { status:'token' };
    const b = LEGALITY.byKey.get(String(x.setCode).toUpperCase() + '-' + String(x.collectorNum||'').toLowerCase().replace(/^0+(?=\d)/,''));
    return b ? { status:'banned', ban:b } : { status:'legal' };
  }
  if(x.itemType !== 'Card') return null;          // collectibles aren't played
  const base = csvNorm(String(x.name||'').split(/\[|\(/)[0].replace(/\s[-–]\s/, ' '));
  const b = LEGALITY.byName.get(base);
  return b ? { status:'banned', ban:b } : { status:'legal' };
}
function isBannedEverywhere(card){
  const l = legalityOf(card, 'card');
  return !!card.banned || !!(l && l.status === 'banned' && l.ban.formats.includes('Standard'));
}
function legalityHtml(x, kind){
  const l = legalityOf(x, kind);
  if(!l) return LEGALITY ? '&mdash;' : '<span class="lg-dim">Checking&hellip;</span>';
  if(l.status === 'token') return '<span class="lg-dim">Token &middot; not a deck card</span>';
  const fmts = LEGALITY.formats;
  if(l.status === 'legal') return `<span class="lg lg-ok">&#10003; Legal</span> <span class="lg-dim">${fmts.join(' &amp; ')}</span>`;
  const banned = l.ban.formats, legalIn = fmts.filter(f => !banned.includes(f));
  const since = l.ban.since ? new Date(l.ban.since+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) : '';
  return `${legalIn.length ? `<span class="lg lg-ok">&#10003; Legal</span> <span class="lg-dim">${legalIn.join(' &amp; ')}</span><br>` : ''}<span class="lg lg-ban">&#10005; Banned</span> <span class="lg-dim">${banned.join(' &amp; ')}${since ? ' &middot; since '+since : ''}</span>`;
}

/* ---------- One-time patch notice: Unleashed Chinese IDs (Nov 9, 2026) ----------
   Until this fix, Unleashed Chinese cards shared IDs with Origins Chinese
   (card-41000 to card-41302), so a check on one showed on both. Anyone whose
   collection has checks in that range sees this note once, so they can
   re-check their Unleashed Chinese cards. Stops showing after Jan 31, 2027. */
const UNL_ZH_NOTICE_KEY = 'cb_notice_unl_zh_ids_2026_11';
function unlZhAffectedCount(){
  return Object.keys(setState.owned || {}).filter(id => {
    const m = /^card-41(\d{3})$/.exec(id);
    if(!m || +m[1] > 302) return false;
    const o = setState.owned[id];
    return !!(o && (o.Normal || o.Foil));
  }).length;
}
function maybeShowUnlZhNotice(){
  try{ if(localStorage.getItem(UNL_ZH_NOTICE_KEY)) return; }catch(e){ return; }
  if(Date.now() > Date.UTC(2027, 0, 31)) return;
  if(document.getElementById('unlZhNotice')) return;
  const n = unlZhAffectedCount();
  if(!n) return;
  const box = document.createElement('div');
  box.id = 'unlZhNotice';
  box.className = 'patch-notice-backdrop';
  box.innerHTML = `
    <div class="patch-notice" role="dialog" aria-modal="true" aria-labelledby="unlZhTitle">
      <div class="patch-notice-tag">Tracker update &middot; Nov 9, 2026</div>
      <h3 id="unlZhTitle">Please re-check your Unleashed Chinese cards</h3>
      <p>We fixed a mix-up where <b>Origins Chinese</b> and <b>Unleashed Chinese</b> cards shared check marks, so checking one also checked the other.</p>
      <p>Your checks were kept, but they now count as <b>Origins Chinese</b> (${n} card${n === 1 ? '' : 's'} in your collection). If any of those were really Unleashed Chinese cards, please check them in Unleashed Chinese and uncheck them in Origins Chinese.</p>
      <div class="patch-notice-actions">
        <button type="button" class="pn-primary" onclick="closeUnlZhNotice(true)">Show my Origins Chinese cards</button>
        <button type="button" class="pn-secondary" onclick="closeUnlZhNotice(false)">Got it</button>
      </div>
    </div>`;
  (document.getElementById('collectBoundApp') || document.body).appendChild(box);
}
function closeUnlZhNotice(show){
  try{ localStorage.setItem(UNL_ZH_NOTICE_KEY, '1'); }catch(e){}
  const el = document.getElementById('unlZhNotice'); if(el) el.remove();
  if(!show) return;
  try{
    switchTab('tabSetBtn');
    setState.set = 'OGN'; setState.language = 'Chinese';
    const a = document.getElementById('setSetFilter'); if(a) a.value = 'OGN';
    const b = document.getElementById('setLanguageFilter'); if(b) b.value = 'Chinese';
    renderSetAll();
  }catch(e){}
}

/* ---------- Rising / cooling badges ----------
   From get-price-history 'trends': anything on TCGplayer (cards, promos, sealed
   products) whose market price moved 15%+ over 7 days ($1 and up). Price
   momentum, not sales counts. Promos use tracker-data/promo-tcg.json to know
   their TCGplayer listing; products use their own TCGplayer id (tp). */
let TRENDS = null, TRENDS_BY_ID = null, PROMO_TCG = null, CT_TRENDS = null;
function loadTrends(){
  if(!MEMBERSHIP_ENABLED || typeof sb === 'undefined' || !sb) return;
  const links = fetch(ghUrl('tracker-data/promo-tcg.json')).then(r => r.ok ? r.json() : null).catch(() => null);
  sb.functions.invoke(HISTORY_FUNCTION, { body:{ mode:'trends' } }).then(async r => {
    if(r.error || !r.data) return;
    const map = new Map();
    (r.data.rising || []).forEach(x => map.set(x.k, { dir:'up', pct:x.pct }));
    (r.data.cooling || []).forEach(x => map.set(x.k, { dir:'down', pct:x.pct }));
    TRENDS = map;
    const byId = new Map();
    (r.data.items || []).forEach(x => byId.set(String(x.p), { dir: x.d === 'up' ? 'up' : 'down', pct: x.pct }));
    TRENDS_BY_ID = byId;
    CT_TRENDS = new Map((r.data.ct || []).map(x => [x.k, { dir: x.d === 'up' ? 'up' : 'down', pct: x.pct, src:'CardTrader lowest listing' }]));
    const l = await links;
    PROMO_TCG = (l && l.links) || {};
    if(typeof renderSetAll === 'function') renderSetAll();
    if(typeof renderAll === 'function' && ITEMS.length) renderAll();
    if(typeof renderProductResults === 'function') renderProductResults();
    refreshBinderIfVisible();
  }).catch(e => console.warn('[Collection-Bound] trends failed', e));
}
function trendPillHtml(t){
  if(!t) return '';
  return t.dir === 'up'
    ? `<span class="trend-pill hot" title="Price up ${t.pct}% in the last 7 days (${t.src || 'TCGplayer market'})">&#128293; Rising</span>`
    : `<span class="trend-pill cold" title="Price down ${Math.abs(t.pct)}% in the last 7 days (${t.src || 'TCGplayer market'})">&#10052;&#65039; Cooling</span>`;
}
// Promos & Collectibles (English promos linked to a TCGplayer listing)
function promoTrendBadgeHtml(item){
  if(!TRENDS_BY_ID || !PROMO_TCG || !item || !item.id) return '';
  const pid = PROMO_TCG[item.id];
  return pid ? trendPillHtml(TRENDS_BY_ID.get(String(pid))) : '';
}
// Products (sealed product with a TCGplayer id)
function productTrendBadgeHtml(p){
  if(!TRENDS_BY_ID || !p || !p.tp) return '';
  return trendPillHtml(TRENDS_BY_ID.get(String(p.tp)));
}
function trendOf(card){
  if(card.language !== 'English'){
    if(!CT_TRENDS || !CT_TRENDS.size) return null;
    const b = card.language + '|' + String(card.setCode||'').toUpperCase() + '|' + String(card.collectorNum||'').toLowerCase().replace(/^0+(?=\d)/,'') + '|';
    const h = ['normal','foil'].map(p => CT_TRENDS.get(b + p)).filter(Boolean);
    return h.length ? h.sort((x,y) => Math.abs(y.pct) - Math.abs(x.pct))[0] : null;
  }
  if(!TRENDS) return null;
  const base = card.setCode + '|' + String(card.collectorNum||'').toLowerCase().replace(/^0+(?=\d)/,'') + '|';
  const hits = card.printings.map(pr => TRENDS.get(base + pr.toLowerCase())).filter(Boolean);
  if(!hits.length) return null;
  return hits.sort((a,b) => Math.abs(b.pct) - Math.abs(a.pct))[0];
}
function trendOverlayHtml(pillHtml){
  return pillHtml ? pillHtml.replace('class="trend-pill ','class="trend-pill trend-overlay ') : '';
}
function trendBadgeHtml(card){
  return trendPillHtml(trendOf(card));
}

/* ---------- International check (VIP, English cards) ----------
   Shows the same card's lowest CardTrader listing in each language next to the
   US price, and flags when another language is much cheaper, because every
   official language can be played. */
const CT_LANG_NAME = { en:'English', fr:'French', 'zh-cn':'Chinese', kr:'Korean' };
async function loadInternational(body){
  const box = () => document.getElementById('cbIntl');
  if(!box() || !sb || !isVipTier()) return;
  const key = body.card_id + '|' + body.printing;
  let res;
  try{
    const [intl, cur] = await Promise.all([
      sb.functions.invoke(HISTORY_FUNCTION, { body:{ mode:'international', set_code: body.set_code, collector_number: body.collector_number } }),
      sb.functions.invoke(HISTORY_FUNCTION, { body:{ mode:'current', set_code: body.set_code, collector_number: body.collector_number, card_name: body.card_name, card_language:'English', printing: body.printing } })
    ]);
    res = { intl: intl.data || {}, cur: cur.data || {} };
  }catch(e){ console.warn('[Collection-Bound] international failed', e); return; }
  if(!box() || priceSel.printing !== body.printing || priceSel.cardId !== body.card_id) return;
  const intl = res.intl;
  if(intl.status !== 'ok' || !(intl.prices||[]).length){ box().remove(); return; }
  const wantFoil = body.printing === 'Foil', foilOnly = !!body.foil_only;
  const best = new Map();
  intl.prices.forEach(p => {
    if(!foilOnly && p.foil !== wantFoil) return;
    const name = CT_LANG_NAME[p.language]; if(!name) return;
    if(!best.has(name) || p.low < best.get(name).low) best.set(name, p);
  });
  if(!best.size){ box().remove(); return; }
  const us = res.cur && res.cur.status === 'ok' ? Number(res.cur.market) : null;
  const rows = [...best.entries()].sort((a,b) => LANG_ORDER.indexOf(a[0]) - LANG_ORDER.indexOf(b[0]))
    .map(([name, p]) => `<div class="intl-row">${langFlagHtml(name)}<span>${escapeHtml(name)}</span><b>${escapeHtml(displayMoney(p.low))}</b><span class="lg-dim">${p.listings} listing${p.listings===1?'':'s'}</span></div>`).join('');
  let tip = '';
  const others = [...best.entries()].filter(([n]) => n !== 'English').sort((a,b) => a[1].low - b[1].low);
  if(us && us >= 5 && others.length && others[0][1].low <= us * 0.7){
    const [name, p] = others[0];
    const pct = Math.round((1 - p.low / us) * 100);
    tip = `<div class="intl-tip">&#128161; <b>Before you pay the US price:</b> the ${escapeHtml(name)} printing's lowest listing is ${escapeHtml(displayMoney(p.low))}, ${pct}% under the US market price of ${escapeHtml(displayMoney(us))}. Official printings in every language can be played in tournament decks, as long as your sleeves keep them from being told apart.</div>`;
  }
  box().innerHTML = `<div class="cbp-k" style="margin-bottom:6px;">&#127757; Same card in other languages</div>${tip}<div class="intl-rows">${rows}</div>
    <div class="cbp-meta">Lowest Near Mint ${escapeHtml(printingLabel(body.printing))} listing on CardTrader per language &middot; ${escapeHtml(intl.day)}. Asking prices, not sold prices.</div>`;
}

/* ---------- Set completion ----------
   Per set + language:
   - Base set: every main card (plain number, no alternate art / overnumber /
     signature / showcase), any printing.
   - Master set: every card in the set except tokens (alternate arts,
     overnumbers, signatures, runes...), in every printing it comes in. */
function isBaseSetCard(c){
  if(isTokenCard(c)) return false;
  const n = String(c.collectorNum||'').trim();
  if(!/^\d+$/.test(n)) return false;
  return !/showcase|overnumber|signature|ultimate/i.test(String(c.rarity||''));
}
function setCompletion(){
  const groups = new Map();
  CARDS.forEach(c => {
    if(isTokenCard(c)) return;
    const k = c.setCode + '|' + c.language;
    if(!groups.has(k)) groups.set(k, { set:c.setCode, lang:c.language, base:[0,0], master:[0,0], any:false });
    const g = groups.get(k);
    const ownedAny = cardEffectiveOwned(c);
    if(ownedAny) g.any = true;
    if(isBaseSetCard(c)){ g.base[1]++; if(ownedAny) g.base[0]++; }
    c.printings.forEach(pr => { g.master[1]++; if(getCardOwned(c.id, pr) || getCardQty(c.id, pr) > 0) g.master[0]++; });
  });
  return [...groups.values()].filter(g => g.any)
    .sort((a,b) => (SET_RELEASE_ORDER.indexOf(a.set) - SET_RELEASE_ORDER.indexOf(b.set)) || (LANG_ORDER.indexOf(a.lang) - LANG_ORDER.indexOf(b.lang)));
}
function renderSetCompletion(){
  const el = document.getElementById('binderSetDone');
  if(!el) return;
  const list = setCompletion();
  const name = g => `${escapeHtml(CARD_SET_NAMES[g.set] || g.set)} <span class="sc-lang">${escapeHtml(g.lang)}</span>`;
  const masters = list.filter(g => g.master[1] && g.master[0] >= g.master[1]);
  const bases = list.filter(g => g.base[1] && g.base[0] >= g.base[1] && !masters.includes(g));
  const banners = [
    ...masters.map(g => `<div class="sc-banner sc-master"><span class="sc-icon">&#127942;</span><div><div class="sc-title">Master set complete: ${name(g)}</div><div class="sc-sub">Every card and every printing, ${g.master[1]} in all. Legendary.</div></div></div>`),
    ...bases.map(g => `<div class="sc-banner sc-base"><span class="sc-icon">&#9989;</span><div><div class="sc-title">Base set complete: ${name(g)}</div><div class="sc-sub">${g.master[1] - g.master[0]} more for the master set (alternate arts, overnumbers, signatures and foils).</div></div></div>`)
  ].join('');
  const bar = (a, b) => `<span class="sc-bar"><i style="width:${b ? Math.round(a/b*100) : 0}%"></i></span>`;
  const pct = (a, b) => b ? Math.round(a/b*100) : 0;
  let open = false; try{ open = localStorage.getItem('cb_setprog_open') === '1'; }catch(e){}
  const progress = list.length ? `<details class="sc-progress"${open ? ' open' : ''} ontoggle="try{localStorage.setItem('cb_setprog_open', this.open ? '1' : '0')}catch(e){}">
    <summary><span class="sc-chev" aria-hidden="true">&#9654;</span><span class="sc-sum-title">&#128202; Set progress</span><span class="sc-sum-count">${list.length} set${list.length===1?'':'s'}</span><span class="sc-sum-hint"><span class="sc-show">Tap to show</span><span class="sc-hide">Tap to hide</span></span></summary>
    <div class="sc-cards">${list.map(g => `
      <div class="sc-card"><div class="sc-name">${name(g)}</div>
        <div class="sc-line"><span class="sc-k">Base</span><b>${pct(g.base[0], g.base[1])}%</b></div>${bar(g.base[0], g.base[1])}<div class="sc-n">${g.base[0]} / ${g.base[1]}</div>
        <div class="sc-line"><span class="sc-k">Master</span><b>${pct(g.master[0], g.master[1])}%</b></div>${bar(g.master[0], g.master[1])}<div class="sc-n">${g.master[0]} / ${g.master[1]}</div>
      </div>`).join('')}</div></details>` : '';
  el.innerHTML = banners + progress;
}

function getOwnedPromos(){
  return ITEMS.filter(i => !!state.owned[i.id]);
}
function getOwnedCards(){
  return CARDS.filter(c => cardEffectiveOwned(c));
}
function matchesBinderSearch(name){
  const q = binderState.search.trim().toLowerCase();
  if(!q) return true;
  return (name||'').toLowerCase().includes(q);
}

function getOwnedProducts(){
  return (typeof PRODUCTS !== 'undefined' ? PRODUCTS : []).filter(p => !p.pl && productOwned(p));
}
// Totals for My Binder, shown in the side panel and above the binder.
// Language / Metal / Nexus Night / Foil chips filter the binder when clicked.
function binderTotals(){
  const promos = getOwnedPromos(), cards = getOwnedCards(), prods = getOwnedProducts();
  const all = [...promos, ...cards, ...prods];
  const langs = ['English','Chinese','French','Korean'];
  const byLang = langs.map(l => ({ label:l, n: all.filter(x => x.language === l).length, kind:'lang', value:l }));
  const foil = cards.filter(c => getCardOwned(c.id, 'Foil')).length;
  return {
    promos: promos.length, cards: cards.length, prods: prods.length, total: all.length,
    chips: [
      ...byLang,
      { label:'Foil cards', n: foil, kind:'special', value:'foil' },
      { label:'Metal', n: promos.filter(i => i.metal).length, kind:'special', value:'metal' },
      { label:'Nexus Night', n: promos.filter(i => i.nexusNight).length, kind:'special', value:'nexusNight' }
    ]
  };
}
function binderChipHtml(c){
  const active = (c.kind === 'lang' ? binderState.lang : binderState.special) === c.value;
  return `<button type="button" class="breakdown-chip chip-link${active?' is-active':''}" aria-pressed="${active}"
      title="${active ? 'Show everything again' : 'Show only ' + escapeHtml(c.label)}" onclick="filterBinderByChip('${c.kind}','${escapeHtml(c.value)}')">
      <span class="bc-label">${escapeHtml(c.label)}</span><span class="bc-count">${c.n}</span></button>`;
}
function filterBinderByChip(kind, value){
  if(kind === 'lang') binderState.lang = binderState.lang === value ? '' : value;
  else binderState.special = binderState.special === value ? '' : value;
  renderBinder();
}
function renderBinderStats(){
  const t = binderTotals();
  const statBlocks = `
    <div class="stat total"><div class="n">${t.total}</div><div class="l">Total in binder</div></div>
    <div class="stat have"><div class="n">${t.cards}</div><div class="l">Card Sets</div></div>
    <div class="stat have"><div class="n">${t.promos}</div><div class="l">Promos &amp; Collectibles</div></div>
    <div class="stat have"><div class="n">${t.prods}</div><div class="l">Products</div></div>`;
  const chips = `<div class="stat-breakdown">${t.chips.filter(c => c.n || c.kind === 'lang').map(binderChipHtml).join('')}</div>`;
  const bar = document.getElementById('binderStatsBar');
  if(bar) bar.innerHTML = statBlocks + chips;
  const main = document.getElementById('binderTotalsMain');
  if(main) main.innerHTML = t.total ? `<div class="bt-stats">${statBlocks}</div>${chips}` : '';
}


/* =========================================================
   Wishlist, price paid and version (print run)
   ---------------------------------------------------------
   Saved locally as extra:<key>, and in the cloud copy as data.extras.
   key = 'promo:<id>' | 'card:<id>' | 'prod:<id>' (wishlist, version) and
   'card:<id>:<Normal|Foil>' for what was paid for a card printing.
   { w:1 } on the wishlist · { v:'Second Print' } version owned
   { p:12.5, d:'2026-05-21' } price paid per copy in USD, date bought
   ========================================================= */
let extraState = {};
function cleanExtra(v){
  if(!v || typeof v !== 'object') return null;
  const o = {};
  if(v.w) o.w = 1;
  if(v.v) o.v = String(v.v).slice(0, 40);
  if(v.p !== undefined && v.p !== null && v.p !== ''){ const p = parseFloat(v.p); if(p >= 0 && p < 1e7) o.p = Math.round(p * 100) / 100; }
  if(v.d && /^\d{4}-\d{2}-\d{2}$/.test(v.d)) o.d = v.d;
  return Object.keys(o).length ? o : null;
}
async function loadExtras(){
  try{
    const r = await window.storage.list('extra:');
    const out = {};
    for(const k of (r && r.keys) || []){
      try{ const g = await window.storage.get(k, false); const v = cleanExtra(JSON.parse(g.value)); if(v) out[k.slice(6)] = v; }catch(e){}
    }
    extraState = out;
  }catch(e){}
}
function getExtra(key){
  const e = extraState[key] || {};
  if(e.v === 'First Run') return { ...e, v:'First Print' };
  if(e.v === 'Second Run') return { ...e, v:'Second Print' };
  return e;
}
async function setExtra(key, patch){
  const v = cleanExtra({ ...getExtra(key), ...patch });
  try{
    if(v){ extraState[key] = v; await window.storage.set('extra:' + key, JSON.stringify(v), false); }
    else { delete extraState[key]; await window.storage.delete('extra:' + key, false); }
  }catch(e){}
  queueCloudSave();
}

/* ---------- Wishlist ---------- */
function wishOn(key){ return !!getExtra(key).w; }
function wishHeartHtml(key){
  const on = wishOn(key);
  return `<button type="button" class="wish-heart${on ? ' on' : ''}" aria-pressed="${on}" title="${on ? 'On your wishlist (tap to remove)' : 'Add to your wishlist'}"
    onclick="event.stopPropagation(); toggleWish('${key}', this)">${on ? '&#9829;' : '&#9825;'}</button>`;
}
async function toggleWish(key, btn){
  const on = !wishOn(key);
  await setExtra(key, { w: on ? 1 : 0 });
  document.querySelectorAll('.wish-heart').forEach(b => {
    if(b.getAttribute('onclick') && b.getAttribute('onclick').includes(`'${key}'`)){
      b.classList.toggle('on', on); b.setAttribute('aria-pressed', on); b.innerHTML = on ? '&#9829;' : '&#9825;';
      b.title = on ? 'On your wishlist (tap to remove)' : 'Add to your wishlist';
    }
  });
  refreshBinderIfVisible();
}
function wishlistItems(){
  const promos = [], cards = [], prods = [];
  Object.entries(extraState).forEach(([key, v]) => {
    if(!v.w) return;
    const i = key.indexOf(':'), kind = key.slice(0, i), id = key.slice(i + 1);
    if(kind === 'promo'){ const x = ITEMS.find(it => it.id === id); if(x) promos.push(x); }
    else if(kind === 'card'){ const x = CARDS.find(c => c.id === id); if(x) cards.push(x); }
    else if(kind === 'prod' && typeof PRODUCTS !== 'undefined'){ const x = PRODUCTS.find(p => p.id === id); if(x) prods.push(x); }
  });
  return { promos, cards, prods, total: promos.length + cards.length + prods.length };
}

/* ---------- Versions (print runs) ----------
   Some sealed items came in more than one print run. Members pick the one
   they own in Details; a reference picture shows how to tell them apart. */
const ITEM_VERSIONS = {
  'promo:item-318': { label:'Print run', options:['First Print','Second Print'], ref:'promo-images/origins-case-print-run-differences-ref.webp',
    how:'Check the shipping label on the case. First-print cases have lot codes in the 5BA to 5BZ range; the January 2026 second print uses codes starting with 5C.' },
  'prod:prod-14-en': { label:'Print run', options:['First Print','Second Print'], ref:'promo-images/origins-case-print-run-differences-ref.webp',
    how:'Check the shipping label on the case. First-print cases have lot codes in the 5BA to 5BZ range; the January 2026 second print uses codes starting with 5C.' },
  'promo:item-314': { label:'Print run', options:['First Print','Second Print'],
    ref:'promo-images/proving-grounds-print-run-differences-ref.webp',
    how:'Look at the small print on the back panel, under riftbound.com. The second print uses a smaller font there. In the photo the barcode label also reads RB-01PG01-EN on the first print and RB-01PG02-EN on the second, and the Made-in line is different. The two prints also differ in card errata, and some first-print boxes had miscut cards that Riot replaced on request.' },
  'prod:prod-20-en': { label:'Print run', options:['First Print','Second Print'],
    ref:'promo-images/proving-grounds-print-run-differences-ref.webp',
    how:'Look at the small print on the back panel, under riftbound.com. The second print uses a smaller font there. In the photo the barcode label also reads RB-01PG01-EN on the first print and RB-01PG02-EN on the second, and the Made-in line is different. The two prints also differ in card errata, and some first-print boxes had miscut cards that Riot replaced on request.' }
};
// Every sealed product can have more than one print run, so Products always offer the picker.
const PRODUCT_PRINT_RUN_DEFAULT = { label:'Print run', options:['First Print','Second Print'],
  how:'Many sealed products had more than one print run. If you know which one yours is, pick it here so your binder keeps track.' };
function versionSectionHtml(key){
  let cfg = ITEM_VERSIONS[key];
  if(!cfg && /^prod:prod-20-/.test(key)) cfg = ITEM_VERSIONS['prod:prod-20-en'];
  if(!cfg && key.startsWith('prod:')) cfg = PRODUCT_PRINT_RUN_DEFAULT;
  if(!cfg) return '';
  const cur = getExtra(key).v || '';
  return `<div class="ver-box"><div class="qty-label">${escapeHtml(cfg.label)}: which one do you have?</div>
    <div class="ver-btns">${cfg.options.map(o => `<button type="button" class="ver-btn${o === cur ? ' on' : ''}" onclick="pickVersion('${key}', '${escapeHtml(o)}')">${escapeHtml(o)}</button>`).join('')}</div>
    <div class="ver-how">${escapeHtml(cfg.how)}</div>
    ${cfg.ref ? `<a class="ver-ref" href="${escapeHtml(ghUrl(cfg.ref))}" target="_blank" rel="noopener"><img src="${escapeHtml(ghUrl(cfg.ref))}" alt="How to tell the print runs apart" loading="lazy"/><span>Reference: how to tell them apart &#8599;</span></a>` : ''}</div>`;
}
async function pickVersion(key, v){
  await setExtra(key, { v: getExtra(key).v === v ? '' : v });
  reopenCurrentModal();
}

/* ---------- What you paid ---------- */
function paidSectionHtml(rows){
  // rows: [{ key, label }]
  if(!rows.length) return '';
  return `<div class="paid-box"><div class="qty-label">What you paid <span class="paid-sub">per copy, USD &middot; only you see this</span></div>
    ${rows.map(r => { const e = getExtra(r.key); return `<div class="paid-row">${r.label ? `<span class="paid-lbl">${escapeHtml(r.label)}</span>` : ''}
      <span class="paid-in">$<input type="number" min="0" step="0.01" inputmode="decimal" placeholder="0.00" value="${e.p !== undefined ? e.p : ''}" onchange="setExtra('${r.key}', { p: this.value })" aria-label="Price paid"></span>
      <input type="date" value="${e.d || ''}" onchange="setExtra('${r.key}', { d: this.value })" aria-label="Date bought"></div>`; }).join('')}</div>`;
}
// Binder value keys: cards 'id|Normal', products 'prod-…', promos 'promo:item-…'
function paidEntries(){
  const out = [];
  Object.entries(extraState).forEach(([key, v]) => {
    if(v.p === undefined) return;
    const parts = key.split(':');
    if(parts[0] === 'card' && parts.length === 3){ const qty = Math.max(1, getCardQty(parts[1], parts[2])); if(getCardOwned(parts[1], parts[2]) || getCardQty(parts[1], parts[2])) out.push({ key, bv: parts[1] + '|' + parts[2], id: parts[1], paid: v.p * qty }); }
    else if(parts[0] === 'promo'){ const id = parts.slice(1).join(':'); if(state.owned[id]) out.push({ key, bv: 'promo:' + id, id, paid: v.p * Math.max(1, getQty(id)) }); }
    else if(parts[0] === 'prod'){ const id = parts.slice(1).join(':'); if(productState.owned[id]) out.push({ key, bv: id, id, paid: v.p * Math.max(1, getProductQty(id)) }); }
  });
  return out;
}
// Return on one binder tile: arrow + % next to the title once both prices are known.
function returnBadgeHtml(bvKeys){
  if(!bvLast || !bvLast.items) return '';
  let paid = 0, now = 0, any = false;
  bvKeys.forEach(([extraKey, bvKey, qty]) => {
    const e = getExtra(extraKey), it = bvLast.items[bvKey];
    if(e.p === undefined || !it) return;
    paid += e.p * qty; now += it.unit * qty; any = true;
  });
  if(!any || paid <= 0) return '';
  const pct = (now - paid) / paid * 100;
  return `<span class="ret-pill ${pct >= 0 ? 'up' : 'down'}" title="Paid ${escapeHtml(displayMoney(paid))}, worth about ${escapeHtml(displayMoney(now))} now">${pct >= 0 ? '&#9650;' : '&#9660;'} ${Math.abs(pct).toFixed(0)}%</span>`;
}
function promoReturnBadge(item){ return returnBadgeHtml([['promo:' + item.id, 'promo:' + item.id, Math.max(1, getQty(item.id))]]); }
function cardReturnBadge(card){ return returnBadgeHtml(card.printings.map(pr => ['card:' + card.id + ':' + pr, card.id + '|' + pr, Math.max(1, getCardQty(card.id, pr))])); }
function productReturnBadge(p){ return returnBadgeHtml([['prod:' + p.id, p.id, Math.max(1, getProductQty(p.id))]]); }

/* ---------- Boxes that hold promos already on the list ----------
   Marking the box as owned also marks the cards inside it. If a card was
   already marked, we ask whether that's a second copy (same idea as the
   merged-promo question). */
const PROMO_BUNDLES = {
  'item-10604': ['item-82','item-79','item-80','item-78','item-83','item-81'],  // Arcane Collector Box (English)
  'item-10605': ['item-72','item-73','item-74','item-75','item-76','item-77'],  // Arcane Collector Box (Chinese)
  'item-10645': ['item-26','item-25','item-23','item-24'],  // Trial Decks Box RB-01DA01 (English): Jinx, Yasuo, Volibear, Viktor
  'item-10646': ['item-19','item-22','item-21','item-20']   // TCG Trial Deck Box FNT01-04 (Chinese)
};
async function applyBundle(boxId){
  const kids = PROMO_BUNDLES[boxId]; if(!kids) return;
  const ask = [];
  for(const id of kids){
    if(state.owned[id]){ ask.push(id); continue; }
    state.owned[id] = true; try{ await window.storage.set('owned:' + id, '1', false); }catch(e){}
    if(!state.qty[id]){ state.qty[id] = 1; try{ await window.storage.set('qty:' + id, '1', false); }catch(e){} }
  }
  queueCloudSave();
  if(ask.length) showBundleAsk(boxId, ask);
}
function showBundleAsk(boxId, ids){
  const box = ITEMS.find(i => i.id === boxId);
  const items = ids.map(id => ITEMS.find(i => i.id === id)).filter(Boolean);
  if(!items.length || document.getElementById('bundleNotice')) return;
  const el = document.createElement('div');
  el.id = 'bundleNotice'; el.className = 'patch-notice-backdrop';
  el.innerHTML = `
    <div class="patch-notice" role="dialog" aria-modal="true" aria-labelledby="bundleTitle">
      <div class="patch-notice-tag">Binder update</div>
      <h3 id="bundleTitle">Is this a second copy?</h3>
      <p>We marked the cards inside your <b>${escapeHtml(box ? box.name : 'box')}</b>. You already had ${items.length === 1 ? 'this card' : 'these cards'} checked off. If the box gave you an extra copy, tap <b>I have 2</b>.</p>
      <div class="merge-list">${items.map(i => `<div class="merge-row" id="bundleRow-${i.id}"><span>${escapeHtml(i.name)}</span>
        <span class="merge-btns"><button type="button" class="pn-secondary" onclick="answerBundle('${i.id}',0)">Just 1</button><button type="button" class="pn-primary" onclick="answerBundle('${i.id}',1)">I have 2</button></span></div>`).join('')}</div>
    </div>`;
  (document.getElementById('collectBoundApp') || document.body).appendChild(el);
}
async function answerBundle(id, extra){
  if(extra) await setQty(id, Math.max(getQty(id), 1) + 1);
  const row = document.getElementById('bundleRow-' + id); if(row) row.remove();
  const el = document.getElementById('bundleNotice');
  if(el && !el.querySelector('.merge-row')) el.remove();
  renderAll(); refreshBinderIfVisible();
}

/* ---------- Back to top ---------- */
(function(){
  const b = document.createElement('button');
  b.type = 'button'; b.id = 'cbTopBtn'; b.className = 'cb-top-btn'; b.setAttribute('aria-label', 'Back to top');
  b.innerHTML = '<svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><path d="M6 10V2M2.5 5.5 6 2l3.5 3.5" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg><span>Top</span>';
  b.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
  (document.getElementById('collectBoundApp') || document.body).appendChild(b);
  const onScroll = () => b.classList.toggle('show', window.scrollY > 700);
  window.addEventListener('scroll', onScroll, { passive: true }); onScroll();
  // lift the Top button while the cookie banner is on screen
  // Find the cookie banner wherever it sits (any visible element near the bottom edge) and lift the Top button above it.
  const cookieCheck = () => {
    let lift = 0;
    document.querySelectorAll('[class*="cookie"]').forEach(el => {
      const r = el.getBoundingClientRect(), cs = getComputedStyle(el);
      if(r.height > 20 && r.width > 200 && cs.visibility !== 'hidden' && cs.display !== 'none' && r.bottom >= window.innerHeight - 4 && r.top > window.innerHeight * 0.4) lift = Math.max(lift, window.innerHeight - r.top);
    });
    document.body.classList.toggle('cb-cookie-open', lift > 0);
    b.style.bottom = lift > 0 ? (lift + 16) + 'px' : '';
  };
  cookieCheck(); setInterval(cookieCheck, 1500);
})();


function renderBinder(){
  setTimeout(maybeShowMergeNotice, 300);
  renderBinderStats();
  refreshBinderValue();
  renderSetCompletion();
  const container = document.getElementById('binderResults');
  if(!container) return;

  const langOk = x => !binderState.lang || x.language === binderState.lang;
  const sp = binderState.special;
  let promos = getOwnedPromos().filter(i=>matchesBinderSearch(i.name) && langOk(i));
  let cards = getOwnedCards().filter(c=>matchesBinderSearch(c.name) && langOk(c));
  let prods = getOwnedProducts().filter(p=>matchesBinderSearch(p.name) && langOk(p));
  if(sp === 'foil'){ promos = []; prods = []; cards = cards.filter(c => getCardOwned(c.id, 'Foil')); }
  if(sp === 'metal' || sp === 'nexusNight'){ cards = []; prods = []; promos = promos.filter(i => i[sp]); }
  if(binderState.kind === 'promo'){ cards = []; prods = []; }
  if(binderState.kind === 'card'){ promos = []; prods = []; }
  if(binderState.kind === 'product'){ promos = []; cards = []; }
  // Wishlist: what the member is still hunting for (tap the heart on any tile).
  let wl = { promos:[], cards:[], prods:[], total:0 };
  if(!sp && (binderState.kind === '' || binderState.kind === 'wish')){
    const w = wishlistItems();
    wl.promos = w.promos.filter(i=>matchesBinderSearch(i.name) && langOk(i));
    wl.cards = w.cards.filter(c=>matchesBinderSearch(c.name) && langOk(c));
    wl.prods = w.prods.filter(p=>matchesBinderSearch(p.name) && langOk(p));
    wl.total = wl.promos.length + wl.cards.length + wl.prods.length;
  }
  if(binderState.kind === 'wish'){ promos = []; cards = []; prods = []; }

  if(promos.length === 0 && cards.length === 0 && prods.length === 0 && wl.total === 0){
    if(binderState.kind === 'wish'){ container.innerHTML = `<div class="empty-state">Nothing on your wishlist yet. Tap the &#9825; on any card, promo or product you're hunting for and it shows up here.</div>`; return; }
    container.innerHTML = (binderState.lang || sp)
      ? `<div class="empty-state">Nothing in your binder matches that filter. Click the highlighted chip again to show everything.</div>`
      : `<div class="empty-state">Nothing marked as HAVE yet. Check items off in the other tabs and they'll show up here.</div>`;
    return;
  }

  let html = '';
  if(promos.length){
    html += `<div class="group-heading">Promos &amp; Collectibles <span class="count">${promos.length} item${promos.length!==1?'s':''}</span></div>`;
    html += `<div class="grid">${promos.map(cardHtml).join('')}</div>`;
  }
  if(cards.length){
    html += `<div class="group-heading">Card Sets <span class="count">${cards.length} item${cards.length!==1?'s':''}</span></div>`;
    html += `<div class="grid">${cards.map(cardTileHtml).join('')}</div>`;
  }
  if(prods.length){
    html += `<div class="group-heading">Products <span class="count">${prods.length} item${prods.length!==1?'s':''}</span></div>`;
    html += `<div class="grid">${prods.map(productCardHtml).join('')}</div>`;
  }
  if(wl.total){
    html += `<div class="group-heading wish-heading">&#9829; Wishlist <span class="count">${wl.total} item${wl.total!==1?'s':''}</span></div>`;
    html += `<div class="grid">${[...wl.promos.map(cardHtml), ...wl.cards.map(cardTileHtml), ...wl.prods.map(productCardHtml)].join('')}</div>`;
  }
  container.innerHTML = html;
}


/* ---------- Binder value ----------
   Free: one estimate for English cards + sealed products (TCGplayer market).
   Collector Club: every language (French/Chinese use the lowest CardTrader
   listing), split by tab, plus the change over the last week.
   VIP: adds value over time and the most valuable items.
   Promos and collectibles aren't priced yet, and every total says what it covers. */
let bvTimer = null, bvDays = 30, bvLast = null;
const bvCache = new Map();
function refreshBinderValue(){
  clearTimeout(bvTimer);
  bvTimer = setTimeout(loadBinderValue, 500);
}
function binderValueRequest(){
  const club = isPaidTier();
  const cards = [], products = [], ebay = [];
  CARDS.filter(cardEffectiveOwned).forEach(c=>{
    if(!club && c.language !== 'English') return;
    c.printings.forEach(pr=>{
      if(!getCardOwned(c.id, pr) && !getCardQty(c.id, pr)) return;
      cards.push({ k: c.id+'|'+pr, set_code: c.setCode, collector_number: c.collectorNum, card_name: c.name,
        card_language: c.language, printing: pr, qty: Math.max(1, getCardQty(c.id, pr)),
        foil_only: c.printings.length === 1 && c.printings[0] === 'Foil' });
    });
  });
  if(typeof PRODUCTS !== 'undefined') PRODUCTS.filter(productOwned).forEach(p=>{
    if(p.tp) products.push({ k: p.id, tp: p.tp, qty: Math.max(1, getProductQty(p.id)) });
    else if(!p.language || p.language === 'English') ebay.push({ k: p.id, kind:'prod', id: p.id, qty: Math.max(1, getProductQty(p.id)) });
  });
  // Promos & collectibles that have a TCGplayer listing (tracker-data/promo-tcg.json).
  if(PROMO_TCG) getOwnedPromos().forEach(i=>{
    const tp = PROMO_TCG[i.id];
    if(tp && (club || i.language === 'English')) products.push({ k: 'promo:' + i.id, tp, qty: Math.max(1, getQty(i.id)) });
    else if(!tp && isVipTier() && ebay.length < 80) ebay.push({ k: 'promo:' + i.id, kind:'promo', id: i.id, qty: Math.max(1, getQty(i.id)) });
  });
  return { cards, products, ebay };
}
const NOTE_HTML = ' <br><span style="opacity:.85">We only count items with a real, checked price from a trusted shop. If we can&#39;t find a trusted price (like for many promos, statues and plushes), we don&#39;t guess. It shows as &quot;not priced&quot; instead. Nobody can type in their own prices, so your total is always honest.</span>';
async function loadBinderValue(){
  const box = document.getElementById('binderValueBox');
  const panel = document.getElementById('binderPanel');
  if(!box) return;
  if(!MEMBERSHIP_ENABLED || !sb){ box.innerHTML = ''; return; }
  if(panel && panel.style.display === 'none') return;
  const req = binderValueRequest();
  const ownedCount = getOwnedCards().length + getOwnedPromos().length + getOwnedProducts().length;
  if(!req.cards.length && !req.products.length && !req.ebay.length){
    box.innerHTML = ownedCount ? `<div class="bv-box"><div class="bv-label">Binder value</div><div class="bv-meta">Nothing here has a price source yet.</div></div>` : '';
    return;
  }
  const tier = isVipTier() ? 'tier2' : isPaidTier() ? 'tier1' : 'free';
  const sig = tier + '|' + bvDays + '|' + JSON.stringify(req);
  let res = bvCache.get(sig);
  if(!res){
    if(!bvLast) box.innerHTML = `<div class="bv-box"><div class="bv-label">Binder value</div><div class="bv-meta">Adding up your binder…</div></div>`;
    try{
      const r = await sb.functions.invoke(HISTORY_FUNCTION, { body: { mode:'binder', days: bvDays, ...req } });
      if(r.error) throw r.error;
      res = r.data || {};
      bvCache.set(sig, res);
    }catch(e){ console.warn('[Collection-Bound] binder value failed', e); res = { error:true }; }
  }
  bvLast = res;
  const el = document.getElementById('binderValueBox'); if(el) el.innerHTML = binderValueHtml(res, req, ownedCount);
  // Tiles show a gain / loss arrow once prices are in: redraw them once per new price set.
  if(paidEntries().length && bvBadgeSig !== sig){ bvBadgeSig = sig; renderBinder(); }
}
let bvBadgeSig = '';
function setBinderDays(d){ bvDays = d; loadBinderValue(); }
function binderValueHtml(res, req, ownedCount){
  if(res.error) return `<div class="bv-box"><div class="bv-label">Binder value</div><div class="bv-meta">Binder value couldn't load right now.</div></div>`;
  const money = v => displayMoney(v);
  const items = res.items || {};
  let cardsVal = 0, prodVal = 0, promoVal = 0, promoPriced = 0, priced = 0;
  const lines = [];
  const cardKeys = new Set(req.cards.map(c=>c.k));
  Object.entries(items).forEach(([k, it])=>{
    const v = it.unit * it.qty; priced++;
    if(cardKeys.has(k)) cardsVal += v; else if(k.startsWith('promo:')){ promoVal += v; promoPriced++; } else prodVal += v;
    lines.push({ k, v, unit: it.unit, qty: it.qty, source: it.source });
  });
  const total = cardsVal + prodVal + promoVal;
  // Value by language: every language's cards, products and promos.
  const langOf = k => {
    if(k.startsWith('promo:')){ const it = ITEMS.find(x=>x.id===k.slice(6)); return it ? it.language : 'English'; }
    const id = k.split('|')[0];
    const c = CARDS.find(x=>x.id===id); if(c) return c.language;
    const pr = (typeof PRODUCTS !== 'undefined') ? PRODUCTS.find(x=>x.id===id) : null; return pr ? (pr.language || 'English') : 'English';
  };
  const BV_LANGS = ['English','Chinese','Korean','French'];
  const byLang = Object.fromEntries(BV_LANGS.map(l => [l, { v:0, n:0 }]));
  lines.forEach(l => { const g = byLang[langOf(l.k)] || byLang.English; g.v += l.v; g.n += l.qty; });
  const ownedLangs = new Set([...getOwnedCards().map(c=>c.language), ...getOwnedPromos().map(i=>i.language), ...getOwnedProducts().map(p=>p.language || 'English')]);
  const langRows = BV_LANGS.filter(l => ownedLangs.has(l) || byLang[l].v > 0).map(l =>
    `<div><span>${langFlagHtml(l)} ${escapeHtml(l)}</span><span>${byLang[l].v ? escapeHtml(money(byLang[l].v)) : '<small>not priced yet</small>'}</span></div>`).join('');
  const unpricedLangs = BV_LANGS.filter(l => l !== 'English' && ownedLangs.has(l) && !byLang[l].v);
  const langNote = unpricedLangs.length ? `<div class="bv-meta" style="margin-top:6px;">${unpricedLangs.join(' and ')} items show "not priced yet" because TCGplayer doesn't list them and no verified ${unpricedLangs.join('/')} price source exists. Only verified prices are counted, so nothing is estimated for them. They are not worth $0, they are just left out of the total.</div>` : '';
  // Your performance: what you paid vs what those items are worth now.
  let perf = '';
  const pe = paidEntries();
  if(pe.length){
    let paid = 0, now = 0, n = 0;
    pe.forEach(e => { const it = items[e.bv]; if(!it) return; paid += e.paid; now += it.unit * it.qty; n++; });
    if(n && paid > 0){
      const ch = now - paid, pct = ch / paid * 100;
      perf = `<div class="bv-perf"><div class="bv-label">Your performance</div>
        <div class="bv-rows"><div><span>You paid</span><span>${escapeHtml(money(paid))}</span></div><div><span>Worth now</span><span>${escapeHtml(money(now))}</span></div>
        <div><span>Return</span><span class="${ch>=0?'bv-up':'bv-down'}">${ch>=0?'&#9650;':'&#9660;'} ${escapeHtml(money(Math.abs(ch)))} (${pct>=0?'+':''}${pct.toFixed(1)}%)</span></div></div>
        <div class="bv-meta">${n} item${n===1?'':'s'} with both a price and what you paid. Add what you paid in any item's Details.</div></div>`;
    }
  }
  const want = req.cards.length + req.products.length + (req.ebay ? req.ebay.length : 0);
  const promoCount = getOwnedPromos().length;
  const upgrade = (tier, text) => `<a href="#" class="bv-tease" onclick="event.preventDefault(); openMembershipChooser('${tier}');">${text}</a>`;
  const day = res.day ? new Date(res.day+'T12:00:00').toLocaleDateString('en-US', { month:'short', day:'numeric' }) : '';
  const head = `${isPaidTier() ? `<div class="bv-cur">${currencyPickerHtml()}</div>` : ''}<div class="bv-label">Binder value (estimate)</div><div class="bv-total">${escapeHtml(money(total))}</div>${usdAside(total)}`;
  if(!isPaidTier()){
    return `<div class="bv-box bv-wide"><div class="bv-col">${head}
      <div class="bv-meta">English cards &amp; sealed products, Near Mint, TCGplayer market price${day ? ' &middot; '+escapeHtml(day) : ''}. ${priced} of ${want} priced.${NOTE_HTML}</div>
      ${perf}${upgrade('tier1', 'See every language, a breakdown, value tiers and your weekly change with the Collector Club &rarr;')}</div></div>`;
  }
  // change line
  const hist = res.history || [];
  let change = '';
  if(hist.length >= 2){
    const first = hist[0].value, last = hist[hist.length-1].value;
    const ch = last - first, pct = first ? (ch/first)*100 : 0;
    const label = isVipTier() ? `since ${new Date(hist[0].day+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}` : 'this week';
    change = `<div class="bv-meta"><span class="${ch>=0?'bv-up':'bv-down'}">${ch>=0?'&#9650;':'&#9660;'} ${escapeHtml(money(Math.abs(ch)))} (${pct.toFixed(1)}%)</span> ${label}, English cards &amp; products</div>`;
  }
  // value tiers (by each item's single-copy price)
  const TIERS = [
    { k:'chase', label:'Chase', range:'$100+', min:100 },
    { k:'high',  label:'High',  range:'$20 – 100', min:20 },
    { k:'mid',   label:'Mid',   range:'$5 – 20', min:5 },
    { k:'low',   label:'Low',   range:'$1 – 5', min:1 },
    { k:'bulk',  label:'Bulk',  range:'under $1', min:0 }
  ];
  const tierOf = u => TIERS.find(t => u >= t.min) || TIERS[TIERS.length-1];
  const tierAgg = TIERS.map(t => ({ ...t, n:0, v:0 }));
  lines.forEach(l => { const t = tierAgg.find(x => x.k === tierOf(l.unit).k); t.n += l.qty; t.v += l.v; });
  const tierHtml = `<div class="bv-label" style="margin-top:12px;">Value tiers</div>
    <div class="bv-tierbar">${tierAgg.filter(t=>t.v>0).map(t=>`<span class="tier-${t.k}" style="flex:${Math.max(t.v, total*0.02)}" title="${t.label}: ${escapeHtml(money(t.v))}"></span>`).join('')}</div>
    <div class="bv-tiers">${tierAgg.map(t=>`<div class="bv-tier"><i class="tier-${t.k}"></i><div><b>${t.label}</b> <span class="bv-tr">${t.range}</span><div class="bv-tr">${t.n} item${t.n===1?'':'s'} &middot; ${escapeHtml(money(t.v))}</div></div></div>`).join('')}</div>`;
  const left = `<div class="bv-col">${head}${change}
    ${langRows ? `<div class="bv-label" style="margin-top:10px;">By language</div><div class="bv-rows bv-lang-rows">${langRows}</div>${langNote}<div class="bv-label" style="margin-top:10px;">By tab</div>` : ''}
    <div class="bv-rows">
      <div><span>Card Sets</span><span>${escapeHtml(money(cardsVal))}</span></div>
      <div><span>Products</span><span>${escapeHtml(money(prodVal))}</span></div>
      ${promoCount ? `<div><span>Promos &amp; Collectibles</span><span>${promoPriced ? escapeHtml(money(promoVal)) + ` <small>(${promoPriced} of ${promoCount} priced)</small>` : 'not priced yet'}</span></div>` : ''}
    </div>${perf}
    <div class="bv-meta">${priced} of ${want} cards, products &amp; promos priced${day ? ' &middot; '+escapeHtml(day) : ''}. Near Mint. English uses TCGplayer market price; French &amp; Chinese use the lowest CardTrader listing.${lines.some(l=>l.source==='ebay') ? ' Items with no TCGplayer price use the lowest eBay asking price, which runs a bit above what they sell for.' : ''} Tiers use each item's single-copy price.${NOTE_HTML}</div>
    ${!isVipTier() ? upgrade('tier2', 'See your value over time and your most valuable cards with VIP &rarr;') : ''}</div>`;
  if(!isVipTier()) return `<div class="bv-box bv-wide">${left}<div class="bv-col">${tierHtml}</div></div>`;
  // One chart per language, side by side. English = TCGplayer market price (cards, products, promos);
  // Chinese, Korean and French = lowest CardTrader listing for your cards in that language.
  const hbl = res.history_by_lang || {};
  const chartFor = (lang, history, caption) => `<div class="bv-chart"><div class="bv-chart-lang">${langFlagHtml(lang)} ${escapeHtml(lang)}</div>
    <div class="cbp-trend" style="margin-top:0;padding-top:0;border:0;">${priceTrendHtml({ history }, bvDays, { field:'value', fn:'setBinderDays', title:'Value over time',
      empty: () => `<div class="cbp-meta">${ownedLangs.has(lang) ? 'This chart fills in as daily prices are saved.' : `No ${escapeHtml(lang)} items in your binder yet.`}</div>`,
      caption })}</div></div>`;
  const chart = `<div class="bv-charts">
    ${chartFor('English', hist, 'English cards, sealed products and promos, TCGplayer market price.')}
    ${chartFor('Chinese', hbl.Chinese || [], 'Chinese cards, lowest CardTrader listing.')}
    ${chartFor('Korean', hbl.Korean || [], 'Korean cards, lowest CardTrader listing.')}
    ${chartFor('French', hbl.French || [], 'French cards, lowest CardTrader listing.')}
  </div>`;
  const nameOf = k => {
    if(k.startsWith('promo:')){ const it = ITEMS.find(x=>x.id===k.slice(6)); return { id: k.slice(6), name: it ? it.name + ' · ' + it.language : k }; }
    const [id, pr] = k.split('|');
    const c = CARDS.find(x=>x.id===id); if(c) return { id, name: cardDisplayName(c) + (pr === 'Foil' && c.printings.length > 1 ? ' (Foil)' : '') + ' · ' + c.language };
    const p = (typeof PRODUCTS !== 'undefined') ? PRODUCTS.find(x=>x.id===id) : null; return p ? { id, name: p.name } : { id, name: id };
  };
  const top = lines.sort((a,b)=>b.v-a.v).slice(0, 10).map(l=>{ const n = nameOf(l.k);
    return `<button type="button" onclick="openModal('${escapeHtml(n.id)}')"><span>${escapeHtml(n.name)}${l.qty>1?' &times;'+l.qty:''}</span><span>${escapeHtml(money(l.v))}</span></button>`; }).join('');
  return `<div class="bv-box bv-wide">${left}<div class="bv-col">${tierHtml}</div>
    <div class="bv-full">${chart}${top ? `<div class="bv-label" style="margin-top:12px;">Most valuable</div><div class="bv-top bv-top-2col">${top}</div>` : ''}</div></div>`;
}


function refreshBinderIfVisible(){
  const panel = document.getElementById('binderPanel');
  if(panel && panel.style.display !== 'none') renderBinder();
  if(typeof refreshExtraTabsIfVisible === 'function') refreshExtraTabsIfVisible();
}

