async function toggleOwned(id){
  const next = !state.owned[id];
  if(next && !canAddMoreItems(true)) return;
  state.owned[id] = next;
  try{
    await window.storage.set('owned:'+id, next ? '1':'0', false);
  }catch(e){}
  if(next && PROMO_BUNDLES[id]) await applyBundle(id);
  renderAll();
  if(typeof PRODUCTS !== 'undefined' && PRODUCTS.some(p=>p.pl===id) && typeof renderProductAll === 'function') renderProductAll();
  refreshBinderIfVisible();
  queueCloudSave();
}

async function markAllOwned(){
  if(promoDetailsLocked()) return;
  const remaining = ITEMS.filter(it=>!state.owned[it.id]).length;
  if(remaining === 0){
    alert('Every item is already marked as HAVE.');
    return;
  }

  const limit = getTierLimit();
  let toMark = ITEMS.filter(it=>!state.owned[it.id]);
  let cappedNote = '';
  if(limit !== Infinity){
    const alreadyUsed = getTotalBinderCount();
    const room = Math.max(0, limit - alreadyUsed);
    if(room === 0){
      canAddMoreItems(true);
      return;
    }
    if(toMark.length > room){
      toMark = toMark.slice(0, room);
      cappedNote = ` Your ${tierDisplayName(currentUserTier)} plan caps your binder at ${limit} items, so only ${room} could be added — upgrade to add the rest.`;
    }
  }

  const ok = confirm(`Mark ${toMark.length} item${toMark.length!==1?'s':''} as HAVE?${cappedNote}`);
  if(!ok) return;

  toMark.forEach(it=>{ state.owned[it.id] = true; });
  renderAll();
  refreshBinderIfVisible();

  try{
    await Promise.all(toMark.map(it => window.storage.set('owned:'+it.id, '1', false)));
  }catch(e){}
  queueCloudSave();

  if(cappedNote) alert(`Marked ${toMark.length} items.${cappedNote}`);
}

function itemDomains(item){
  return domainList(item.domain);
}

function itemDomainText(item){
  return itemDomains(item).join(', ');
}

// Same physical card printed in another language: matched by name + set +
// collector number. Used to cross-link language variants in the details
// modal (not the same as the Language field itself).
function languageSiblings(item){
  const seen = new Set([item.language]);
  const siblings = [];
  ITEMS.forEach(other=>{
    if(other.id === item.id) return;
    if(other.name !== item.name) return;
    if(other.set !== item.set) return;
    if(other.collectorNum !== item.collectorNum) return;
    if(!other.language || seen.has(other.language)) return;
    seen.add(other.language);
    siblings.push(other);
  });
  return siblings;
}

function isPromoItem(item){
  const c = (item.category||'').toUpperCase();
  return c === 'PROMO' || c === 'PROMO + COLLECTIBLE';
}

// Affiliate links. Each entry is a link TEMPLATE, set from the Supabase
// `app_settings` table (not from this file), so approving an affiliate program
// is "paste one value in Supabase" — no re-pasting the page. A template is the
// partner's own deep-link with {url} where the destination page goes, e.g.
//   https://partner.example/c/1234/5678?u={url}
// Empty (the default) = plain link, no tracking. See loadAffiliateSettings().
const AFFILIATE_LINKS = { tcgplayer:'', cardmarket:'', alimama:'', coupang:'', ebay:'' };
const AFFILIATE_SETTING_KEYS = {
  AFFILIATE_TCGPLAYER_TEMPLATE:'tcgplayer', AFFILIATE_CARDMARKET_TEMPLATE:'cardmarket',
  AFFILIATE_ALIMAMA_TEMPLATE:'alimama', AFFILIATE_COUPANG_TEMPLATE:'coupang',
  AFFILIATE_EBAY_TEMPLATE:'ebay'
};

function affiliateLink(partner, url){
  if(partner === 'ebay') return ebayLink(url);
  const tpl = AFFILIATE_LINKS[partner];
  return tpl ? tpl.replace('{url}', encodeURIComponent(url)) : url;
}
// eBay Partner Network: campaign "Collection-Bound Tracker". The tracking
// fields are added straight onto the eBay search link (eBay's own format), so
// the link always opens the normal eBay results page. Each eBay site has its
// own rotation id (US 711-..., France 709-...).
const EBAY_CAMPAIGN_ID = '5339245405';
const EBAY_ROTATION = { 'www.ebay.com':['711-53200-19255-0','0'], 'www.ebay.fr':['709-53476-19255-0','71'] };
function ebayLink(url){
  try{
    const u = new URL(url);
    const r = EBAY_ROTATION[u.hostname]; if(!r || !EBAY_CAMPAIGN_ID) return url;
    u.searchParams.set('mkcid', '1'); u.searchParams.set('mkrid', r[0]); u.searchParams.set('siteid', r[1]);
    u.searchParams.set('campid', EBAY_CAMPAIGN_ID); u.searchParams.set('toolid', '10001'); u.searchParams.set('mkevt', '1');
    return u.toString();
  }catch(e){ return url; }
}
// Search words for shop links: drop our own labels in (...) and [...] that
// sellers don't use, but keep the words collectors do search for.
function shopSearchName(name){
  const s = String(name || '');
  const keep = (s.match(/\b(plated|metal|oversized|signature|serialized|judge|playmat|sleeves|deck ?box|binder|pin|nexus night|launch|best of|jacket|medal)\b/gi) || []);
  const base = s.replace(/\[[^\]]*\]|\([^)]*\)/g, ' ').replace(/\s+-\s+/g, ' ').replace(/\s+/g, ' ').trim();
  const extra = [...new Set(keep.map(w => w.toLowerCase()))].filter(w => !base.toLowerCase().includes(w));
  return (base + (extra.length ? ' ' + extra.join(' ') : '')).trim();
}
function anyAffiliateActive(){
  return !!EBAY_CAMPAIGN_ID || Object.values(AFFILIATE_LINKS).some(Boolean);
}
const AFFILIATE_DISCLOSURE = 'Some links are affiliate links — we may earn a small commission at no extra cost to you.';

async function loadAffiliateSettings(){
  if(typeof sb === 'undefined' || !sb) return;
  try{
    const { data, error } = await sb.from('app_settings').select('key,value').in('key', Object.keys(AFFILIATE_SETTING_KEYS));
    if(error || !data) return;
    data.forEach(row=>{
      const partner = AFFILIATE_SETTING_KEYS[row.key];
      const v = String(row.value || '').trim();
      // Only accept https templates that say where the destination goes.
      if(partner && /^https:\/\//i.test(v) && v.includes('{url}')) AFFILIATE_LINKS[partner] = v;
    });
  }catch(e){ /* settings are optional — links stay plain */ }
}

