function populateFilters(){
  const statuses = [...new Set(ITEMS.map(i=>i.status).filter(Boolean))];
  const cats = [...new Set(ITEMS.map(i=>i.category).filter(Boolean))];
  const langs = [...new Set(ITEMS.map(i=>i.language).filter(Boolean))];
  const RARITY_ORDER = ['Common','Uncommon','Rare','Epic','Overnumber/Alternate Art','ARC','Champion Card','FND Rare','TBD'];
  const rarities = RARITY_ORDER;
  const DOMAIN_ORDER = ['Fury','Calm','Body','Order','Mind','Chaos','TBD','N/A'];
  const domains = DOMAIN_ORDER;
  const events = EVENT_ORDER;
  const sf = document.getElementById('statusFilter');
  const cf = document.getElementById('categoryFilter');
  const lf = document.getElementById('languageFilter');
  const rf = document.getElementById('rarityFilter');
  const df = document.getElementById('domainFilter');
  const ef = document.getElementById('eventFilter');
  statuses.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; sf.appendChild(o); });
  cats.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; cf.appendChild(o); });
  langs.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; lf.appendChild(o); });
  rarities.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; rf.appendChild(o); });
  domains.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; df.appendChild(o); });
  populateEventFilter();
}
// Event filter: Club and VIP see every event. Free accounts only see Nexus
// Night (a public event everyone already sees); the other events and
// locations stay members-only, so they're listed as one locked line.
function populateEventFilter(){
  const ef = document.getElementById('eventFilter'); if(!ef) return;
  const keep = ef.value;
  const free = promoDetailsLocked();
  const events = free ? ['NN - Nexus Nights'] : EVENT_ORDER;
  ef.innerHTML = '<option value="">All events</option>' + events.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join('')
    + (free ? '<option value="" disabled>&#128274; Every other event &amp; location: Club &amp; VIP</option>' : '');
  ef.value = events.includes(keep) ? keep : '';
  if(ef.value !== keep){ state.event = ''; }
}
function isNexusItem(i){ return !!i.nexusNight || itemEventGroups(i).includes('NN - Nexus Nights'); }
function nexusViewActive(){ return state.special === 'nexusNight' || state.event === 'NN - Nexus Nights' || String(state.event).startsWith('NN::'); }

function matches(item){
  const q = state.search.trim().toLowerCase();
  if(q){
    const hay = (promoDetailsLocked()
      ? [item.name, item.set, item.tags, item.itemType]
      : [item.name, item.event, item.set, item.tags, item.info, item.itemType, itemDomainText(item)]).join(' ').toLowerCase();
    if(!hay.includes(q)) return false;
  }
  if(state.status && item.status !== state.status) return false;
  if(state.category && item.category !== state.category) return false;
  if(state.language && item.language !== state.language) return false;
  if(state.rarity && item.rarity !== state.rarity) return false;
  if(state.domain && !itemDomains(item).includes(state.domain)) return false;
  if(state.event && String(state.event).startsWith('NN::')){ if(!isNexusItem(item) || item.set !== state.event.slice(4)) return false; }
  else if(state.event && !itemEventGroups(item).includes(state.event)) return false;
  if(state.special && !item[state.special]) return false;
  if(state.set && item.set !== state.set) return false;
  return true;
}

function effectiveStatus(item){
  return state.owned[item.id] ? 'HAVE' : item.status;
}

function renderStats(){
  const total = ITEMS.length;
  let have=0, need=0;
  ITEMS.forEach(i=>{
    const s = effectiveStatus(i);
    if(s==='HAVE') have++;
    else need++;
  });
  const pct = total ? Math.round((have/total)*100) : 0;
  const bar = document.getElementById('statsBar');

  const languages = [...new Set([...ITEMS.map(i=>i.language).filter(Boolean), 'Korean'])];
  const langCounts = languages.map(lang=>{
    const items = ITEMS.filter(i=>i.language===lang);
    const owned = items.filter(i=>effectiveStatus(i)==='HAVE').length;
    return {label: lang, owned, total: items.length};
  });

  const metalItems = ITEMS.filter(i=>i.metal);
  const nexusItems = ITEMS.filter(i=>i.nexusNight);
  const tourneyItems = ITEMS.filter(i=>i.tournament);
  const countOwned = arr => arr.filter(i=>effectiveStatus(i)==='HAVE').length;

  const breakdownChips = [
    ...langCounts.map(l=>({label: l.label, owned: l.owned, total: l.total, kind:'lang', value:l.label})),
    {label:'Metal', owned: countOwned(metalItems), total: metalItems.length, kind:'special', value:'metal'},
    {label:'Nexus Night', owned: countOwned(nexusItems), total: nexusItems.length, kind:'special', value:'nexusNight'},
    {label:'Tournament', owned: countOwned(tourneyItems), total: tourneyItems.length, kind:'special', value:'tournament'},
  ];

  bar.innerHTML = `
    <div class="stat total"><div class="n">${total}</div><div class="l">Total items</div></div>
    <div class="stat have"><div class="n">${have}</div><div class="l">Have &middot; ${pct}%</div>
      <div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div>
    </div>
    <div class="stat need"><div class="n">${need}</div><div class="l">Still need</div></div>
    <div class="stat-breakdown">
      ${breakdownChips.map(c=>chipButtonHtml(c, (c.kind==='lang' ? state.language : state.special) === c.value, 'filterPromosByChip')).join('')}
    </div>
  `;
}

function metalBadgesHtml(item){
  if(!item.metal) return '';
  return `<div class="tr-badges">${item.bestOfMetal ? '<span class="bestof-badge">BEST OF</span>' : ''}<span class="metal-badge">METAL</span></div>`;
}
function specialBadgesHtml(item){
  const badges = [];
  if(item.bestOfMetal){
    badges.push('<span class="badge-3d">3D STEREO</span>');
    badges.push('<span class="badge-textured">TEXTURED</span>');
    badges.push('<span class="badge-dotted-foil">DOT FOIL</span>');
  } else if(item.prizeWall){
    badges.push('<span class="badge-textured">TEXTURED</span>');
  }
  return badges.length ? `<div class="special-badges">${badges.join('')}</div>` : '';
}

// Free visitors see every promo's picture and name; the details (event, how
// it was given out, packaging, notes) and tracking are for members.
function promoDetailsLocked(){ return MEMBERSHIP_ENABLED && !isPaidTier(); }

function cardHtml(item){
  const locked = promoDetailsLocked();
  const owned = !!state.owned[item.id];
  const status = effectiveStatus(item);
  const domains = domainList(item.domain);
  const img = item.img
    ? `<img src="${escapeHtml(item.img)}" alt="${escapeHtml(item.name)}" loading="lazy" draggable="false" oncontextmenu="return false" onload="if(this.naturalWidth>this.naturalHeight){this.classList.add('is-landscape');}" onerror="var d=document.createElement('div');d.className='img-fallback';d.textContent=this.alt;this.replaceWith(d);"/>`
    : `<div class="img-fallback"><b>${item.language==='French' ? 'French picture coming soon' : 'Image coming soon'}</b><br>${escapeHtml(item.name)}</div>`;

  return `
  <div class="card ${owned?'is-have':''}" data-id="${item.id}" onclick="openModal('${item.id}')" role="button" tabindex="0">
    <div class="img-wrap">
      ${img}
      ${stampBoxHtml(item.id, true)}
      ${wishHeartHtml('promo:' + item.id)}
      ${trendOverlayHtml(promoTrendBadgeHtml(item))}
      <div class="br-badges">${langFlagHtml(item.language, item.flagMix)}${item.foil ? `<span class="foil-badge">FOIL</span>` : ''}</div>
      ${metalBadgesHtml(item)}
      ${specialBadgesHtml(item)}
      <div class="check-seal" onclick="event.stopPropagation(); toggleOwned('${item.id}')" title="Toggle owned">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><path d="M20 6 9 17l-5-5"/></svg>
      </div>${qtyBubbleHtml(getQty(item.id))}${locked ? '' : gradeBubbleHtml(promoGradeLabels(item.id))}
    </div>
    <div class="card-body">
      <div class="card-title">${escapeHtml(item.name)}${promoReturnBadge(item)}</div>
      <div class="card-meta">${locked ? (item.set ? escapeHtml(item.set) : '') : (itemEvents(item).length > 2 ? `${escapeHtml(item.set || '')}${eventColumnsHtml(item, ' / ', true)}` : `${escapeHtml(itemEvents(item).join(' / '))}${item.set? ' &middot; '+escapeHtml(item.set):''}`)}</div>
      <div class="chip-row">
        ${item.category? `<span class="pip">${escapeHtml(item.category)}</span>`:''}
        ${item.language? langPipHtml(item.language):''}
        ${item.rarity? `<span class="pip">${escapeHtml(item.rarity)}</span>`:''}
        ${domains.length ? `<span class="pip domain-${escapeHtml(domains[0])}">${escapeHtml(domains.join(', '))}</span>` : ''}
      </div>
      <div class="card-footer">
        <span class="num">${item.collectorNum && item.collectorNum!=='N/A' ? '#'+escapeHtml(item.collectorNum) : ''}</span>
        <button class="info-btn" onclick="event.stopPropagation(); openModal('${item.id}')">${locked ? 'Details &#128274;' : 'Details &rarr;'}</button>
      </div>
    </div>
  </div>`;
}

function sortItems(items){
  const arr = [...items];
  if(state.sort==='name') arr.sort((a,b)=>a.name.localeCompare(b.name));
  else if(state.sort==='status') arr.sort((a,b)=> effectiveStatus(a).localeCompare(effectiveStatus(b)));
  else arr.sort((a,b)=>promoSortRow(a)-promoSortRow(b));
  return arr;
}
// Project K trial-deck SAMPLE cards were added later (rows 10600+) but belong with the
// Macau event cards, so they sort straight after Gale Swordsman [Macau] (row 16).
function promoSortRow(i){
  if(/\[Project K Trial Deck\]/.test(i.name)){
    // English trial-deck cards come first, then the Chinese SAMPLE ones.
    if(i.language === 'English') return 16 + (i.row - 10669) / 100000;
    return 16 + (i.row - 10599) / 1000;
  }
  return i.row;
}

function renderGroupedGrid(items){
  const groups = {};
  items.forEach(i=>{
    const key = i.category || 'Other';
    groups[key] = groups[key]||[];
    groups[key].push(i);
  });
  let html = promoSectionJumpHtml(groups);
  Object.keys(groups).forEach((key, idx)=>{
    html += `<div class="group-heading" id="promoGroup-${idx}">${escapeHtml(key)} <span class="count">${groups[key].length} item${groups[key].length!==1?'s':''}</span>${collectibleGroupNoteHtml(key, groups[key])}</div>`;
    html += `<div class="grid ${state.view==='list'?'list-mode':''}">${groups[key].map(cardHtml).join('')}</div>`;
  });
  return html;
}

// Banner at the top of Promos & Collectibles: the list is long, so tell the
// viewer which sections exist further down and let them jump straight there.
function promoSectionJumpHtml(groups){
  const keys = Object.keys(groups);
  if(keys.length < 2) return '';
  const first = keys[0];
  const links = keys.map((k, i)=>
    `<button type="button" class="psj-link" onclick="jumpToPromoGroup(${i})">${escapeHtml(k)} <span>${groups[k].length}</span></button>`).join('');
  return `<div class="promo-section-jump" role="note">
    <div class="psj-text">The ${escapeHtml(first)} section is first and it's a long one, so collectibles and everything else are further down. Skip ahead:</div>
    <div class="psj-links">${links}</div>
  </div>`;
}

function jumpToPromoGroup(i){
  const el = document.getElementById('promoGroup-' + i);
  if(!el) return;
  const root = document.getElementById('collectBoundApp');
  const offset = parseFloat(getComputedStyle(root).getPropertyValue('--embed-header-offset')) || 0;
  window.scrollTo({ top: Math.max(0, el.getBoundingClientRect().top + window.scrollY - offset - 14), behavior: 'smooth' });
}

// Nexus Night promos grouped by set, in set order.
function renderNexusBySet(items){
  const by = new Map();
  items.forEach(i => { const k = i.set || 'Other'; if(!by.has(k)) by.set(k, []); by.get(k).push(i); });
  const keys = [...by.keys()].sort((a,b)=>(PROMO_SET_ORDER.indexOf(a)+1||99)-(PROMO_SET_ORDER.indexOf(b)+1||99));
  return keys.map(k => `<div class="group-heading">${escapeHtml(CARD_SET_NAMES[k] || k)} &mdash; Nexus Night <span class="count">${by.get(k).length} item${by.get(k).length!==1?'s':''}</span></div>
    <div class="grid ${state.view==='list'?'list-mode':''}">${by.get(k).map(cardHtml).join('')}</div>`).join('');
}
/* ---------- Product filter: what's inside each pre-constructed product ----------
   tracker-data/decks.json lists the cards in each Pre-Rift seeded deck,
   Champion (pre-constructed) deck and Showdown (dual battle) deck. Picking
   one in the "Product" filter shows those cards, with how many copies the
   product has and whether you already own each card, so collectors know
   what's inside without opening it. Cards are shown in the language picked
   in Card Language when that printing exists, otherwise English. */
let DECKS = null;
const DECK_KIND_LABEL = { starter:'Starter decks (Proving Grounds)', prerift:'Pre-Rift decks', champion:'Pre-Constructed (Champion) decks', showdown:'Dual Battle (Showdown) decks' };
const DECK_KIND_ORDER = ['starter', 'prerift', 'champion', 'showdown'];
function loadDecks(){
  return fetch(ghUrl('tracker-data/decks.json')).then(r => r.ok ? r.json() : null).then(d => {
    DECKS = (d && d.decks) || [];
    populateDeckFilter();
    if(state.deck) renderResults();
  }).catch(() => { DECKS = []; });
}
function deckSetOrder(code){ const i = PROMO_SET_ORDER.indexOf(code); return i < 0 ? 99 : i; }
function populateDeckFilter(){
  const sel = document.getElementById('deckFilter'); if(!sel || !DECKS) return;
  const keep = sel.value;
  sel.innerHTML = '<option value="">All products</option>' + DECK_KIND_ORDER.map(kind => {
    const list = DECKS.filter(d => d.kind === kind).sort((a, b) => deckSetOrder(a.set) - deckSetOrder(b.set) || a.name.localeCompare(b.name));
    if(!list.length) return '';
    return `<optgroup label="${escapeHtml(DECK_KIND_LABEL[kind])}">${list.map(d =>
      `<option value="${escapeHtml(d.id)}">${escapeHtml((kind === 'starter' ? d.product : (CARD_SET_NAMES[d.set] || d.set)) + (kind === 'starter' ? '' : kind === 'prerift' ? ' Pre-Rift' : kind === 'showdown' ? ' Showdown' : ' Champion Deck') + ' — ' + d.name)}</option>`).join('')}</optgroup>`;
  }).join('');
  if(keep) sel.value = keep;
}
const deckNum = c => { const m = /^0*(\d+)(.*)$/.exec(String(c || '')); return m ? (m[1] + m[2]).toLowerCase() : String(c || '').toLowerCase(); };
function deckCard(e, deckSet, lang){
  const pool = CARDS.filter(c => c.language === lang);
  let hit = null;
  if(e.s && e.c){
    hit = pool.find(c => c.setCode === e.s && deckNum(c.collectorNum) === deckNum(e.c));
  } else {
    const n = String(e.n).toLowerCase();
    const named = pool.filter(c => String(c.name).toLowerCase() === n);
    if(lang !== 'English' && !named.length){
      // other languages print other names: find the English card, then its printing in this language
      const en = deckCard(e, deckSet, 'English');
      if(en) hit = pool.find(c => c.setCode === en.setCode && deckNum(c.collectorNum) === deckNum(en.collectorNum));
      return hit;
    }
    const plain = c => /^\d+$/.test(String(c.collectorNum)) && !/showcase/i.test(String(c.rarity));
    hit = named.sort((a, b) => (a.setCode !== deckSet) - (b.setCode !== deckSet) || (!plain(a)) - (!plain(b)) || (parseInt(a.collectorNum, 10) || 999) - (parseInt(b.collectorNum, 10) || 999))[0] || null;
  }
  return hit;
}
function deckViewHtml(d){
  if(!CARDS.length) return '<div class="empty-state">Loading cards…</div>';
  const lang = (typeof setState !== 'undefined' && setState.language) || state.language || 'English';
  const sections = [[d.champion && d.champion.length ? 'Legend & chosen champion' : 'Legend', [...d.legend, ...(d.champion || [])]], ['Main deck', d.main], ['Battlefields & runes', [...d.battlefields, ...d.runes]]];
  let have = 0, total = 0, missing = [];
  const secHtml = sections.filter(([, list]) => list && list.length).map(([title, list]) => {
    const tiles = list.map(e => {
      let c = deckCard(e, d.set, lang);
      if(!c && lang !== 'English') c = deckCard(e, d.set, 'English');
      total++;
      if(!c){ missing.push(e.n); return `<div class="deck-missing">${escapeHtml(e.n)}${e.q > 1 ? ` &times;${e.q}` : ''}</div>`; }
      const owned = cardEffectiveOwned(c); if(owned) have++;
      if(state.deckOwn === 'need' && owned) return '';
      if(state.deckOwn === 'have' && !owned) return '';
      return `<div class="deck-tile">${cardTileHtml(c)}${e.q > 1 ? `<span class="deck-qty" title="${e.q} copies in this product">&times;${e.q}</span>` : ''}</div>`;
    }).join('');
    const n = list.reduce((s, e) => s + (e.q || 1), 0);
    return tiles.trim() ? `<div class="group-heading">${escapeHtml(title)} <span class="count">${n} card${n === 1 ? '' : 's'}</span></div><div class="grid deck-grid">${tiles}</div>` : '';
  }).join('');
  const pct = total ? Math.round(have / total * 100) : 0;
  return `<div class="deck-head">
      <div class="deck-kicker">${escapeHtml(DECK_KIND_LABEL[d.kind] || '')} &middot; ${escapeHtml(CARD_SET_NAMES[d.set] || d.set)}</div>
      <h3>${escapeHtml(d.product)}${d.kind === 'starter' || d.kind === 'prerift' || d.kind === 'showdown' ? ' &mdash; ' + escapeHtml(d.name) : ''}</h3>
      <div class="deck-progress"><b>${have}</b> of ${total} different cards in your collection (${pct}%)
        <div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div></div>
      <div class="deck-own">
        ${['', 'need', 'have'].map(v => `<button type="button" class="${(state.deckOwn || '') === v ? 'on' : ''}" onclick="setDeckOwn('${v}')">${v === '' ? 'All cards' : v === 'need' ? 'Missing only' : 'Have only'}</button>`).join('')}
      </div>
      ${d.note ? `<div class="deck-note">${escapeHtml(d.note)}</div>` : ''}
      <div class="deck-src">Decklist source: ${escapeHtml(d.source || '')}. ${d.kind === 'prerift' ? 'Pre-Rift kits also include booster packs; this is the seeded deck.' : ''}</div>
    </div>${secHtml || '<div class="empty-state">Nothing to show with this filter.</div>'}`;
}
function setDeckOwn(v){ state.deckOwn = v; renderResults(); }

function renderFlatGrid(items){
  return `<div class="grid ${state.view==='list'?'list-mode':''}">${items.map(cardHtml).join('')}</div>`;
}

function renderResults(){
  const container = document.getElementById('results');
  if(state.deck){
    const d = (DECKS || []).find(x => x.id === state.deck);
    container.innerHTML = d ? deckViewHtml(d) : '<div class="empty-state">Loading product contents…</div>';
    return;
  }
  if(!promosLoaded && !ITEMS.length){
    container.innerHTML = '<div class="sk-grid" aria-label="Loading promos and collectibles">' + '<div class="sk-card"></div>'.repeat(10) + '</div><div class="sk-note">Loading promos &amp; collectibles&hellip;</div>';
    return;
  }
  const filtered = sortItems(ITEMS.filter(matches));
  if(filtered.length===0){
    container.innerHTML = promosComingSoonHtml() || `<div class="empty-state">No items match your filters.</div>`;
    return;
  }

  if(nexusViewActive() && state.sort === 'row'){ container.innerHTML = renderNexusBySet(filtered); return; }
  const groupedView = (state.category === '' && state.sort === 'row');
  container.innerHTML = groupedView ? renderGroupedGrid(filtered) : renderFlatGrid(filtered);
}

function renderAll(){
  renderStats();
  renderResults();
}

function getFilteredPromoList(){
  return sortItems(ITEMS.filter(matches));
}

function updateModalNavButtons(){
  const prevBtn = document.getElementById('modalPrevBtn');
  const nextBtn = document.getElementById('modalNextBtn');
  if(!prevBtn || !nextBtn) return;
  const list = currentModalKind === 'card' ? getFilteredCardList() : currentModalKind === 'product' ? getFilteredProductList() : getFilteredPromoList();
  const idx = list.findIndex(i=>i.id===currentModalId);
  prevBtn.disabled = idx <= 0;
  nextBtn.disabled = idx === -1 || idx >= list.length - 1;
}

function navigateModal(delta){
  if(currentModalId === null) return;
  const list = currentModalKind === 'card' ? getFilteredCardList() : currentModalKind === 'product' ? getFilteredProductList() : getFilteredPromoList();
  const idx = list.findIndex(i=>i.id===currentModalId);
  if(idx === -1) return;
  const nextIdx = idx + delta;
  if(nextIdx < 0 || nextIdx >= list.length) return;
  openModal(list[nextIdx].id);
}

function openModal(id){
  if(id.startsWith('prod-')){
    openProductModal(id);
  } else if(id.startsWith('card-')){
    openCardModal(id);
  } else {
    openPromoModal(id);
  }
}

function openPromoModal(id){
  const item = ITEMS.find(i=>i.id===id);
  if(!item) return;
  if(promoDetailsLocked()){ openPromoTeaser(item); return; }
  currentModalId = id;
  currentModalKind = 'promo';
  const status = effectiveStatus(item);
  const imgs = [item.img].filter(Boolean);
  const packagingHtml = item.packagingImg
    ? `<div class="pkg-thumb"><img src="${escapeHtml(item.packagingImg)}" alt="Packaging" draggable="false" oncontextmenu="return false" onerror="this.parentElement.style.display='none'"/></div>`
    : `${escapeHtml(item.packagingText)||'&mdash;'}`;
  const isRetired = item.set === 'ARC' || item.set === 'FND';
  const qty = getQty(item.id);
  const siblings = languageSiblings(item);

  document.getElementById('modalBody').innerHTML = `
    <button class="modal-close" onclick="closeModal()">&times;</button>
    <h2>${escapeHtml(item.name)}${promoTrendBadgeHtml(item)}</h2>
    <div class="modal-sub">${escapeHtml(item.category)} &middot; ${escapeHtml(item.itemType)} &middot; <span class="status-chip ${status}" style="position:static;display:inline-block;">${status}</span></div>
    <div class="modal-imgs-row">
      <div class="modal-imgs">${imgs.map(u=>`<div class="modal-img-wrap"><div class="br-badges">${langFlagHtml(item.language, item.flagMix)}${item.foil ? `<span class="foil-badge">FOIL</span>` : ''}</div>${metalBadgesHtml(item)}${specialBadgesHtml(item)}<img src="${escapeHtml(u)}" alt="${escapeHtml(item.name)}" draggable="false" oncontextmenu="return false" onerror="this.parentElement.style.display='none'"/>${stampBoxHtml(item.id, false)}</div>`).join('')}</div>
      ${isRetired ? `<div class="retired-label">Retired</div>` : ''}
    </div>
    <div class="modal-grid">
      <div><div class="k">Event / Location</div><div class="v">${eventColumnsHtml(item, ', ')||'&mdash;'}${eventListHtml(item)}</div></div>
      <div><div class="k">Set</div><div class="v">${escapeHtml(item.set)||'&mdash;'}</div></div>
      <div><div class="k">Rarity</div><div class="v">${escapeHtml(item.rarity)||'&mdash;'}</div></div>
      <div><div class="k">Collector #</div><div class="v">${escapeHtml(item.collectorNum)||'&mdash;'}</div></div>
      <div><div class="k">Language</div><div class="v">${languageFieldHtml(item.language, siblings)}</div></div>
      <div><div class="k">Packaging</div><div class="v">${packagingHtml}</div></div>
      ${item.itemType === 'Card' ? `<div><div class="k">Tournament play</div><div class="v">${legalityHtml(item, 'promo')}</div></div>` : ''}
      <div><div class="k">Domain</div><div class="v">${escapeHtml(domainList(item.domain).join(', '))||'&mdash;'}</div></div>
      <div><div class="k">Tags</div><div class="v">${escapeHtml(item.tags)||'&mdash;'}</div></div>
    </div>
    ${item.serialMax ? '' : `<div class="qty-row">
      <span class="qty-label">Copies owned</span>
      <div class="qty-stepper">
        <button type="button" onclick="setQty('${item.id}', getQty('${item.id}')-1)">&minus;</button>
        <span id="qtyValue-${item.id}">${qty}</span>
        <button type="button" onclick="setQty('${item.id}', getQty('${item.id}')+1)">+</button>
      </div>
    </div>`}
    ${serialSectionHtml(item)}${promoGradingSectionHtml(item)}
    ${versionSectionHtml('promo:' + item.id)}${paidSectionHtml([{ key: 'promo:' + item.id, label: '' }])}
    <div class="modal-actions">
      <a href="#" onclick="toggleOwned('${item.id}');closeModal();return false;">${state.owned[item.id] ? 'Mark as not owned' : 'Mark as owned'}</a>
      <a href="#" onclick="toggleWish('promo:${item.id}');reopenCurrentModal();return false;">${wishOn('promo:' + item.id) ? '&#9829; On your wishlist' : '&#9825; Add to wishlist'}</a>
      ${item.infoImg ? `<a href="${escapeHtml(item.infoImg)}" target="_blank" rel="noopener">Additional photo &#8599;</a>` : ''}
    </div>
    ${marketplaceLinksHtml(item)}
    <div id="cbEbay"></div>
    <div class="cb-history" id="cbHistory"></div>
    ${cardValueSectionHtml()}
  `;
  document.getElementById('modalBackdrop').classList.add('open');
  updateModalNavButtons();
  hydrateOwnerPhotos(document.getElementById('modalBody'));
  fillHistory('promo', item);
  fillEbayPrice('promo', item);
}
/* ---------- History & Origin ----------
   Lore from the Lore Codex (codex/champs.json, linked to cards through
   tracker-data/codex-links.json) plus Jessica's own notes on the printing.
   Free visitors see a blurred placeholder (filler text, not the real notes)
   and a Club prompt. Nothing shows when there's no lore or notes for an item. */
let codexData = null, codexLoading = null;
const codexNum = n => String(n||'').trim().toLowerCase().replace(/^0+(?=\d)/,'');
const codexNameKey = n => String(n||'').toLowerCase().replace(/[^a-z0-9]/g,'');
function loadCodex(){
  if(codexData) return Promise.resolve(codexData);
  if(!codexLoading){
    codexLoading = Promise.all([
      fetch(ghUrl('tracker-data/codex-links.json')).then(r=>r.ok?r.json():null),
      fetch(ghUrl('codex/champs.json')).then(r=>r.ok?r.json():null)
    ]).then(([links, champs])=>{
      const byKey = new Map(), byId = new Map(), byName = new Map();
      (champs||[]).forEach(c=>{ byId.set(c.id, c); byName.set(codexNameKey(c.name), c); });
      Object.entries((links && links.links) || {}).forEach(([k, id])=>{
        const i = k.indexOf('-'); if(i < 0) return;
        byKey.set(k.slice(0,i).toUpperCase()+'-'+codexNum(k.slice(i+1)), id);
      });
      codexData = { byKey, byId, byName, page: (links && links.codexPage) || 'https://unravelingtherift.com/lore' };
      return codexData;
    }).catch(e=>{ console.warn('[Collection-Bound] codex failed', e); codexLoading = null; return null; });
  }
  return codexLoading;
}
function champForCard(card){
  const id = codexData.byKey.get(String(card.setCode||'').toUpperCase()+'-'+codexNum(card.collectorNum));
  return id ? codexData.byId.get(id) || null : null;
}
function champForPromo(item){
  if(item.itemType && item.itemType !== 'Card') return null;
  const base = String(item.name||'').split(/\s[-–]\s|,|\[|\(/)[0];
  return codexData.byName.get(codexNameKey(base)) || null;
}
async function fillHistory(kind, obj){
  const data = await loadCodex();
  const el = document.getElementById('cbHistory');
  if(!el || currentModalId !== obj.id) return;
  const champ = data ? (kind === 'card' ? champForCard(obj) : champForPromo(obj)) : null;
  // Notes are Jessica's own research (members only). Visitors don't receive the
  // text at all; get-promos just flags that notes exist (hasNotes).
  const notes = kind === 'promo' ? String(obj.info||'').trim() : '';
  const hasNotes = !!notes || (kind === 'promo' && !!obj.hasNotes);
  if(!champ && !hasNotes){ el.remove(); return; }
  const notesLocked = kind === 'promo' && promoDetailsLocked();
  // Lore is free for everyone, same as the public Lore Codex page.
  const lore = champ && champ.lore ? `<div class="cbh-k">${escapeHtml(champ.name)}${champ.title ? ', '+escapeHtml(champ.title) : ''}</div>
      <p>${escapeHtml(champ.lore)}</p>
      <a class="cbh-link" href="${escapeHtml(data.page)}#${encodeURIComponent(champ.id)}" target="_blank" rel="noopener">Read the full lore in the Lore Codex &rarr;</a>` : '';
  let printing = '';
  if(hasNotes && notesLocked){
    const filler = 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud.';
    printing = `<div class="cbh-k">About this printing</div>
      <div class="cbh-locked"><p class="cbh-blur" aria-hidden="true">${filler}</p>
        <a href="#" class="cbh-bar" onclick="event.preventDefault(); closeModal(); openMembershipChooser('tier1');">&#128274; Join the Collector Club to read the story behind this promo</a></div>`;
  }else if(notes){
    printing = `<div class="cbh-k">About this printing</div><p>${escapeHtml(notes)}</p>`;
  }
  if(!printing && !lore){ el.remove(); return; }
  el.innerHTML = `<div class="cbh-label">History &amp; Origin</div>${printing}${lore}`;
}

