/* ---- Best-effort image protection ----
   Browsers cannot truly block the OS-level Print Screen key, Snipping
   Tool, or similar capture utilities — nothing served over the web can
   prevent a screenshot. What's below deters casual "save image" /
   drag-out / print attempts and leaves a visible watermark on the
   images themselves so any captured copy is still marked. */
document.addEventListener('contextmenu', (e)=>{
  if(e.target.tagName === 'IMG'){ e.preventDefault(); }
});
document.addEventListener('dragstart', (e)=>{
  if(e.target.tagName === 'IMG'){ e.preventDefault(); }
});

let shieldTimeout = null;
function triggerPrivacyShield(){
  document.body.classList.add('privacy-shield');
  clearTimeout(shieldTimeout);
  shieldTimeout = setTimeout(()=>{ document.body.classList.remove('privacy-shield'); }, 1200);
}
document.addEventListener('keyup', (e)=>{
  // PrintScreen (Windows). Key events fire only after the OS has already
  // captured the screen, so this cannot stop the capture — it can only
  // react after the fact.
  if(e.key === 'PrintScreen'){ triggerPrivacyShield(); }
});
document.addEventListener('keydown', (e)=>{
  const k = (e.key||'').toLowerCase();
  // Common browser save/print shortcuts
  if((e.ctrlKey||e.metaKey) && (k==='p' || k==='s')){
    triggerPrivacyShield();
  }
});

// Arrow-key navigation while the details modal is open
document.addEventListener('keydown', (e)=>{
  if(!document.getElementById('modalBackdrop').classList.contains('open')) return;
  if(e.key === 'ArrowRight'){ e.preventDefault(); navigateModal(1); }
  else if(e.key === 'ArrowLeft'){ e.preventDefault(); navigateModal(-1); }
  else if(e.key === 'Escape'){ closeModal(); }
});

// Keyboard activation for card tiles (Enter / Space)
document.getElementById('results').addEventListener('keydown', (e)=>{
  if(e.key !== 'Enter' && e.key !== ' ') return;
  const card = e.target.closest('.card');
  if(!card) return;
  e.preventDefault();
  openModal(card.dataset.id);
});

/* =========================================================
   Origins (OGN) full-set tracking
   ========================================================= */

/* =========================================================
   Card Sets — data loaded from external hosting (GitHub), not
   embedded in this file. This is what lets the app keep adding
   new sets every quarter without the HTML file itself growing.
   ========================================================= */

let CARDS = [];
let CARD_LOAD_ERRORS = [];

// Card data is served from Supabase (Postgres + an Edge Function), not
// straight from GitHub JSON anymore. The function paginates (200 rows per
// call) and rate-limits by IP, so a visitor's normal browsing is unaffected
// but a bulk scrape of the whole catalog is slow, logged, and throttleable
// instead of a single instant download. SUPABASE_URL / SUPABASE_ANON_KEY are
// declared later in this file (Supabase Auth section) — cardApiUrl() reads
// them lazily via a function so load order doesn't matter.
// GITHUB_USER / GITHUB_REPO / GITHUB_BRANCH / ghUrl() below are still used
// for other assets (set art) — card, promo and product data moved off them.
const GITHUB_USER = 'unravelingtherift';
const GITHUB_REPO = 'collect-bound-data';
const GITHUB_BRANCH = 'main';

function ghUrl(filename){
  return `https://cdn.jsdelivr.net/gh/${GITHUB_USER}/${GITHUB_REPO}@${GITHUB_BRANCH}/${filename}`;
}

function cardApiUrl(){ return `${SUPABASE_URL}/functions/v1/get-cards`; }
const CARD_SETS = ['OGN', 'SFD', 'UNL', 'VEN', 'RAD', 'OGS'];

function expandCardRecord(r){
  // The database sends empty stats as null; the page expects '' for "none".
  const v = x => (x === null || x === undefined || String(x).trim().toLowerCase() === 'null') ? '' : x;
  return {
    row: r.r,
    name: r.nm,
    setCode: r.se,
    type: r.ty,
    tags: v(r.tg),
    energy: v(r.en),
    might: v(r.mi),
    power: v(r.po),
    mightBonus: v(r.mb),
    domain: v(r.do),
    rarity: r.ra,
    // Card numbers always use at least two digits: 7 -> 07, 007a -> 07a,
    // 030a -> 30a, 300* stays 300*. Lettered numbers (R01, T01, SP1) are left as they are.
    collectorNum: String(v(r.cn)).replace(/^0*(\d+)/, (m, d) => d.padStart(2, '0')),
    img: r.img,
    language: r.la,
    printings: r.pr,
    id: r.id,
    banned: r.ba
  };
}

async function fetchCardPage(setCode, offset){
  for(let attempt=0; attempt<4; attempt++){
    const res = await fetch(`${cardApiUrl()}?set=${encodeURIComponent(setCode)}&offset=${offset}`, {
      headers: { 'Authorization': `Bearer ${SUPABASE_ANON_KEY}`, 'apikey': SUPABASE_ANON_KEY }
    });
    if(res.ok) return res.json();
    if(res.status === 429){
      console.warn('Card data rate-limited, pausing briefly for', setCode);
      await new Promise(r=>setTimeout(r, 1500));
      continue;
    }
    throw new Error(`HTTP ${res.status}`);
  }
  throw new Error('rate limited');
}

// Page 1 tells us the set's total; the remaining pages are then fetched at the
// same time instead of one after another (the server still caps each request at
// 200 rows and rate-limits per IP, so this is not a bulk-download shortcut).
async function loadCardsForSet(setCode){
  try{
    const first = await fetchCardPage(setCode, 0);
    const pageSize = (first.data && first.data.length) || 200;
    const total = first.total || first.data.length;
    const jobs = [];
    for(let off = pageSize; off < total; off += pageSize) jobs.push(fetchCardPage(setCode, off));
    const rest = await Promise.all(jobs);
    return [first, ...rest].flatMap(p => p.data.map(expandCardRecord));
  }catch(e){
    console.error('Failed to load set data for', setCode, e);
    CARD_LOAD_ERRORS.push(setCode);
    return [];
  }
}

async function loadCards(){
  CARD_LOAD_ERRORS = [];
  const results = await Promise.all(CARD_SETS.map(loadCardsForSet));
  return results.flat();
}

// Browser cache so repeat visits show cards instantly; refreshed in the
// background when older than CARD_CACHE_TTL_MS.
const CARD_CACHE_KEY = 'cb_cards_cache_v3';
const CARD_CACHE_TTL_MS = 10 * 60 * 1000;
function cbReadCardCache(){
  try{
    const raw = localStorage.getItem(CARD_CACHE_KEY);
    if(!raw) return null;
    const o = JSON.parse(raw);
    if(!o || !Array.isArray(o.cards) || o.cards.length === 0) return null;
    return o;
  }catch(e){ return null; }
}
function cbWriteCardCache(cards){
  try{ localStorage.setItem(CARD_CACHE_KEY, JSON.stringify({ t: Date.now(), cards })); }
  catch(e){ try{ localStorage.removeItem(CARD_CACHE_KEY); }catch(_){} }
}
async function cbLoadCardsCached(){
  const cached = cbReadCardCache();
  if(cached){
    // Show the saved copy instantly, then fetch a fresh one in the background
    // (skipped only if the saved copy is under a minute old).
    const stale = (Date.now() - cached.t) > 60 * 1000;
    return { cards: cached.cards, refresh: stale ? loadCards() : null };
  }
  const cards = await loadCards();
  if(cards.length && CARD_LOAD_ERRORS.length === 0) cbWriteCardCache(cards);
  return { cards, refresh: null };
}


const setState = {
  search: '',
  set: '',
  language: '',
  type: '',
  rarity: '',
  domain: '',
  printing: '',
  sort: 'row',
  view: 'grid',
  owned: {},   // { [cardId]: { Normal: bool, Foil: bool } }
  qty: {},     // { [cardId]: { Normal: n, Foil: n } }
  cond: {}     // { [cardId]: { Normal: 'NM', Foil: 'LP' } } — condition of the copy you own
};

async function loadCardOwnership(){
  try{
    const res = await window.storage.list('card:');
    const owned = {};
    const qty = {};
    const cond = {};
    if(res && res.keys){
      for(const k of res.keys){
        try{
          const r = await window.storage.get(k, false);
          if(r && r.value){
            const data = JSON.parse(r.value);
            const id = k.replace('card:', '');
            owned[id] = { Normal: !!data.normalOwned, Foil: !!data.foilOwned };
            qty[id] = { Normal: data.normalQty|0, Foil: data.foilQty|0 };
            if(data.normalCond || data.foilCond) cond[id] = { Normal: data.normalCond||'', Foil: data.foilCond||'' };
          }
        }catch(e){}
      }
    }
    setState.owned = owned;
    setState.qty = qty;
    setState.cond = cond;
  }catch(e){ /* storage unavailable */ }
}

function getCardOwned(id, style){
  return !!(setState.owned[id] && setState.owned[id][style]);
}
function getCardQty(id, style){
  return (setState.qty[id] && setState.qty[id][style]) || 0;
}

async function saveCardOwnership(id){
  const owned = setState.owned[id] || { Normal:false, Foil:false };
  const qty = setState.qty[id] || { Normal:0, Foil:0 };
  const cond = setState.cond[id] || { Normal:'', Foil:'' };
  try{
    await window.storage.set('card:'+id, JSON.stringify({
      normalOwned: owned.Normal, foilOwned: owned.Foil,
      normalQty: qty.Normal, foilQty: qty.Foil,
      normalCond: cond.Normal || '', foilCond: cond.Foil || ''
    }), false);
  }catch(e){}
}

async function toggleCardPrinting(id, style){
  const card = CARDS.find(c=>c.id===id);
  const wasOwned = card ? cardEffectiveOwned(card) : false;
  const turningOn = !(setState.owned[id] && setState.owned[id][style]);
  if(!wasOwned && turningOn && !canAddMoreItems(true)) return;

  if(!setState.owned[id]) setState.owned[id] = { Normal:false, Foil:false };
  setState.owned[id][style] = !setState.owned[id][style];
  await saveCardOwnership(id);
  renderSetAll();
  refreshBinderIfVisible();
  queueCloudSave();
  if(state.deck) renderResults();
  const openCard = CARDS.find(c=>c.id===id);
  if(openCard && currentModalId===id) openCardModal(id);
}

async function setCardQty(id, style, next){
  next = Math.max(0, next|0);
  if(!setState.qty[id]) setState.qty[id] = { Normal:0, Foil:0 };
  setState.qty[id][style] = next;
  await saveCardOwnership(id);
  const el = document.getElementById(`cardQty-${id}-${style}`);
  if(el) el.textContent = next;
  queueCloudSave();
}

// Corner checkmark on Card Sets tiles. Not owned: marks the card's standard
// printing (Normal, or Foil for foil-only cards). Owned: unmarks every
// printing. Foil/Normal-specific choices still live in the Details window.
async function quickToggleCard(id){
  const card = CARDS.find(c=>c.id===id);
  if(!card) return;
  if(!setState.owned[id]) setState.owned[id] = { Normal:false, Foil:false };
  if(cardEffectiveOwned(card)){
    setState.owned[id].Normal = false;
    setState.owned[id].Foil = false;
  } else {
    if(!canAddMoreItems(true)) return;
    const base = card.printings.includes('Normal') ? 'Normal' : card.printings[0];
    setState.owned[id][base] = true;
  }
  await saveCardOwnership(id);
  renderSetAll();
  refreshBinderIfVisible();
  queueCloudSave();
  if(state.deck) renderResults();
}

function cardEffectiveOwned(card){
  const o = setState.owned[card.id];
  if(!o) return false;
  return card.printings.some(p => o[p]);
}

function isFoilOnly(card){
  return card.printings.length === 1 && card.printings[0] === 'Foil';
}

const DOMAIN_COLORS = {
  'Fury': '#e0917c', 'Order': '#8fb6e0', 'Calm': '#8fd6dd',
  'Chaos': '#d09be0', 'Mind': '#b6a8f0', 'Body': '#9bd696'
};
function domainColor(domain){
  const first = (domain||'').split(',')[0].trim();
  return DOMAIN_COLORS[first] || 'var(--gold-bright)';
}
function mightSymbol(){
  return `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" style="vertical-align:-1.5px;margin-right:3px;"><path d="M6.5 17.5 3 21l3.5-3.5M14 4l6 6-9 9-6-6z"/><path d="M14 4l2-2 4 4-2 2"/></svg>`;
}
function powerSymbol(color){
  return `<svg width="10" height="10" viewBox="0 0 24 24" style="vertical-align:-1px;margin-right:3px;"><polygon points="12,2 21,7 21,17 12,22 3,17 3,7" fill="${color}" opacity="0.85"/></svg>`;
}

// Card sets in the order they were released, not alphabetical.
const SET_RELEASE_ORDER = ['OGN','OGS','SFD','UNL','VEN','RAD','LGC','REC'];
function byReleaseOrder(a,b){
  const ia = SET_RELEASE_ORDER.indexOf(a), ib = SET_RELEASE_ORDER.indexOf(b);
  return (ia<0?99:ia) - (ib<0?99:ib) || String(a).localeCompare(String(b));
}

function populateSetFilters(){
  const sets = [...new Set(CARDS.map(c=>c.setCode).filter(Boolean))].sort(byReleaseOrder);
  const languages = [...new Set(CARDS.map(c=>c.language).filter(Boolean))].sort();
  const types = [...new Set(CARDS.map(c=>c.type).filter(Boolean))].sort();
  const rarities = [...new Set(CARDS.map(c=>c.rarity).filter(Boolean))].sort();
  const domains = [...new Set(CARDS.map(c=>c.domain).filter(Boolean))].sort();
  const sf = document.getElementById('setSetFilter');
  const lf = document.getElementById('setLanguageFilter');
  const tf = document.getElementById('setTypeFilter');
  const rf = document.getElementById('setRarityFilter');
  const df = document.getElementById('setDomainFilter');
  [sf,lf,tf,rf,df].forEach(sel=>{ const keep=sel.value; while(sel.options.length>1) sel.remove(1); sel.dataset.keep=keep; });
  sets.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; sf.appendChild(o); });
  languages.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; lf.appendChild(o); });
  types.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; tf.appendChild(o); });
  rarities.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; rf.appendChild(o); });
  domains.forEach(s=>{ const o=document.createElement('option'); o.value=s; o.textContent=s; df.appendChild(o); });
  // Re-add the upcoming sets (Legacy, The Reckoning) every time the list is rebuilt,
  // including the quiet background refresh, so they never drop out of the dropdown.
  if(typeof cbAddComingSoonOptions === 'function') cbAddComingSoonOptions();
  [sf,lf,tf,rf,df].forEach(sel=>{ if(sel.dataset.keep) sel.value=sel.dataset.keep; });
}

function matchesCard(card){
  const q = setState.search.trim().toLowerCase();
  if(q){
    const hay = [card.name, card.tags, card.type, card.rarity, card.domain].join(' ').toLowerCase();
    if(!hay.includes(q)) return false;
  }
  if(setState.set && card.setCode !== setState.set) return false;
  if(setState.language && card.language !== setState.language) return false;
  if(setState.type && card.type !== setState.type) return false;
  if(setState.rarity && card.rarity !== setState.rarity) return false;
  if(setState.domain && card.domain !== setState.domain) return false;
  if(setState.printing === 'foilOnly' && !isFoilOnly(card)) return false;
  if(setState.printing === 'normalFoil' && isFoilOnly(card)) return false;
  if(setState.own === 'have' && !cardEffectiveOwned(card)) return false;
  if(setState.own === 'need' && cardEffectiveOwned(card)) return false;
  return true;
}

// Collector-number order for a whole set: the main set 1, 2, 3 ... with
// alternate arts right after their card (40, 40a, 40b, 40*), then lettered
// numbers grouped by letter in alphabetical order (R01-R06 runes, SP1-SP6,
// T01-T07 tokens), each numerically. Cards with no number go last.
const CARD_LANG_ORDER = ['English','Chinese','Korean','French'];
function cardNumberKey(cn){
  const s = String(cn || '').trim().toUpperCase().replace(/^([A-Z]+?)O(\d)/, '$10$2');
  if(!s) return [2, '', 0, ''];
  const m = s.match(/^([A-Z]*)\s*0*(\d+)\s*([A-Z*]*)/);
  if(!m) return [2, s, 0, ''];
  return [m[1] ? 1 : 0, m[1], parseInt(m[2], 10), m[3]];
}
function compareCardNumbers(a, b){
  const ka = cardNumberKey(a), kb = cardNumberKey(b);
  if(ka[0] !== kb[0]) return ka[0] - kb[0];
  if(ka[1] !== kb[1]) return ka[1] < kb[1] ? -1 : 1;
  if(ka[2] !== kb[2]) return ka[2] - kb[2];
  if(ka[3] !== kb[3]) return ka[3] < kb[3] ? -1 : 1;
  return 0;
}
// Which block a card goes in: the main set first, then Runes, then SP cards,
// then Tokens. Runes and tokens are recognized by card type as well as by an
// R / T number, because some sets (Origins) number them inside the main set.
const AFTER_SET_BLOCKS = ['R','SP','T'];
function cardBlock(card){
  const type = String(card.type || '').toLowerCase();
  if(type.includes('token')) return 'T';
  if(type === 'rune' || type.includes(' rune')) return 'R';
  return cardNumberKey(card.collectorNum)[1] || '';
}
function blockRank(block){
  if(!block) return 0;
  const i = AFTER_SET_BLOCKS.indexOf(block);
  return i < 0 ? 1 + AFTER_SET_BLOCKS.length : 1 + i;
}
function compareChecklist(a, b){
  const sa = typeof byReleaseOrder === 'function' ? byReleaseOrder(a.setCode, b.setCode) : 0;
  if(sa) return sa;
  const la = CARD_LANG_ORDER.indexOf(a.language), lb = CARD_LANG_ORDER.indexOf(b.language);
  if(la !== lb) return (la<0?99:la) - (lb<0?99:lb);
  const ba = cardBlock(a), bb = cardBlock(b);
  if(ba !== bb){
    const d = blockRank(ba) - blockRank(bb);
    return d || (ba < bb ? -1 : 1);
  }
  return compareCardNumbers(a.collectorNum, b.collectorNum) || (a.row - b.row);
}
function sortCards(cards){
  const arr = [...cards];
  if(setState.sort === 'name') arr.sort((a,b)=>a.name.localeCompare(b.name));
  else arr.sort(compareChecklist);
  return arr;
}

function getFilteredCardList(){
  return sortCards(CARDS.filter(matchesCard));
}

function renderSetStats(){
  const total = CARDS.length;
  const have = CARDS.filter(cardEffectiveOwned).length;
  const need = total - have;
  const pct = total ? Math.round((have/total)*100) : 0;
  const bar = document.getElementById('setStatsBar');

  const setCodes = [...new Set(CARDS.map(c=>c.setCode).filter(Boolean))].sort(byReleaseOrder);
  const setChips = setCodes.map(sc=>{
    const inSet = CARDS.filter(c=>c.setCode===sc);
    const owned = inSet.filter(cardEffectiveOwned).length;
    return {label: sc, owned, total: inSet.length};
  });

  const DOMAIN_ORDER = ['Fury','Calm','Mind','Body','Chaos','Order'];
  const domainRank = d => {
    const parts = String(d).split(',').map(x=>x.trim());
    const idx = parts.map(x=>{ const i = DOMAIN_ORDER.indexOf(x); return i<0 ? 9 : i; });
    return [parts.length===1 && idx[0]<9 ? 0 : parts.length>1 ? 1 : 2, ...idx];
  };
  const domains = [...new Set(CARDS.map(c=>c.domain).filter(Boolean))].sort((a,b)=>{
    const ra = domainRank(a), rb = domainRank(b);
    for(let i=0;i<Math.max(ra.length,rb.length);i++){ const d=(ra[i]??-1)-(rb[i]??-1); if(d) return d; }
    return a.localeCompare(b);
  });
  const domainChips = domains.map(d=>{
    const inDomain = CARDS.filter(c=>c.domain===d);
    const owned = inDomain.filter(cardEffectiveOwned).length;
    return {label: d, owned, total: inDomain.length};
  });
  const foilOnlyCards = CARDS.filter(isFoilOnly);
  const foilOnlyOwned = foilOnlyCards.filter(cardEffectiveOwned).length;
  // Domains are picked from a dropdown instead of listing every chip.
  const shownDomain = setState.domain || setState.domainChip || '';
  const shownDomainChip = domainChips.find(c=>c.label===shownDomain);

  bar.innerHTML = `
    <div class="stat total"><div class="n">${total}</div><div class="l">Total cards</div></div>
    <div class="stat have"><div class="n">${have}</div><div class="l">Have &middot; ${pct}%</div>
      <div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div>
    </div>
    <div class="stat need"><div class="n">${need}</div><div class="l">Still need</div></div>
    <div class="domain-picker">
      <select id="setDomainChipSelect" aria-label="Domain progress" onchange="pickDomainChip(this.value)">
        <option value="">Domain progress&hellip;</option>
        ${domainChips.map(c=>`<option value="${escapeHtml(c.label)}"${shownDomain===c.label?' selected':''}>${escapeHtml(c.label)} (${c.owned}/${c.total})</option>`).join('')}
      </select>
      ${shownDomainChip ? chipButtonHtml({...shownDomainChip, kind:'domain', value:shownDomainChip.label}, setState.domain===shownDomainChip.label, 'filterSetsByChip') : ''}
    </div>
    <div class="stat-breakdown">
      ${setChips.map(c=>chipButtonHtml({...c, kind:'set', value:c.label}, setState.set===c.label, 'filterSetsByChip')).join('')}
      <div class="breakdown-chip">
        <span class="bc-label">Foil-only</span>
        <span class="bc-count">${foilOnlyOwned}<span class="bc-total">/${foilOnlyCards.length}</span></span>
      </div>
    </div>
  `;
}

// Tokens (Recruit, Sprite…) are mostly white artwork, where the full
// watermark overwhelms the picture — they get a lighter one.
function isTokenCard(card){ return /token/i.test(String(card && card.type || '')); }

// Small sparkle badge after the name: ON (Overnumber), ON SIG (Signature
// Overnumber) or AA (Alternate Art). The "AA" typed at the end of a card name
// is hidden when shown on screen, because the badge says it instead.
function overnumberBadgeHtml(card){
  const r = String(card.rarity || '').toLowerCase();
  if(r.includes('overnumber')){
    return r.includes('signature')
      ? '<span class="on-badge on-sig" title="Signature Overnumber Showcase">ON SIG</span>'
      : '<span class="on-badge" title="Overnumber Showcase">ON</span>';
  }
  if(r.includes('alternate art') || /\sAA$/.test(String(card.name || '').trim())){
    return '<span class="on-badge on-aa" title="Alternate Art">AA</span>';
  }
  return '';
}
function cardDisplayName(card){
  return String(card.name || '').trim().replace(/\s+AA$/, '');
}

function cardTileHtml(card){
  const owned = cardEffectiveOwned(card);
  const foilOnly = isFoilOnly(card);
  const img = card.img
    ? `<img src="${escapeHtml(card.img)}" alt="${escapeHtml(card.name)}" loading="lazy" draggable="false" oncontextmenu="return false" onload="if(this.naturalWidth>this.naturalHeight){this.classList.add('is-landscape');}" onerror="var d=document.createElement('div');d.className='img-fallback';d.textContent=this.alt;this.replaceWith(d);"/>`
    : `<div class="img-fallback"><b>${card.language==='French' ? 'French picture coming soon' : 'Image coming soon'}</b><br>${escapeHtml(card.name)}</div>`;

  return `
  <div class="card ${owned?'is-have':''}" data-id="${card.id}" onclick="openModal('${card.id}')" role="button" tabindex="0">
    <div class="img-wrap${isTokenCard(card) ? ' wm-light' : ''}">
      ${img}
      ${wishHeartHtml('card:' + card.id)}
      ${trendOverlayHtml(trendBadgeHtml(card))}
      <div class="br-badges">${langFlagHtml(card.language)}${foilOnly ? `<span class="foil-badge">FOIL</span>` : ''}</div>
      ${isBannedEverywhere(card) ? `<span class="banned-badge">BANNED</span>` : ''}
      <div class="check-seal" onclick="event.stopPropagation(); quickToggleCard('${card.id}')" title="${owned ? 'Mark as not owned' : 'Mark as owned (Details for Foil)'}">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><path d="M20 6 9 17l-5-5"/></svg>
      </div>${qtyBubbleHtml(getCardQty(card.id,'Normal') + getCardQty(card.id,'Foil'))}${gradeBubbleHtml(cardGradeLabels(card.id))}
    </div>
    <div class="card-body">
      <div class="card-title">${escapeHtml(cardDisplayName(card))}${overnumberBadgeHtml(card)}${cardReturnBadge(card)}</div>
      <div class="card-meta">${escapeHtml(card.setCode||'')}</div>
      <div class="chip-row">
        ${card.type? `<span class="pip">${escapeHtml(card.type)}</span>`:''}
        ${card.language? langPipHtml(card.language):''}
        ${card.rarity? `<span class="pip">${escapeHtml(card.rarity)}</span>`:''}
        ${domainList(card.domain).length ? `<span class="pip domain-${escapeHtml(domainList(card.domain)[0])}">${escapeHtml(domainList(card.domain).join(', '))}</span>` : ''}
        <span class="pip">Cost ${escapeHtml(String(card.energy))}</span>
        <span class="pip">${mightSymbol()}${escapeHtml(String(card.might))}</span>
        <span class="pip">${powerSymbol(domainColor(card.domain))}${escapeHtml(String(card.power))}</span>
      </div>
      <div class="card-footer">
        <span class="num">#${escapeHtml(card.collectorNum)}</span>
        <button class="info-btn" onclick="event.stopPropagation(); openModal('${card.id}')">Details &rarr;</button>
      </div>
    </div>
  </div>`;
}

const CARD_SET_NAMES = { OGN:'Origins', OGS:'Proving Grounds', SFD:'Spiritforged', UNL:'Unleashed',
  VEN:'Vendetta', RAD:'Radiance', LGC:'Legacy', REC:'The Reckoning' };
function setLanguageLabel(c){
  return `${CARD_SET_NAMES[c.setCode] || c.setCode} — ${c.language || 'Other'}`;
}
// Card-number view: a collapsible section each time the set or language changes
// (e.g. "Origins — English", then "Origins — Chinese"). One section only = no heading.
function renderSetLanguageGrid(cards){
  const groups = [];
  cards.forEach(c=>{
    const key = setLanguageLabel(c);
    const last = groups[groups.length-1];
    if(last && last.key === key) last.cards.push(c); else groups.push({ key, cards:[c] });
  });
  if(groups.length < 2) return renderSetFlatGrid(cards);
  return groups.map(g =>
    `<div class="group-heading">${escapeHtml(g.key)} <span class="count">${g.cards.length} item${g.cards.length!==1?'s':''}</span></div>` +
    `<div class="grid ${setState.view==='list'?'list-mode':''}">${g.cards.map(cardTileHtml).join('')}</div>`
  ).join('');
}

function renderSetGroupedGrid(cards){
  const groups = {};
  const manyLangs = new Set(cards.map(c=>c.setCode+'|'+c.language)).size > 1;
  cards.forEach(c=>{
    const key = manyLangs ? `${setLanguageLabel(c)} · ${c.type || 'Other'}` : (c.type || 'Other');
    groups[key] = groups[key]||[];
    groups[key].push(c);
  });
  let html = '';
  Object.keys(groups).forEach(key=>{
    html += `<div class="group-heading">${escapeHtml(key)} <span class="count">${groups[key].length} item${groups[key].length!==1?'s':''}</span></div>`;
    html += `<div class="grid ${setState.view==='list'?'list-mode':''}">${groups[key].map(cardTileHtml).join('')}</div>`;
  });
  return html;
}
function renderSetFlatGrid(cards){
  return `<div class="grid ${setState.view==='list'?'list-mode':''}">${cards.map(cardTileHtml).join('')}</div>`;
}

function renderSetResults(){
  const filtered = getFilteredCardList();
  const container = document.getElementById('setResults');

  let errorBanner = '';
  if(CARD_LOAD_ERRORS.length > 0){
    errorBanner = `<div class="load-error-banner">Couldn't load: ${CARD_LOAD_ERRORS.join(', ')} &mdash; check your internet connection and try reloading the page.</div>`;
  }

  if(filtered.length===0){
    container.innerHTML = errorBanner + (setsComingSoonHtml() || `<div class="empty-state">No cards match your filters.</div>`);
    return;
  }
  // Sections by card type only when the visitor picks "Group by card type".
  const groupedView = (setState.type === '' && setState.sort === 'type');
  const byNumber = (setState.sort !== 'name');
  container.innerHTML = errorBanner + (groupedView ? renderSetGroupedGrid(filtered) : byNumber ? renderSetLanguageGrid(filtered) : renderSetFlatGrid(filtered));
}

function renderSetAll(){
  renderSetStats();
  renderSetResults();
}

function openCardModal(id){
  const card = CARDS.find(c=>c.id===id);
  if(!card) return;
  currentModalId = id;
  currentModalKind = 'card';
  const foilOnly = isFoilOnly(card);

  const printingRows = card.printings.map(style=>{
    const owned = getCardOwned(card.id, style);
    const qty = getCardQty(card.id, style);
    return `
      <div class="printing-row">
        <button type="button" class="printing-check ${owned?'is-checked':''}" onclick="toggleCardPrinting('${card.id}','${style}')">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><path d="M20 6 9 17l-5-5"/></svg>
        </button>
        <span class="printing-label">${escapeHtml(printingLabel(style))}</span>
        <select class="cond-select" aria-label="${escapeHtml(t('m.condition'))} — ${escapeHtml(printingLabel(style))}" title="${escapeHtml(t('m.condition'))}" onchange="setCardCondition('${card.id}','${style}', this.value)">${condOptionsHtml(getCardCond(card.id, style))}</select>
        <div class="qty-stepper">
          <button type="button" onclick="setCardQty('${card.id}','${style}', getCardQty('${card.id}','${style}')-1)">&minus;</button>
          <span id="cardQty-${card.id}-${style}">${qty}</span>
          <button type="button" onclick="setCardQty('${card.id}','${style}', getCardQty('${card.id}','${style}')+1)">+</button>
        </div>
      </div>`;
  }).join('');

  document.getElementById('modalBody').innerHTML = `
    <button class="modal-close" onclick="closeModal()">&times;</button>
    <h2>${escapeHtml(cardDisplayName(card))}${overnumberBadgeHtml(card)}${trendBadgeHtml(card)}</h2>
    <div class="modal-sub">${escapeHtml(card.setCode)} &middot; ${escapeHtml(card.type)}${foilOnly ? ` &middot; <span class="status-chip HAVE" style="position:static;display:inline-block;">FOIL-ONLY</span>` : ''}${isBannedEverywhere(card) ? ` &middot; <span class="status-chip NEED" style="position:static;display:inline-block;background:#c1372f;border-color:#c1372f;color:#fff;">BANNED</span>` : ''}</div>
    <div class="modal-imgs-row">
      <div class="modal-imgs"><div class="modal-img-wrap${isTokenCard(card) ? ' wm-light' : ''}"><div class="br-badges">${langFlagHtml(card.language)}${foilOnly ? `<span class="foil-badge">FOIL</span>` : ''}</div>${isBannedEverywhere(card) ? `<span class="banned-badge">BANNED</span>` : ''}${card.img ? `<img src="${escapeHtml(card.img)}" alt="${escapeHtml(card.name)}" draggable="false" oncontextmenu="return false" onerror="this.parentElement.style.display='none'"/>` : `<div class="img-fallback" style="aspect-ratio:5/7;display:flex;flex-direction:column;justify-content:center;"><b>${card.language==='French' ? 'French picture coming soon' : 'Image coming soon'}</b>${escapeHtml(card.name)}</div>`}</div></div>
    </div>
    <div class="modal-grid">
      <div><div class="k">${t('m.set')}</div><div class="v">${escapeHtml(card.setCode)||'&mdash;'}</div></div>
      <div><div class="k">${t('m.collector')}</div><div class="v">${escapeHtml(card.collectorNum)||'&mdash;'}</div></div>
      <div><div class="k">Domain</div><div class="v">${escapeHtml(card.domain)||'&mdash;'}</div></div>
      <div><div class="k">${t('m.rarity')}</div><div class="v">${escapeHtml(card.rarity)||'&mdash;'}</div></div>
      <div><div class="k">Energy</div><div class="v">${card.energy!=='' ? escapeHtml(String(card.energy)) : '&mdash;'}</div></div>
      <div><div class="k">Might / Power</div><div class="v">${(()=>{const parts=[];if(card.might!=='')parts.push(mightSymbol()+escapeHtml(String(card.might)));if(card.power!=='')parts.push(powerSymbol(domainColor(card.domain))+escapeHtml(String(card.power)));return parts.length?parts.join(' &nbsp;/&nbsp; '):'&mdash;';})()}</div></div>
      ${card.mightBonus!=='' ? `<div><div class="k">Might Bonus</div><div class="v">${mightSymbol()}+${escapeHtml(String(card.mightBonus))}</div></div>` : ''}
      <div><div class="k">${t('m.language')}</div><div class="v">${languageFieldHtml(card.language, cardLanguageSiblings(card))}</div></div>
      <div><div class="k">Tournament play</div><div class="v">${legalityHtml(card, 'card')}</div></div>
      <div><div class="k">${t('m.tags')}</div><div class="v">${escapeHtml(card.tags)||'&mdash;'}</div></div>
    </div>
    <div class="qty-row" style="flex-direction:column; align-items:stretch; gap:8px;">
      <span class="qty-label">${t('m.printingsOwned')}</span>
      ${printingRows}
    </div>
    ${cardGradingSectionHtml(card)}
    ${paidSectionHtml(card.printings.map(pr => ({ key: 'card:' + card.id + ':' + pr, label: card.printings.length > 1 ? printingLabel(pr) : '' })))}
    <div class="modal-actions"><a href="#" onclick="toggleWish('card:${card.id}');reopenCurrentModal();return false;">${wishOn('card:' + card.id) ? '&#9829; On your wishlist' : '&#9825; Add to wishlist'}</a></div>
    ${cardPriceSectionHtml(card)}
    <div class="cb-history" id="cbHistory"></div>
  `;
  document.getElementById('modalBackdrop').classList.add('open');
  updateModalNavButtons();
  if(isVipTier()) requestCardPrice(card);
  else if(MEMBERSHIP_ENABLED) requestBasicPrice(card);
  hydrateOwnerPhotos(document.getElementById('modalBody'));
  fillHistory('card', card);
}

async function markAllSetOwned(){
  const remaining = CARDS.filter(c=>!cardEffectiveOwned(c));
  if(remaining.length === 0){
    alert('Every card is already marked as HAVE.');
    return;
  }

  const limit = getTierLimit();
  let toMark = remaining;
  let cappedNote = '';
  if(limit !== Infinity){
    const alreadyUsed = getTotalBinderCount();
    const room = Math.max(0, limit - alreadyUsed);
    if(room === 0){
      canAddMoreItems(true);
      return;
    }
    if(toMark.length > room){
      toMark = toMark.slice(0, room);
      cappedNote = ` Your ${tierDisplayName(currentUserTier)} plan caps your binder at ${limit} items, so only ${room} could be added — upgrade to add the rest.`;
    }
  }

  const ok = confirm(`Mark ${toMark.length} card${toMark.length!==1?'s':''} as HAVE (all printings)?${cappedNote}`);
  if(!ok) return;

  toMark.forEach(c=>{
    setState.owned[c.id] = {};
    c.printings.forEach(p=>{ setState.owned[c.id][p] = true; });
  });
  renderSetAll();
  refreshBinderIfVisible();

  try{
    await Promise.all(toMark.map(c => window.storage.set('card:'+c.id, JSON.stringify({
      normalOwned: !!setState.owned[c.id].Normal,
      foilOwned: !!setState.owned[c.id].Foil,
      normalQty: getCardQty(c.id,'Normal'),
      foilQty: getCardQty(c.id,'Foil')
    }), false)));
  }catch(e){}
  queueCloudSave();

  if(cappedNote) alert(`Marked ${toMark.length} cards.${cappedNote}`);
}

document.getElementById('setSearchInput').addEventListener('input', e=>{ setState.search=e.target.value; renderSetResults(); });
