// haven't signed up, which is why this needs to work correctly whether or
// not currentUser is set.
let currentUserTier = 'free'; // 'free' | 'tier1' (Collector Club, $5) | 'tier2' (VIP Collector, $15)
let cloudSaveTimer = null;
var pendingJoin = false; // reopen the membership window once they've logged in

// How many total binder items (promos + card sets combined, counting each
// card once regardless of how many printings are owned) each tier may mark
// as HAVE. Free/Public Viewer is capped; both paid tiers are unlimited —
// the difference between Club and VIP is pricing-data features, not item
// count. Adjust these numbers any time — nothing else needs to change.
const TIER_LIMITS = {
  free: 75,
  tier1: Infinity,
  tier2: Infinity
};

function isPaidTier(){
  if(!MEMBERSHIP_ENABLED) return false;
  return currentUserTier && currentUserTier !== 'free';
}

function isVipTier(){
  if(!MEMBERSHIP_ENABLED) return false;
  return currentUserTier === 'tier2';
}

function getTierLimit(){
  if(!MEMBERSHIP_ENABLED) return Infinity;
  return TIER_LIMITS[currentUserTier] ?? TIER_LIMITS.free;
}

function getTotalBinderCount(){
  const promoCount = ITEMS.filter(i=>!!state.owned[i.id]).length;
  const cardCount = CARDS.filter(cardEffectiveOwned).length;
  const productCount = (typeof PRODUCTS !== 'undefined') ? getOwnedProducts().length : 0;
  return promoCount + cardCount + productCount;
}

function tierDisplayName(tier){
  return tier === 'tier2' ? 'VIP Collector' : tier === 'tier1' ? 'Collector Club' : 'Free & Public Viewer';
}

// Call this before marking something new as owned. Returns true if there's
// room; if not, shows a clear message explaining the cap and returns false
// so the caller can bail out without changing anything.
function canAddMoreItems(showMessageIfBlocked){
  const limit = getTierLimit();
  if(limit === Infinity) return true;
  const used = getTotalBinderCount();
  if(used < limit) return true;
  if(showMessageIfBlocked) openLimitGate(limit);
  return false;
}

// Shown when a free binder is full: an upgrade card instead of a plain alert.
function openLimitGate(limit){
  currentModalId = null;
  currentModalKind = 'promo';
  document.getElementById('modalBody').innerHTML = `
    <button class="modal-close" onclick="closeModal()">&times;</button>
    <div class="member-gate-card limit-gate">
      <div class="member-gate-icon">&#128202;</div>
      <div class="member-gate-title">You've maxed out your free starter binder!</div>
      <div class="member-gate-sub">All ${limit} free spots are full. Join the Collector Club for $5/mo to track unlimited cards, promos and collectibles in English, Chinese, French and Korean, plus back up and export your whole collection.</div>
      <a class="mg-btn" href="#" onclick="event.preventDefault(); closeModal(); openMembershipChooser('tier1');">Join the Collector Club</a>
      <a class="limit-gate-later" href="#" onclick="event.preventDefault(); closeModal();">Not right now</a>
    </div>
  `;
  document.getElementById('modalBackdrop').classList.add('open');
  updateModalNavButtons();
}

// Show/Hide password: appears after a failed Log In or Sign Up so people
// can check what they typed. Goes back to hidden after a successful log in.
function revealPasswordToggle(){
  const btn = document.getElementById('authPwToggle');
  if(!btn) return;
  btn.hidden = false;
  btn.parentElement.classList.add('has-toggle');
}
function resetPasswordToggle(){
  const btn = document.getElementById('authPwToggle');
  const input = document.getElementById('authPassword');
  if(!btn || !input) return;
  input.type = 'password';
  btn.textContent = 'Show';
  btn.setAttribute('aria-pressed', 'false');
  btn.hidden = true;
  btn.parentElement.classList.remove('has-toggle');
}
document.getElementById('authPwToggle').addEventListener('click', ()=>{
  const input = document.getElementById('authPassword');
  const showing = input.type === 'text';
  input.type = showing ? 'password' : 'text';
  const btn = document.getElementById('authPwToggle');
  btn.textContent = showing ? 'Show' : 'Hide';
  btn.setAttribute('aria-pressed', showing ? 'false' : 'true');
  input.focus();
});

// Plain-language versions of the Supabase errors people hit most.
function friendlyAuthError(error){
  const m = (error && error.message || '').toLowerCase();
  if(m.includes('invalid login credentials')) return "That email and password don't match. Click Show to check what you typed.";
  if(m.includes('email not confirmed')) return 'Confirm your email first: open the email we sent and click its link, then log in.';
  if(m.includes('rate limit')) return 'Too many emails sent just now. Wait a few minutes, then try again.';
  if(m.includes('already registered')) return 'That email already has an account. Click Log In instead.';
  return error.message;
}

function setAuthMessage(msg, isError){
  const el = document.getElementById('authMessage');
  if(!el) return;
  el.textContent = msg || '';
  el.style.color = isError ? '#e08f7c' : '';
}

function setSyncStatus(msg){
  const el = document.getElementById('authSyncStatus');
  if(el) el.textContent = msg || '';
}

function applyUserWatermark(email){
  removeUserWatermark();
  if(!email) return;
  const overlay = document.createElement('div');
  overlay.className = 'user-watermark-overlay';
  overlay.id = 'userWatermarkOverlay';
  for(let i=0;i<24;i++){
    const span = document.createElement('span');
    span.textContent = email;
    overlay.appendChild(span);
  }
  (document.getElementById('collectBoundApp') || document.body).appendChild(overlay);
}
function removeUserWatermark(){
  const existing = document.getElementById('userWatermarkOverlay');
  if(existing) existing.remove();
}

// Best-effort right-click deterrent across the whole tracker (not just
// images). Like every measure in this section, this only raises friction
// for casual copying — it can't stop someone using devtools or view-source,
// and doesn't try to.
document.addEventListener('contextmenu', (e)=>{
  if(e.target.closest && e.target.closest('.app-root')){
    e.preventDefault();
  }
});

// Show or hide member-only promo controls, and redraw the promo grid when the
// visitor's tier changes (log in, log out, upgrade).
let lastLockState = null;
function applyTierLocks(){
  const locked = promoDetailsLocked();
  const ev = document.getElementById('eventFilter');
  if(ev) ev.style.display = '';   // the Event filter is for everyone; free accounts only get Nexus Night
  if(lastLockState !== locked) populateEventFilter();
  const mark = document.getElementById('markAllBtn');
  if(mark) mark.style.display = locked ? 'none' : '';
  if(lastLockState !== null && lastLockState !== locked){
    if(typeof renderResults === 'function' && typeof ITEMS !== 'undefined') renderResults();
    if(typeof refreshExtraTabsIfVisible === 'function') refreshExtraTabsIfVisible();
  }
  // Member details arrive only for members: fetch the full catalog after
  // logging in / upgrading, and drop it again after logging out.
  if(MEMBERSHIP_ENABLED && typeof ITEMS !== 'undefined' && ITEMS.length && promosAreFull === locked){
    if(locked) cbClearMemberPromoCaches();
    reloadPromosForTier();
  }
  lastLockState = locked;
  if(MEMBERSHIP_ENABLED && isVipTier() && displayCurrencyPref !== 'USD' && !fxRates){
    loadFxRates().then(r => { if(r) refreshBinderValue(); });
  }
  if(typeof refreshBinderValue === 'function') refreshBinderValue();
}

let promoReloading = false;
async function reloadPromosForTier(){
  if(promoReloading) return;
  promoReloading = true;
  try{
    ITEMS = await loadItems(true);
    renderAll();
    if(typeof refreshExtraTabsIfVisible === 'function') refreshExtraTabsIfVisible();
    if(typeof refreshBinderIfVisible === 'function') refreshBinderIfVisible();
  }catch(e){ console.warn('[Collection-Bound] promo reload failed', e); }
  promoReloading = false;
}

function updateAuthUI(){
  applyTierLocks();
  const loggedOutEl = document.getElementById('authLoggedOut');
  const loggedInEl = document.getElementById('authLoggedIn');
  if(!loggedOutEl || !loggedInEl) return;

  const limit = getTierLimit();
  const used = getTotalBinderCount();
  const usageText = limit === Infinity ? `${used} items` : `${used} / ${limit} items`;
  const usageEl = document.getElementById('authUsage');
  if(usageEl) usageEl.textContent = usageText;
  const usageEl2 = document.getElementById('authUsageLoggedIn');
  if(usageEl2) usageEl2.textContent = usageText;

  // Note: the tracker itself is public — there's no login gate here anymore.
  // Signing in only unlocks unlimited tracking + cross-device sync (paid
  // tiers) instead of the free tier's item cap. Anyone can browse without
  // an account at all.
  if(currentUser){
    loggedOutEl.style.display = 'none';
    loggedInEl.style.display = '';
    document.getElementById('authUserEmail').textContent = currentUser.email || '';
    document.getElementById('authTierBadge').textContent = tierDisplayName(currentUserTier);
    applyUserWatermark(currentUser.email);
  } else {
    loggedOutEl.style.display = '';
    loggedInEl.style.display = 'none';
    removeUserWatermark();
  }

  // Header button: "Join the Chase" for free/visitors, "My Membership" for members.
  const joinBtn = document.getElementById('joinChaseBtn');
  if(joinBtn) joinBtn.innerHTML = (currentUser && isPaidTier()) ? 'My Membership &rarr;' : 'Join the Chase! &rarr;';
  if(!MEMBERSHIP_ENABLED){
    if(joinBtn) joinBtn.style.display = 'none';
    const badge = document.getElementById('authTierBadge');
    if(badge) badge.style.display = 'none';
  }

  // Keep the membership window in step with login state.
  const chooser = document.getElementById('membershipChooser');
  if(chooser && typeof openMembershipChooser === 'function'){
    if(!chooser.hidden) openMembershipChooser();
    else if(currentUser && typeof pendingJoin !== 'undefined' && pendingJoin){ pendingJoin = false; openMembershipChooser(); }
  }
}

async function handleSignUp(){
  if(!sb){ setAuthMessage('Cloud sync unavailable (Supabase failed to load).', true); return; }
  const email = document.getElementById('authEmail').value.trim();
  const password = document.getElementById('authPassword').value;
  if(!email || !password){ setAuthMessage('Enter an email and password first.', true); return; }
  const cap = captchaOptions(); if(!cap) return;
  setAuthMessage('Signing up…', false);
  const { error } = await sb.auth.signUp({ email, password, options: { ...cap, emailRedirectTo: AUTH_REDIRECT_URL } });
  resetCaptcha();
  if(error){ setAuthMessage(friendlyAuthError(error), true); revealPasswordToggle(); return; }
  setAuthMessage('Check your email to confirm your account, then log in.', false);
}

async function handleLogIn(){
  if(!sb){ setAuthMessage('Cloud sync unavailable (Supabase failed to load).', true); return; }
  const email = document.getElementById('authEmail').value.trim();
  const password = document.getElementById('authPassword').value;
  if(!email || !password){ setAuthMessage('Enter an email and password first.', true); return; }
  const cap = captchaOptions(); if(!cap) return;
  setAuthMessage('Logging in…', false);
  const { error } = await sb.auth.signInWithPassword({ email, password, options: cap });
  resetCaptcha();
  if(error){ setAuthMessage(friendlyAuthError(error), true); revealPasswordToggle(); return; }
  setAuthMessage('', false);
  resetPasswordToggle();
}

async function handleForgotPassword(){
  if(!sb){ setAuthMessage('Cloud sync unavailable (Supabase failed to load).', true); return; }
  const email = document.getElementById('authEmail').value.trim();
  if(!email){ setAuthMessage('Type your email in the box first, then click "Forgot password?"', true); document.getElementById('authEmail').focus(); return; }
  const cap = captchaOptions(); if(!cap) return;
  setAuthMessage('Sending reset link…', false);
  const { error } = await sb.auth.resetPasswordForEmail(email, { redirectTo: AUTH_REDIRECT_URL, ...cap });
  resetCaptcha();
  if(error){ setAuthMessage(friendlyAuthError(error), true); return; }
  setAuthMessage('If that email has an account, a reset link is on its way. Check your inbox (and spam).', false);
}

function openPasswordReset(){
  document.getElementById('prPassword').value = '';
  document.getElementById('prPassword2').value = '';
  setResetMessage('', false);
  document.getElementById('passwordReset').hidden = false;
  document.getElementById('prPassword').focus();
}

function setResetMessage(msg, isError){
  const el = document.getElementById('prMessage');
  el.textContent = msg;
  el.classList.toggle('err', !!isError);
}

async function saveNewPassword(){
  const p1 = document.getElementById('prPassword').value;
  const p2 = document.getElementById('prPassword2').value;
  if(p1.length < 8){ setResetMessage('Use at least 8 characters.', true); return; }
  if(p1 !== p2){ setResetMessage("Those passwords don't match.", true); return; }
  setResetMessage('Saving…', false);
  const { error } = await sb.auth.updateUser({ password: p1 });
  if(error){ setResetMessage(error.message, true); return; }
  setResetMessage('Password updated. You\'re signed in.', false);
  setTimeout(()=>{ document.getElementById('passwordReset').hidden = true; }, 1500);
}

// Wipes the collection copy kept in this browser (it belongs to whoever was signed in),
// so the next visitor on this device never sees someone else's checked cards.
function wipeLocalCollection(){
  try{
    const kill = [];
    for(let i=0;i<localStorage.length;i++){
      const k = localStorage.key(i);
      if(k && /^cb:(owned|qty|card|prodowned|prodqty|grade|serial|extra):/.test(k)) kill.push(k);
    }
    kill.forEach(k=>localStorage.removeItem(k));
  }catch(e){}
}
async function handleLogOut(){
  if(!sb) return;
  await sb.auth.signOut();
}

async function loadFromCloud(){
  if(!sb || !currentUser) return;
  setSyncStatus('Syncing…');
  try{
    const { data, error } = await sb
      .from('user_collections')
      .select('data, tier')
      .eq('user_id', currentUser.id)
      .maybeSingle();
    if(error){ console.error('cloud load failed', error); setSyncStatus('Sync failed'); return; }
    if(data){
      currentUserTier = data.tier || 'free';
      if(data.data && Object.keys(data.data).length){
        await applyCollectionData(data.data);
        await migrateMergedPromos();
        if(CARDS.length) maybeShowUnlZhNotice();
      }
    }
    updateAuthUI();
    setSyncStatus('Synced');
    setTimeout(()=>setSyncStatus(''), 2000);
  }catch(e){
    console.error(e);
    setSyncStatus('Sync failed');
  }
}

async function saveToCloud(){
  if(!sb || !currentUser) return;
  setSyncStatus('Saving…');
  try{
    const payload = buildExportData();
    const { error } = await sb
      .from('user_collections')
      .upsert({ user_id: currentUser.id, data: payload, updated_at: new Date().toISOString() }, { onConflict: 'user_id' });
    if(error){ console.error('cloud save failed', error); setSyncStatus('Save failed'); }
    else{ setSyncStatus('Saved'); setTimeout(()=>setSyncStatus(''), 1500); }
  }catch(e){
    console.error(e);
    setSyncStatus('Save failed');
  }
}

function queueCloudSave(){
  // Refresh the "x / 75 items" counter on every change, logged in or not.
  updateAuthUI();
  if(!sb || !currentUser) return;
  clearTimeout(cloudSaveTimer);
  cloudSaveTimer = setTimeout(saveToCloud, 900);
}

loadAffiliateSettings();

if(sb){
  sb.auth.onAuthStateChange(async (event, session) => {
    // Arrived from a "reset your password" email: ask for the new password.
    if(event === 'PASSWORD_RECOVERY') openPasswordReset();
    if(session && session.user){
      // A different person signing in on this browser must not inherit (or upload) the
      // previous person's locally stored collection.
      let lastUser = null;
      try{ lastUser = localStorage.getItem('cb:lastUser'); }catch(e){}
      if(lastUser && lastUser !== session.user.id){
        wipeLocalCollection();
        try{ localStorage.setItem('cb:lastUser', session.user.id); }catch(e){}
        location.reload();
        return;
      }
      try{ localStorage.setItem('cb:lastUser', session.user.id); }catch(e){}
      currentUser = session.user;
      updateAuthUI();
      await loadFromCloud();
    } else {
      currentUser = null;
      currentUserTier = 'free';
      if(event === 'SIGNED_OUT'){
        // Signed out: clear this browser's copy and reload so the page shows an empty tracker.
        wipeLocalCollection();
        try{ localStorage.removeItem('cb:lastUser'); }catch(e){}
        location.reload();
        return;
      }
      updateAuthUI();
    }
  });

  document.getElementById('authSignupBtn').addEventListener('click', handleSignUp);
  document.getElementById('authLoginBtn').addEventListener('click', handleLogIn);
  document.getElementById('authLogoutBtn').addEventListener('click', handleLogOut);
  document.getElementById('authForgotBtn').addEventListener('click', handleForgotPassword);
  document.getElementById('prSave').addEventListener('click', saveNewPassword);
  setupCaptcha();
} else {
  setAuthMessage('Cloud sync unavailable (Supabase library failed to load). The tracker itself still works.', true);
}


// ---------- Collapsible section headings (all tabs) ----------
// Click a heading (or press Enter/Space) to fold away its grid. The folded
// state is remembered while the page is open, even as filters re-render the
// lists, so a viewer can hide sections they don't care about and just scroll.
const collapsedGroups = new Set();
function groupKey(container, h){
  return container.id + '|' + (h.firstChild ? h.firstChild.textContent : h.textContent).trim();
}
function nextGrid(h){
  let n = h.nextElementSibling;
  while(n && !n.classList.contains('grid')){
    if(n.classList.contains('group-heading')) return null;
    n = n.nextElementSibling;
  }
  return n;
}
const COLLAPSE_TIP_HTML = '<b>Tip:</b> click the glowing <span class="tip-arrow">\u25BE</span> arrow next to any section title to collapse or expand that section, so you can skip what you don\u2019t want to scroll through.';
function ensureCollapseTip(container){
  const first = container.querySelector('.group-heading');
  if(!first) return;
  const jump = container.querySelector('.promo-section-jump');
  if(jump){
    if(!jump.querySelector('.psj-tip')){
      const t = document.createElement('div'); t.className = 'psj-tip'; t.innerHTML = COLLAPSE_TIP_HTML; jump.appendChild(t);
    }
  } else if(!container.querySelector('.collapse-tip')){
    const t = document.createElement('div'); t.className = 'collapse-tip'; t.innerHTML = COLLAPSE_TIP_HTML;
    first.parentNode.insertBefore(t, first);
  }
}
function applyGroupState(container){
  ensureCollapseTip(container);
  container.querySelectorAll('.group-heading').forEach(h=>{
    h.setAttribute('role','button'); h.tabIndex = 0;
    const closed = collapsedGroups.has(groupKey(container, h));
    h.classList.toggle('collapsed', closed);
    h.setAttribute('aria-expanded', closed ? 'false' : 'true');
    const g = nextGrid(h); if(g) g.classList.toggle('group-collapsed', closed);
  });
}
function toggleGroup(container, h){
  const key = groupKey(container, h);
  if(collapsedGroups.has(key)) collapsedGroups.delete(key); else collapsedGroups.add(key);
  applyGroupState(container);
  fitSidePanels();
}
['results','setResults','productResults','binderResults'].forEach(id=>{
  const c = document.getElementById(id);
  if(!c) return;
  new MutationObserver(()=>applyGroupState(c)).observe(c, {childList:true});
  c.addEventListener('click', e=>{
    const h = e.target.closest && e.target.closest('.group-heading');
    if(!h || e.target.closest('a,button.psj-link')) return;
    toggleGroup(c, h);
  });
  c.addEventListener('keydown', e=>{
    if(e.key!=='Enter' && e.key!==' ') return;
    const h = e.target.closest && e.target.closest('.group-heading');
    if(!h) return;
    e.preventDefault(); toggleGroup(c, h);
  });
  applyGroupState(c);
});

// Side panels show at full length. Short panels stick below the header.
// Panels taller than the screen scroll along with the page until their
// bottom edge is in view, then stay put, so every control is reachable.
function fitSidePanels(){
  // The side panel is now a pull-out menu sized by CSS; just clear any old inline sizing.
  document.querySelectorAll('.side-panel').forEach(p=>{ p.style.top=''; p.style.bottom=''; });
}
function fitSidePanelsOld(){
  document.querySelectorAll('.side-panel').forEach(p=>{
    if(window.innerWidth <= 900 || !p.offsetHeight){ p.style.top=''; p.style.bottom=''; return; }
    const offset = parseFloat(getComputedStyle(p).getPropertyValue('--embed-header-offset')) || 140;
    const room = window.innerHeight - offset - 28;
    if(p.offsetHeight > room){
      // Taller than the viewport: don't pin it near the top (that would
      // trap its lower half permanently off-screen). Instead let it scroll
      // with the page until its bottom nears the viewport's bottom edge,
      // then stick there, so the whole panel stays reachable.
      p.style.top = 'auto';
      p.style.bottom = '14px';
    } else {
      p.style.top = '';
      p.style.bottom = '';
    }
  });
}
window.addEventListener('resize', fitSidePanels);

// Pull-out side menus: add the gold tab to each tab's side panel.
(function setupSideMenus(){
  const panels = [...document.querySelectorAll('.panel-layout .side-panel')];
  const closeAll = except => panels.forEach(p=>{
    if(p === except) return;
    p.classList.remove('open');
    p.scrollTop = 0;   // closed, the panel is only the button: keep it at the top
    const t = p.querySelector('.sp-tab'); if(t) t.setAttribute('aria-expanded','false');
  });
  panels.forEach(p=>{
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'sp-tab';
    b.setAttribute('aria-label','Filters and stats'); b.setAttribute('aria-expanded','false');
    b.title = 'Filters & stats';
    b.innerHTML = '<svg class="sp-burger" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M4 6h16M4 12h16M4 18h16"/></svg><span class="sp-close" aria-hidden="true">&times;</span>';
    p.prepend(b);
    b.addEventListener('click', e=>{
      e.stopPropagation();
      const open = !p.classList.contains('open');
      closeAll(p);
      p.classList.toggle('open', open);
      p.scrollTop = 0;
      b.setAttribute('aria-expanded', String(open));
      if(!open) b.blur();
    });
  });
  document.addEventListener('click', e=>{
    if(!e.target.closest || !e.target.closest('.panel-layout .side-panel')) closeAll(null);
  });
  document.addEventListener('keydown', e=>{
    if(e.key === 'Escape'){ closeAll(null); if(document.activeElement && document.activeElement.closest && document.activeElement.closest('.side-panel')) document.activeElement.blur(); }
  });
})();
if('ResizeObserver' in window){
  const panelWatcher = new ResizeObserver(fitSidePanels);
  document.querySelectorAll('.side-panel').forEach(p=>panelWatcher.observe(p));
}

