function t(key, vars){
  let str = (I18N.en[key] !== undefined) ? I18N.en[key] : key;
  if(vars) for(const [k,v] of Object.entries(vars)) str = str.split('{'+k+'}').join(String(v));
  return str;
}

function langForCard(card){
  const v = String((card && card.language) || '').trim().toLowerCase();
  return CARD_LANGS.find(l => v === l.data.toLowerCase()) || DEFAULT_PRICING;
}

function printingLabel(style){ return t('printing.'+style) === 'printing.'+style ? style : t('printing.'+style); }

function condOptionsHtml(selected){
  const sel = COND_CODES.includes(selected) ? selected : 'NM';
  return COND_CODES.map(c=>`<option value="${c}"${c===sel?' selected':''}>${escapeHtml(t('cond.'+c))}</option>`).join('');
}

function ensureOption(select, value){
  if(!select || !value) return;
  if(![...select.options].some(o=>o.value===value)){
    const o = document.createElement('option'); o.value = value; o.textContent = value; select.appendChild(o);
  }
}

// Point both tabs' Language filters at the chosen card language.
function applyCardLanguage(code){
  const L = CARD_LANGS.find(l=>l.code===code);
  const val = L ? L.data : '';
  const pf = document.getElementById('languageFilter');
  const sf = document.getElementById('setLanguageFilter');
  ensureOption(pf, val); ensureOption(sf, val);
  state.language = val;    if(pf) pf.value = val;
  setState.language = val; if(sf) sf.value = val;
  renderResults();
  renderSetResults();
  renderStats();
  renderSetStats();
  if(typeof refreshExtraTabsIfVisible === 'function') refreshExtraTabsIfVisible();
}

// Called once card data has loaded, so empty languages can show as "coming soon".
function cbInitCardLanguage(){
  const sel = document.getElementById('cardLangSelect');
  if(!sel) return;
  const has = l => ITEMS.some(i=>i.language===l.data) || CARDS.some(c=>c.language===l.data);
  sel.innerHTML = '<option value="">All languages</option>' + CARD_LANGS.map(l=>
    `<option value="${l.code}">${escapeHtml(l.label)}${has(l)?'':' — coming soon'}</option>`).join('');
  cbAddComingSoonOptions();
  cbInitChipSync();
  cbInitPromoSetFilter();

  let saved = '';
  try{ saved = localStorage.getItem('cb:cardLang') || ''; }catch(e){}
  const savedLang = CARD_LANGS.find(l=>l.code===saved);
  if(savedLang){ sel.value = saved; applyCardLanguage(saved); }

  sel.addEventListener('change', e=>{
    const code = e.target.value;
    try{ localStorage.setItem('cb:cardLang', code); }catch(err){}
    applyCardLanguage(code);
  });
  // If someone uses a tab's own Language filter, keep the top picker in step.
  ['languageFilter','setLanguageFilter'].forEach(id=>{
    const el = document.getElementById(id);
    if(el) el.addEventListener('change', ()=>{
      const L = CARD_LANGS.find(l=>l.data===el.value);
      sel.value = L ? L.code : '';
    });
  });
}

