// Colour-coded language bubble used on every tab's tiles.
function langPipHtml(language){
  return `<span class="pip lang-pip" data-lang="${escapeHtml(language)}">${escapeHtml(language)}</span>`;
}

// Language field: this item's language, then the other languages it exists in
// as clickable bubbles that open that version.
const LANG_ORDER = ['English','Chinese','French','Korean'];
function languageFieldHtml(language, others){
  if(!language) return '&mdash;';
  const list = (others||[]).filter(o=>o.language && o.language !== language)
    .sort((a,b)=>LANG_ORDER.indexOf(a.language)-LANG_ORDER.indexOf(b.language));
  if(!list.length) return langPipHtml(language);
  return `${langPipHtml(language)}<div class="lang-also"><span>Also in:</span>${list.map(o=>
    `<button type="button" class="pip lang-pip lang-also-btn" data-lang="${escapeHtml(o.language)}" onclick="openModal('${o.id}')" title="Open the ${escapeHtml(o.language)} version">${escapeHtml(o.language)} &rarr;</button>`).join('')}</div>`;
}
// Same card in other languages: same set + collector number.
function cardLanguageSiblings(card){
  const num = String(card.collectorNum||'').toLowerCase().replace(/^0+(?=\d)/,'');
  const seen = new Set([card.language]), out = [];
  CARDS.forEach(o=>{
    if(o.id === card.id || o.setCode !== card.setCode || seen.has(o.language)) return;
    if(String(o.collectorNum||'').toLowerCase().replace(/^0+(?=\d)/,'') !== num || !num) return;
    seen.add(o.language); out.push(o);
  });
  return out;
}

function langFlagHtml(language, mix){
  const code = LANG_FLAG[String(language || '').trim()];
  if(!code || !FLAG_SVGS[code]) return '';
  const second = mix && LANG_FLAG[String(mix).trim()];
  if(second && FLAG_SVGS[second] && second !== code){
    const label = `${language} event, ${mix} card`;
    return `<span class="lang-flag lang-flag-split" title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}" role="img"><span class="lf-half lf-left">${FLAG_SVGS[code]}</span><span class="lf-half lf-right">${FLAG_SVGS[second]}</span></span>`;
  }
  const label = `${language} edition`;
  return `<span class="lang-flag" title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}" role="img">${FLAG_SVGS[code]}</span>`;
}

