// When a language has no promos yet, say so instead of showing an empty grid.
function promosComingSoonHtml(){
  if(state.set && PROMO_SET_NOTES[state.set] && !ITEMS.some(i=>i.set===state.set && (!state.language || i.language===state.language))){
    const name = PROMO_SET_NAMES[state.set] || state.set;
    return comingSoonPanel(`${name} promos & collectibles are on the way`,
      `${name} promos and collectibles${state.language ? ' in '+state.language : ''} haven't been added yet. Check back soon.`);
  }
  if(state.language && !ITEMS.some(i=>i.language===state.language)){
    return comingSoonPanel(`${state.language} promos & collectibles are on the way`,
      `${state.language} promos and collectibles haven't been added to the tracker yet. Check back soon — in the meantime, pick another language to browse.`);
  }
  return '';
}

