/* ---------- Condition of owned copies (saved with the binder) ---------- */

function getCardCond(id, style){
  const c = setState.cond[id] && setState.cond[id][style];
  return COND_CODES.includes(c) ? c : 'NM';
}

async function setCardCondition(id, style, value){
  if(!COND_CODES.includes(value)) return;
  if(!setState.cond[id]) setState.cond[id] = { Normal:'', Foil:'' };
  setState.cond[id][style] = value;
  await saveCardOwnership(id);
  queueCloudSave();
}

/* ---------- VIP price lookup via the convert-tcg-price Edge Function ---------- */

const PRICE_FUNCTION = 'convert-tcg-price';
const PRICE_CACHE_MS = 10 * 60 * 1000; // reuse an answer for 10 minutes
const priceCache = new Map();
let priceReqSeq = 0;
let priceDebounceTimer = null;
const priceSel = { cardId:null, printing:null, condition:null };

// What gets sent to the Edge Function. If your function expects different
// field names, this is the only place that needs to change.
function buildPriceRequest(card, printing, condition){
  const loc = langForCard(card);
  return {
    card_id: card.id,
    card_name: card.name,
    set_code: card.setCode,
    collector_number: card.collectorNum,
    card_language: card.language,   // e.g. 'Korean'
    language: loc.code,             // 'en' | 'zh' | 'ko' | 'fr'
    printing,                 // 'Normal' | 'Foil'
    condition,                // 'NM' | 'LP' | 'MP' | 'HP' | 'DMG'
    // VIP can choose the currency; otherwise that language's market currency, e.g. 'KRW'
    currency: activeDisplayCurrency() !== 'USD' ? activeDisplayCurrency() : loc.currency,
    country: loc.country,           // e.g. 'KR'
    locale: loc.locale,             // e.g. 'ko-KR'
    foil_only: card.printings.length === 1 && card.printings[0] === 'Foil'
  };
}

// Reads the Edge Function's reply. Accepts a few common shapes, e.g.
//   { price: 12.5, currency: 'EUR', source: 'Cardmarket', updated_at: '...' }
//   { converted_price: 12.5, currency: 'EUR' }
//   { data: { prices: { market: 12.5, low: 9, high: 15 }, currency: 'EUR' } }
// Returns null when there's no usable number, so nothing gets made up.
function readPriceResponse(raw){
  let data = raw;
  if(typeof data === 'string'){ try{ data = JSON.parse(data); }catch(e){ return null; } }
  if(!data || typeof data !== 'object') return null;
  const d = (data.data && typeof data.data === 'object') ? data.data : data;
  const p = (d.prices && typeof d.prices === 'object') ? d.prices : d;
  const num = v => (typeof v === 'number' && isFinite(v)) ? v
    : (typeof v === 'string' && v.trim() !== '' && isFinite(Number(v))) ? Number(v) : null;
  const pick = (...vals) => { for(const v of vals){ const n = num(v); if(n !== null) return n; } return null; };
  const market = pick(p.market, p.price, p.converted_price, p.convertedPrice, p.amount, p.mid);
  const low = pick(p.low, p.min);
  const high = pick(p.high, p.max);
  if(market === null && low === null && high === null) return null;
  const cur = (d.currency || p.currency || d.target_currency || '');
  return {
    market, low, high,
    currency: /^[A-Za-z]{3}$/.test(cur) ? cur.toUpperCase() : null,
    source: d.source || d.marketplace || p.source || null,
    updatedAt: d.updated_at || d.updatedAt || d.timestamp || null
  };
}

// USD figures only count if the service clearly labels them USD — a reply
// in the wrong currency is never shown with a $ sign.
function readUsdReply(raw){
  const p = readPriceResponse(raw);
  return (p && p.currency === 'USD') ? p : null;
}
// If your function already includes USD in the main reply, e.g.
//   { price: 15000, currency:'KRW', usd: { price: 10.9 } }  or  { price_usd: 10.9 }
// it's used directly and the second request is just a backup.
function readUsdFromReply(raw){
  let data = raw;
  if(typeof data === 'string'){ try{ data = JSON.parse(data); }catch(e){ return null; } }
  if(!data || typeof data !== 'object') return null;
  const d = (data.data && typeof data.data === 'object') ? data.data : data;
  const nested = d.usd || (d.converted && (d.converted.USD || d.converted.usd));
  if(nested && typeof nested === 'object'){
    const p = readPriceResponse({ ...nested, currency:'USD' });
    if(p) return p;
  }
  const flat = d.price_usd ?? d.usd_price ?? d.priceUsd ?? (typeof d.usd === 'number' || typeof d.usd === 'string' ? d.usd : undefined);
  if(flat !== undefined){
    const p = readPriceResponse({ price: flat, currency:'USD' });
    if(p) return p;
  }
  return null;
}

function formatMoney(n, currency, locale){
  try{ return new Intl.NumberFormat(locale, { style:'currency', currency }).format(n); }
  catch(e){ return `${n.toFixed(2)} ${currency}`; }
}

/* ---------- VIP "Show prices in" ----------
   Prices are saved in US dollars. VIP members can pick a currency; amounts are
   converted with daily exchange rates (get-price-history 'rates') and the USD
   figure is still shown next to the main numbers. */
const DISPLAY_CURRENCIES = ['USD','EUR','GBP','CAD','AUD','CNY','KRW','JPY'];
let fxRates = null, fxLoading = null;
let displayCurrencyPref = 'USD';
try{ const c = localStorage.getItem('cb:displayCurrency'); if(DISPLAY_CURRENCIES.includes(c)) displayCurrencyPref = c; }catch(e){}
function activeDisplayCurrency(){
  if(!MEMBERSHIP_ENABLED || !isVipTier()) return 'USD';
  const c = displayCurrencyPref;
  return (c !== 'USD' && fxRates && fxRates[c]) ? c : 'USD';
}
// usd -> text in the viewer's chosen currency (USD for everyone else)
function displayMoney(usd){
  const n = Number(usd);
  const c = activeDisplayCurrency();
  if(c === 'USD') return formatMoney(n, 'USD', 'en-US');
  return formatMoney(n * fxRates[c], c, 'en-US');
}
// small "≈ $12.34 USD" line when another currency is showing
function usdAside(usd){
  return activeDisplayCurrency() === 'USD' ? '' : `<span class="cbp-usd">≈ ${escapeHtml(formatMoney(Number(usd), 'USD', 'en-US'))} USD</span>`;
}
async function loadFxRates(){
  if(fxRates || !sb || !isVipTier()) return fxRates;
  if(!fxLoading){
    fxLoading = sb.functions.invoke(HISTORY_FUNCTION, { body:{ mode:'rates' } })
      .then(r => { if(r.error) throw r.error; fxRates = (r.data && r.data.rates) || null; return fxRates; })
      .catch(e => { console.warn('[Collection-Bound] exchange rates failed', e); fxLoading = null; return null; });
  }
  return fxLoading;
}
function currencyPickerHtml(){
  if(!MEMBERSHIP_ENABLED || !isVipTier()) return '';
  const opts = DISPLAY_CURRENCIES.map(c=>`<option value="${c}"${c===displayCurrencyPref?' selected':''}>${c}</option>`).join('');
  return `<label class="cbp-field cb-currency"><span>Show prices in</span><select onchange="setDisplayCurrency(this.value)">${opts}</select></label>`;
}
async function setDisplayCurrency(c){
  if(!DISPLAY_CURRENCIES.includes(c)) return;
  displayCurrencyPref = c;
  try{ localStorage.setItem('cb:displayCurrency', c); }catch(e){}
  if(c !== 'USD') await loadFxRates();
  document.querySelectorAll('.cb-currency select').forEach(sel=>{ sel.value = c; });
  // redraw whatever is showing prices
  const backdrop = document.getElementById('modalBackdrop');
  if(backdrop && backdrop.classList.contains('open')){
    if(currentModalKind === 'card' && currentModalId) openModal(currentModalId);
    else if(document.getElementById('moversPanel') && document.getElementById('moversPanel').style.display !== 'none') renderMoversPanel();
  }
  loadBinderValue();
}

function formatUpdated(v, locale){
  const d = new Date(v);
  if(isNaN(d)) return String(v);
  try{ return new Intl.DateTimeFormat(locale, { dateStyle:'medium', timeStyle:'short' }).format(d); }
  catch(e){ return d.toLocaleString(); }
}

function defaultPriceSelection(card){
  const owned = card.printings.find(p=>getCardOwned(card.id, p));
  const printing = owned || card.printings[0];
  return { printing, condition: getCardCond(card.id, printing) };
}

function cardPriceSectionHtml(card){
  if(!MEMBERSHIP_ENABLED) return '';
  if(!isVipTier()) return basicPriceSectionHtml(card); // today's price for everyone; history for Club
  if(priceSel.cardId !== card.id || !card.printings.includes(priceSel.printing)){
    const d = defaultPriceSelection(card);
    priceSel.cardId = card.id; priceSel.printing = d.printing; priceSel.condition = d.condition;
  }
  const printingOpts = card.printings.map(p=>
    `<option value="${escapeHtml(p)}"${p===priceSel.printing?' selected':''}>${escapeHtml(printingLabel(p))}</option>`).join('');
  return `
    <div class="card-value-section">
      <div class="card-value-label">${escapeHtml(t('price.label'))} <span class="card-value-vip-tag">VIP</span></div>
      <div class="cbp-controls">
        <label class="cbp-field"><span>${escapeHtml(t('price.printing'))}</span>
          <select id="cbpPrinting" onchange="onPricePrintingChange(this.value)">${printingOpts}</select></label>
        <label class="cbp-field"><span>${escapeHtml(t('m.condition'))}</span>
          <select id="cbpCondition" onchange="onPriceConditionChange(this.value)">${condOptionsHtml(priceSel.condition)}</select></label>
        ${currencyPickerHtml()}
      </div>
      <div class="cbp-out" id="cbpOut" aria-live="polite"></div>
    </div>`;
}

/* ---------- Today's price (free + Collector Club) ----------
   Reads the newest saved TCGplayer price from get-price-history, so it needs
   no login. Club members also get the price history chart. */
function basicPriceSectionHtml(card){
  if(priceSel.cardId !== card.id || !card.printings.includes(priceSel.printing)){
    const d = defaultPriceSelection(card);
    priceSel.cardId = card.id; priceSel.printing = d.printing; priceSel.condition = d.condition;
  }
  const printingOpts = card.printings.map(p=>
    `<option value="${escapeHtml(p)}"${p===priceSel.printing?' selected':''}>${escapeHtml(printingLabel(p))}</option>`).join('');
  return `
    <div class="card-value-section">
      <div class="card-value-label">Today's Price</div>
      <div class="cbp-controls">
        <label class="cbp-field"><span>${escapeHtml(t('price.printing'))}</span>
          <select id="cbpPrinting" onchange="onBasicPrintingChange(this.value)">${printingOpts}</select></label>
      </div>
      <div class="cbp-out" id="cbpOut" aria-live="polite"></div>
    </div>`;
}
function onBasicPrintingChange(value){
  const card = CARDS.find(c=>c.id===priceSel.cardId);
  if(!card || !card.printings.includes(value)) return;
  priceSel.printing = value;
  requestBasicPrice(card);
}
const basicPriceCache = new Map();
async function requestBasicPrice(card){
  const out = document.getElementById('cbpOut'); if(!out) return;
  const body = buildPriceRequest(card, priceSel.printing, 'NM');
  const upgrade = (tier, text) => `<a href="#" class="bv-tease" onclick="event.preventDefault(); closeModal(); openMembershipChooser('${tier}');">${text}</a>`;
  if(body.card_language !== 'English'){
    out.innerHTML = `<div class="cbp-msg">&#128274; ${escapeHtml(body.card_language)} market prices from CardTrader, side by side with US prices, are a VIP feature.</div>
      ${upgrade('tier2', 'Go VIP for international prices &rarr;')}${priceLinksHtml(body)}`;
    return;
  }
  if(!sb){ out.innerHTML = `<div class="cbp-msg">${escapeHtml(t('price.unavailable'))}</div>${priceLinksHtml(body)}`; return; }
  const key = body.card_id + '|' + body.printing;
  let res = basicPriceCache.get(key);
  if(!res){
    out.innerHTML = `<div class="cbp-msg">${escapeHtml(t('price.loading'))}</div>`;
    try{
      const r = await sb.functions.invoke(HISTORY_FUNCTION, { body: { mode:'current', set_code: body.set_code,
        collector_number: body.collector_number, card_name: body.card_name, card_language: body.card_language, printing: body.printing } });
      if(r.error) throw r.error;
      res = r.data || {};
      basicPriceCache.set(key, res);
    }catch(e){ console.warn('[Collection-Bound] current price failed', e); res = { error:true }; }
  }
  if(priceSel.cardId !== card.id || priceSel.printing !== body.printing) return;
  const el = document.getElementById('cbpOut'); if(!el) return;
  if(res.error || res.status !== 'ok'){
    el.innerHTML = `<div class="cbp-msg">${escapeHtml(t('price.unavailable'))}</div>${priceLinksHtml(body)}`;
    return;
  }
  const money = v => formatMoney(v, 'USD', 'en-US');
  const stats = [['price.market', res.market], ['price.low', res.low], ['price.high', res.high]]
    .filter(([,v]) => v !== null && v !== undefined)
    .map(([k,v]) => `<div class="cbp-stat"><span class="cbp-k">${escapeHtml(t(k))}</span><span class="cbp-v">${escapeHtml(money(v))}</span></div>`).join('');
  const day = new Date(res.day+'T12:00:00').toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' });
  const history = isPaidTier()
    ? '<div class="cbp-trend" id="cbpTrend"></div>'
    : upgrade('tier1', "&#128200; See this card's price history back to June 2025 with the Collector Club &rarr;");
  el.innerHTML = `<div class="cbp-stats">${stats}</div>
    <div class="cbp-meta">Source: TCGplayer (via TCGCSV), Near Mint, USD &middot; Updated ${escapeHtml(day)}</div>
    ${history}${priceLinksHtml(body)}`;
  if(isPaidTier()) loadPriceTrend(body, trendDays);
}

function queuePriceRequest(){
  clearTimeout(priceDebounceTimer);
  priceDebounceTimer = setTimeout(()=>{
    const card = CARDS.find(c=>c.id===priceSel.cardId);
    if(card) requestCardPrice(card);
  }, 250);
}

function onPricePrintingChange(value){
  const card = CARDS.find(c=>c.id===priceSel.cardId);
  if(!card || !card.printings.includes(value)) return;
  priceSel.printing = value;
  priceSel.condition = getCardCond(card.id, value); // follow the condition you own it in
  const condEl = document.getElementById('cbpCondition');
  if(condEl) condEl.value = priceSel.condition;
  queuePriceRequest();
}

function onPriceConditionChange(value){
  if(!COND_CODES.includes(value)) return;
  priceSel.condition = value;
  queuePriceRequest();
}

function retryCardPrice(){
  const card = CARDS.find(c=>c.id===priceSel.cardId);
  if(card) requestCardPrice(card);
}

async function requestCardPrice(card){
  const out = document.getElementById('cbpOut');
  if(!out) return;
  if(!sb || !currentUser){ renderPrice({ ok:false }, null); return; }

  const body = buildPriceRequest(card, priceSel.printing, priceSel.condition);
  const key = JSON.stringify([body.card_id, body.printing, body.condition, body.currency, body.country]);
  const cached = priceCache.get(key);
  if(cached && Date.now() - cached.at < PRICE_CACHE_MS){ renderPrice(cached.result, body); return; }

  const seq = ++priceReqSeq;
  out.innerHTML = `<div class="cbp-msg">${escapeHtml(t('price.loading'))}</div>`;

  let result;
  try{
    // Uses this page's signed-in Supabase client (sb), so the user's login
    // token is sent along with the request automatically.
    // Non-USD cards also ask for the same market's price converted to USD,
    // using your function's exchange rates, so viewers can compare markets.
    const needUsd = body.currency !== 'USD';
    const usdBody = needUsd ? { ...body, currency:'USD', compare_currency:'USD' } : null;
    const [main, usdReply] = await Promise.all([
      sb.functions.invoke(PRICE_FUNCTION, { body }),
      needUsd ? sb.functions.invoke(PRICE_FUNCTION, { body: usdBody }).catch(e=>({ error:e })) : Promise.resolve(null)
    ]);
    if(main.error) throw main.error;
    const price = readPriceResponse(main.data);
    const usd = needUsd ? (readUsdFromReply(main.data) || (usdReply && !usdReply.error ? readUsdReply(usdReply.data) : null)) : null;
    result = { ok:true, price, usd };
    priceCache.set(key, { at: Date.now(), result });
  }catch(err){
    let detail = err && err.message;
    try{ if(err && err.context && typeof err.context.text === 'function') detail = await err.context.text(); }catch(e){}
    console.warn('[Collection-Bound] convert-tcg-price failed:', detail, err);
    result = { ok:false };
  }

  // Ignore answers that arrive after the person moved to another card or option.
  if(seq !== priceReqSeq || priceSel.cardId !== card.id) return;
  renderPrice(result, body);
}

/* "Find this card" outbound search links under the price panel. Plain links
   only — nothing is fetched from these sites. */
function cbCopyHint(btn){
  const txt = btn.getAttribute('data-copy') || '';
  const done = () => { const o = btn.textContent; btn.textContent = 'Copied \u2713'; setTimeout(()=>{ btn.textContent = o; }, 1600); };
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(txt).then(done, ()=>{ cbCopyFallback(txt); done(); });
  } else { cbCopyFallback(txt); done(); }
}
function cbCopyFallback(txt){
  const ta = document.createElement('textarea');
  ta.value = txt; ta.style.position = 'fixed'; ta.style.opacity = '0';
  document.body.appendChild(ta); ta.select();
  try{ document.execCommand('copy'); }catch(e){}
  ta.remove();
}

/* ---------- VIP price trends + market movers (get-price-history) ----------
   English cards only: daily TCGplayer market prices saved by the
   snapshot-prices job, starting November 4, 2026. */
const HISTORY_FUNCTION = 'get-price-history';
const PRICE_HISTORY_START = 'November 4, 2026';
let trendDays = 30;
let trendBody = null;
const trendCache = new Map();

async function loadPriceTrend(body, days){
  trendBody = body; trendDays = days;
  const box = document.getElementById('cbpTrend'); if(!box || !sb) return;
  const key = [body.card_id, body.printing, days].join('|');
  let res = trendCache.get(key);
  if(!res){
    box.innerHTML = `<div class="cbp-meta">Loading price trend…</div>`;
    try{
      const r = await sb.functions.invoke(HISTORY_FUNCTION, { body: {
        mode:'card', set_code: body.set_code, collector_number: body.collector_number,
        card_name: body.card_name, card_language: body.card_language, printing: body.printing, days } });
      if(r.error) throw r.error;
      res = r.data || {};
      trendCache.set(key, res);
    }catch(e){ console.warn('[Collection-Bound] price history failed', e); res = { error:true }; }
  }
  if(trendBody !== body) return;
  const el = document.getElementById('cbpTrend'); if(el) el.innerHTML = priceTrendHtml(res, days);
}
function setTrendDays(d){ if(trendBody) loadPriceTrend(trendBody, d); }

function priceTrendHtml(res, days, o){
  o = o || {};
  const field = o.field || 'market';
  const btns = [7,30,90].map(d=>`<button type="button" class="trend-btn${d===days?' on':''}" onclick="${o.fn || 'setTrendDays'}(${d})">${d}d</button>`).join('');
  const head = `<div class="trend-head"><span class="cbp-k">${o.title || 'Price trend'}</span><span class="trend-btns">${btns}</span></div>`;
  if(res.error) return head + `<div class="cbp-meta">The price trend couldn't load right now.</div>`;
  const pts = (res.history||[]).filter(h=>typeof h[field]==='number' || (h[field]!==null && h[field]!==undefined && !isNaN(Number(h[field]))))
    .map(h=>({ day:h.day, v:Number(h[field]) }));
  if(pts.length < 2){
    if(o.empty) return head + o.empty(pts.length);
    return head + `<div class="cbp-meta">Price history started ${PRICE_HISTORY_START}. This chart fills in as daily prices are saved${pts.length===1 ? ' (1 day so far)' : ''}.</div>`;
  }
  const W=300, H=110, L=40, R=8, T=10, B=22;
  const vals = pts.map(p=>p.v), min = Math.min(...vals), max = Math.max(...vals);
  const pad = (max-min) * 0.1 || Math.max(max*0.05, 0.5);
  const lo = Math.max(0, min-pad), hi = max+pad;
  const x = i => L + (W-L-R) * (pts.length===1 ? 0 : i/(pts.length-1));
  const y = v => T + (H-T-B) * (1 - (v-lo)/(hi-lo));
  const line = pts.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p.v).toFixed(1)}`).join(' ');
  const area = `${line} L${x(pts.length-1).toFixed(1)},${H-B} L${x(0).toFixed(1)},${H-B} Z`;
  const money = v => displayMoney(v);
  const first = pts[0], last = pts[pts.length-1];
  const ch = last.v - first.v, pct = first.v ? ch/first.v*100 : 0;
  const cls = ch > 0 ? 'up' : ch < 0 ? 'down' : '';
  const fmtDay = d => new Date(d+'T12:00:00').toLocaleDateString('en-US', { month:'short', day:'numeric' });
  const svg = `<svg class="trend-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${o.title ? escapeHtml(o.title) : 'Market price'} from ${escapeHtml(money(first.v))} to ${escapeHtml(money(last.v))}">
    <line x1="${L}" y1="${y(hi-pad/2).toFixed(1)}" x2="${W-R}" y2="${y(hi-pad/2).toFixed(1)}" class="trend-grid"/>
    <line x1="${L}" y1="${y(lo+pad/2).toFixed(1)}" x2="${W-R}" y2="${y(lo+pad/2).toFixed(1)}" class="trend-grid"/>
    <text x="${L-4}" y="${(y(hi-pad/2)+3).toFixed(1)}" text-anchor="end" class="trend-axis">${escapeHtml(money(hi-pad/2))}</text>
    <text x="${L-4}" y="${(y(lo+pad/2)+3).toFixed(1)}" text-anchor="end" class="trend-axis">${escapeHtml(money(lo+pad/2))}</text>
    <path d="${area}" class="trend-area"/><path d="${line}" class="trend-line"/>
    <circle cx="${x(pts.length-1).toFixed(1)}" cy="${y(last.v).toFixed(1)}" r="3.2" class="trend-dot"/>
    <text x="${L}" y="${H-6}" class="trend-axis">${escapeHtml(fmtDay(first.day))}</text>
    <text x="${W-R}" y="${H-6}" text-anchor="end" class="trend-axis">${escapeHtml(fmtDay(last.day))}</text>
  </svg>`;
  return head + svg + `<div class="trend-sum ${cls}">${ch>=0?'+':''}${escapeHtml(money(ch))} (${ch>=0?'+':''}${pct.toFixed(1)}%) since ${escapeHtml(fmtDay(first.day))}</div>
    <div class="cbp-meta">${o.caption || `Daily market price, English ${escapeHtml(printingLabel(trendBody.printing))}, Near Mint. Price data: TCGplayer via TCGCSV. Market history, not buying advice.`}</div>`;
}

/* ---------- CardTrader listings for French / Chinese / Korean cards ----------
   Saved daily by snapshot-prices (cheapest Near Mint listings per language).
   These are sellers' asking prices, not sold prices, and are labeled that way. */
const CT_LANGS = ['French','Chinese','Korean'];
let ctDays = 30, ctBody = null;
const ctCache = new Map();
function hasCtPrices(body){ return !!body && CT_LANGS.includes(body.card_language); }
async function loadCtPrice(body, days){
  ctBody = body; ctDays = days;
  const box = document.getElementById('cbpCt'); if(!box || !sb) return;
  const key = [body.card_id, body.printing, days].join('|');
  let res = ctCache.get(key);
  if(!res){
    box.innerHTML = `<div class="cbp-meta">Loading CardTrader listings…</div>`;
    try{
      const r = await sb.functions.invoke(HISTORY_FUNCTION, { body: {
        mode:'cardtrader', set_code: body.set_code, collector_number: body.collector_number, card_name: body.card_name,
        card_language: body.card_language, printing: body.printing, foil_only: !!body.foil_only, days } });
      if(r.error) throw r.error;
      res = r.data || {};
      ctCache.set(key, res);
    }catch(e){ console.warn('[Collection-Bound] CardTrader prices failed', e); res = { error:true }; }
  }
  if(ctBody !== body) return;
  const el = document.getElementById('cbpCt'); if(el) el.innerHTML = ctPriceHtml(res, days, body);
}
function setCtDays(d){ if(ctBody) loadCtPrice(ctBody, d); }
function ctPriceHtml(res, days, body){
  const langName = body.card_language;
  const title = `CardTrader &middot; ${escapeHtml(langName)} listings`;
  if(res.error) return `<div class="cbp-k">${title}</div><div class="cbp-meta">CardTrader listings couldn't load right now.</div>`;
  const latest = res.latest;
  if(res.status !== 'ok' || !latest){
    return `<div class="cbp-k">${title}</div><div class="cbp-meta">No ${escapeHtml(langName)} ${escapeHtml(printingLabel(body.printing))} copies of this card are listed on CardTrader right now.</div>`;
  }
  const cur = res.currency || 'USD';
  const money = v => cur === 'USD' ? displayMoney(v) : formatMoney(v, cur, 'en-US');
  const fmtDay = d => new Date(d+'T12:00:00').toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' });
  const stats = [
    ['Lowest listing', money(latest.low)],
    latest.median !== null ? ['Typical asking', money(latest.median)] : null,
    ['Listings', String(latest.listings)]
  ].filter(Boolean).map(([k,v])=>`<div class="cbp-stat"><span class="cbp-k">${k}</span><span class="cbp-v">${escapeHtml(v)}</span></div>`).join('');
  const chart = priceTrendHtml(res, days, {
    field:'low', fn:'setCtDays', title:'Lowest listing trend',
    empty: () => `<div class="cbp-meta">CardTrader history started November 4, 2026. This chart fills in as daily prices are saved.</div>`,
    caption: `Lowest CardTrader listing each day, ${escapeHtml(langName)} ${escapeHtml(printingLabel(body.printing))}, Near Mint.`
  });
  return `<div class="cbp-k" style="margin-bottom:6px;">${title}</div><div class="cbp-stats">${stats}</div>
    <div class="cbp-meta">Near Mint asking prices from CardTrader sellers, not sold prices. &ldquo;Typical asking&rdquo; is the middle of the cheapest listings. Updated ${escapeHtml(fmtDay(latest.day))}.</div>
    <div class="cbp-trend">${chart}</div>`;
}

let moversDays = 7, moversSet = '';
// Market movers has its own tab now (with card pictures). Old buttons still call this.
function openMarketMovers(days, set){
  if(days) moversDays = days;
  if(set !== undefined) moversSet = set;
  const panel = document.getElementById('moversPanel');
  if(panel && panel.style.display === 'none'){ closeModal(); switchTab('tabMoversBtn'); window.scrollTo({ top: 0 }); return; }
  renderMoversPanel();
}
async function renderMoversPanel(){
  const box = document.getElementById('moversResults'); if(!box) return;
  if(!isVipTier()){
    box.innerHTML = `<div class="member-gate-card"><div class="member-gate-icon">&#128200;</div>
      <div class="member-gate-title">Market movers is a VIP feature</div>
      <div class="member-gate-sub">See which Riftbound cards rose or fell the most in price this week, with daily price trends on every English card.</div>
      <a class="mg-btn" href="#" onclick="event.preventDefault(); openMembershipChooser();">Become a VIP Collector</a></div>`;
    return;
  }
  const sets = ['','OGN','OGS','SFD','UNL','VEN','RAD'];
  const controls = `<div class="movers-controls">
    ${[7,30].map(d=>`<button type="button" class="trend-btn${d===moversDays?' on':''}" onclick="openMarketMovers(${d})">${d === 7 ? 'This week' : 'Last 30 days'}</button>`).join('')}
    <select onchange="openMarketMovers(0, this.value)" aria-label="Set">${sets.map(sc=>`<option value="${sc}"${sc===moversSet?' selected':''}>${sc ? escapeHtml(sc+' — '+(CARD_SET_NAMES[sc]||sc)) : 'All sets'}</option>`).join('')}</select>
    ${currencyPickerHtml() ? `<span class="cbp-controls">${currencyPickerHtml()}</span>` : ''}</div>`;
  box.innerHTML = controls + `<div class="cbp-meta">Loading…</div>`;
  let res;
  try{
    const r = await sb.functions.invoke(HISTORY_FUNCTION, { body:{ mode:'movers', days: moversDays, set_code: moversSet || undefined } });
    if(r.error) throw r.error;
    res = r.data || {};
  }catch(e){ console.warn('[Collection-Bound] movers failed', e); box.innerHTML = controls + `<div class="cbp-meta">Market movers couldn't load right now. Please try again in a moment.</div>`; return; }
  const money = v => displayMoney(v);
  const tile = m => {
    const card = findCardForMover(m);
    const promo = card ? null : findPromoForMover(m);
    const pct = Number(m.pct);
    const name = card ? cardDisplayName(card) : m.name;
    const pic = card && card.img ? card.img : (promo ? promo.img : '');
    const img = pic
      ? `<img src="${escapeHtml(pic)}" alt="${escapeHtml(name)}" loading="lazy" draggable="false" oncontextmenu="return false" onload="if(this.naturalWidth>this.naturalHeight){this.classList.add('is-landscape');}"/>`
      : `<div class="img-fallback"><b>${escapeHtml(name)}</b></div>`;
    const target = card ? card.id : (promo ? promo.id : '');
    return `<div class="card mover-card" ${target ? `onclick="openModal('${target}')" role="button" tabindex="0"` : ''}>
      <div class="img-wrap">${img}<span class="mover-pct-badge ${pct>0?'up':'down'}">${pct>0?'&#9650; +':'&#9660; '}${pct.toFixed(1)}%</span></div>
      <div class="card-body">
        <div class="card-title">${escapeHtml(name)}${card ? overnumberBadgeHtml(card) : ''}</div>
        <div class="card-meta">${escapeHtml(m.set_code||'')} #${escapeHtml(String(m.collector_number||'').replace(/^(\d)$/,'0$1'))} &middot; ${escapeHtml(printingLabel(m.printing))}</div>
        <div class="mover-price">${escapeHtml(money(m.old_price))} &rarr; <b>${escapeHtml(money(m.new_price))}</b></div>
      </div></div>`;
  };
  const up = res.up||[], down = res.down||[];
  if(!up.length && !down.length){
    box.innerHTML = controls + `<div class="cbp-meta">Not enough price history yet. Prices are saved once a day starting ${PRICE_HISTORY_START}, so movers appear after the second day.</div>`;
    return;
  }
  const span = res.base_day && res.latest_day ? `Comparing ${escapeHtml(res.base_day)} with ${escapeHtml(res.latest_day)}. ` : '';
  box.innerHTML = controls + `
    <div class="group-heading">Biggest risers <span class="count">${up.length}</span></div><div class="grid">${up.map(tile).join('') || '<div class="cbp-meta">None</div>'}</div>
    <div class="group-heading">Biggest drops <span class="count">${down.length}</span></div><div class="grid">${down.map(tile).join('') || '<div class="cbp-meta">None</div>'}</div>
    <div class="cbp-meta">${span}English cards, Near Mint market price, cards $1 and up. Price data: TCGplayer via TCGCSV. Market history, not buying advice.</div>`;
}
// The review (Preview) page runs with membership off: hide the VIP-only tab there.
(function(){ const b = document.getElementById('tabMoversBtn'); if(b && !MEMBERSHIP_ENABLED) b.style.display = 'none'; })();
function findCardForMover(m){
  const norm = s => String(s||'').toLowerCase().replace(/\(.*?\)/g,'').replace(/\s+aa\s*$/,'').replace(/[^a-z0-9]/g,'');
  const num = String(m.collector_number||'').toLowerCase().replace(/^([a-z]*)0+(?=\d)/,'$1');
  return CARDS.find(c=>c.language==='English' && c.setCode===m.set_code &&
    String(c.collectorNum||'').toLowerCase().replace(/^([a-z]*)0+(?=\d)/,'$1') === num && norm(c.name) === norm(m.name)) || null;
}
// Some priced cards (Blossom runes, other promo-only printings) live in Promos & Collectibles,
// not the Card Sets list. Use that entry's picture and details for the mover tile.
function findPromoForMover(m){
  const norm = s => String(s||'').toLowerCase().replace(/\(.*?\)/g,'').replace(/[^a-z0-9]/g,'');
  const num = String(m.collector_number||'').toLowerCase().replace(/^([a-z]*)0+(?=\d)/,'$1');
  return ITEMS.find(i=>i.language==='English' && i.img &&
    String(i.collectorNum||'').toLowerCase().replace(/^([a-z]*)0+(?=\d)/,'$1') === num && norm(i.name) === norm(m.name)) || null;
}

function priceLinksHtml(body, label){
  if(!body || !body.card_name) return '';
  // Collection-Bound abbreviates alternate arts as "... AA" to save space. TCGplayer
  // lists them as "... (Alternate Art)" and other sites don't use the label at all.
  const rawName = String(body.card_name);
  const name = rawName.replace(/\s+AA$/, '');
  const sname = shopSearchName(name);   // eBay / Vinted / Bunjang search words
  const tcgName = /\s+AA$/.test(rawName) ? name + ' (Alternate Art)' : name;
  const lang = body.card_language;
  const q = s => encodeURIComponent(s);
  let links = [], who = '', hint = false;
  if(lang === 'English' || !['Chinese','Korean','French'].includes(lang)){
    let u = `https://www.tcgplayer.com/search/riftbound-league-of-legends-trading-card-game/product?productLineName=riftbound-league-of-legends-trading-card-game&q=${q(tcgName)}&view=grid`;
    links = [
      ['TCGplayer', affiliateLink('tcgplayer', u)],
      ['Cardmarket', affiliateLink('cardmarket', `https://www.cardmarket.com/en/Riftbound/Products/Search?searchString=${q(name)}`)],
      ['eBay', affiliateLink('ebay', `https://www.ebay.com/sch/i.html?_nkw=${q(sname + ' riftbound')}`)]
    ];
    who = 'TCGplayer, Cardmarket, or eBay';
  } else if(lang === 'Chinese'){
    links = [
      ['eBay', affiliateLink('ebay', `https://www.ebay.com/sch/i.html?_nkw=${q(sname + ' chinese riftbound')}`)],
      ['Baidu (login)', `https://www.baidu.com/s?wd=${q(name + ' 符文战场 卡牌 价格')}`],
      ['Taobao (login)', affiliateLink('alimama', `https://s.taobao.com/search?q=${q(name + ' Riftbound 符文之地')}`)]
    ];
    who = 'eBay, Baidu, or Taobao/Alimama';
    hint = true;
  } else if(lang === 'Korean'){
    links = [
      ['eBay', affiliateLink('ebay', `https://www.ebay.com/sch/i.html?_nkw=${q(sname + ' riftbound korean')}`)],
      ['Bunjang', `https://m.bunjang.co.kr/search/products?q=${q(name + ' 리프트바운드')}`]
    ];
    who = 'eBay or Bunjang';
  } else if(lang === 'French'){
    links = [
      ['Cardmarket', affiliateLink('cardmarket', `https://www.cardmarket.com/fr/Riftbound/Products/Search?searchString=${q(name)}`)],
      ['Vinted', `https://www.vinted.fr/catalog?search_text=${q(name + ' riftbound')}`],
      ['eBay France', affiliateLink('ebay', `https://www.ebay.fr/sch/i.html?_nkw=${q(sname + ' riftbound fr')}`)]
    ];
    who = 'Cardmarket, Vinted, or eBay';
  }
  if(!links.length) return '';
  return `<div class="market-links"><span class="market-links-label">${label || 'Find this card:'}</span>` +
    links.map(([label, url]) => `<a class="market-link" href="${escapeHtml(url)}" target="_blank" rel="noopener">${label} &#8599;</a>`).join('') +
    (hint ? `<div class="market-hint"><span>Chinese prices are easiest to find in the Jihuanshe (集换社) app, or Exchange Society, its English version. They&rsquo;re app-only (no web link) and some need a sign-in to open photos &mdash; copy the name and search there.</span><button type="button" class="market-copy" data-copy="${escapeHtml(name)}" onclick="cbCopyHint(this)">Copy card name</button></div>` : '') +
    `<div class="market-disclaimer">Not affiliated with or endorsed by ${who}. Some sites may have limited access or require a login depending on your country. We're working to find more reliable options.${anyAffiliateActive() ? ' ' + AFFILIATE_DISCLOSURE : ''}</div></div>`;
}

function renderPrice(result, body){
  const out = document.getElementById('cbpOut');
  if(!out) return;
  const ctBox = hasCtPrices(body) ? '<div class="cbp-trend" id="cbpCt"></div>' : '';
  if(!result.ok){
    out.innerHTML = `<div class="cbp-msg err">${escapeHtml(t('price.error'))}<button type="button" class="cbp-retry" onclick="retryCardPrice()">${escapeHtml(t('price.retry'))}</button></div>${ctBox}${priceLinksHtml(body)}`;
    if(ctBox) loadCtPrice(body, ctDays);
    return;
  }
  const p = result.price;
  if(!p){
    out.innerHTML = (ctBox ? ctBox : `<div class="cbp-msg">${escapeHtml(t('price.unavailable'))}</div>`) + (body.card_language==='English' ? '<div class="cbp-trend" id="cbIntl"></div>' : '') + priceLinksHtml(body);
    if(ctBox) loadCtPrice(body, ctDays);
    if(body.card_language==='English') loadInternational(body);
    return;
  }

  const loc = body.locale;
  const cur = p.currency || body.currency;
  const usd = (cur !== 'USD') ? result.usd : null;
  const stats = [['price.market', p.market, 'market'], ['price.low', p.low, 'low'], ['price.high', p.high, 'high']]
    .filter(([,v]) => v !== null)
    .map(([k,v,f]) => {
      const u = usd && usd[f] !== null && usd[f] !== undefined ? usd[f] : null;
      const usdLine = u !== null ? `<span class="cbp-usd">≈ ${escapeHtml(formatMoney(u, 'USD', 'en-US'))} USD</span>` : '';
      return `<div class="cbp-stat"><span class="cbp-k">${escapeHtml(t(k))}</span><span class="cbp-v">${escapeHtml(formatMoney(v, cur, loc))}</span>${usdLine}</div>`;
    })
    .join('');
  const meta = [
    p.source ? `${escapeHtml(t('price.source'))}: ${escapeHtml(String(p.source))}` : escapeHtml(t('price.noSource')),
    p.updatedAt ? `${escapeHtml(t('price.updated'))}: ${escapeHtml(formatUpdated(p.updatedAt, loc))}` : ''
  ].filter(Boolean).join(' · ');
  const curNote = (p.currency && p.currency !== body.currency)
    ? `<div class="cbp-meta">${escapeHtml(t('price.currencyNote', { cur: p.currency }))}</div>` : '';
  const usdNote = (cur !== 'USD')
    ? `<div class="cbp-meta">${escapeHtml(usd ? t('price.usdNote') : t('price.usdMissing'))}</div>` : '';
  out.innerHTML = `<div class="cbp-stats">${stats}</div><div class="cbp-meta">${meta}</div>${usdNote}${curNote}${body.card_language==='English' ? '<div class="cbp-trend" id="cbpTrend"></div><div class="cbp-trend" id="cbIntl"></div>' : ''}${ctBox}${priceLinksHtml(body)}`;
  if(body.card_language==='English') loadInternational(body);
  if(body.card_language==='English') loadPriceTrend(body, trendDays);
  if(ctBox) loadCtPrice(body, ctDays);
}


/* =====================================================================
   PRODUCTS TAB — sealed Riftbound TCG product
   ---------------------------------------------------------------------
   Data lives in the Supabase product_items table, served by get-products.
   Each entry is one product in one language:
     st: 'ok'   released — shows its image, or "Image Pending" if `ip`
         'tbd'  not yet released in that language (sheet said TBD)
         'soon' details not announced yet (sheet had ___ blanks)
   Languages marked N/A in the sheet aren't listed at all.
   ===================================================================== */

let PRODUCTS = [];
let PRODUCT_LOAD_ERROR = false;

const PRODUCT_SET_NAMES = {
  OGN:'Origins', SFD:'Spiritforged', UNL:'Unleashed', VEN:'Vendetta',
  OGS:'Proving Grounds', RAD:'Radiance', LGC:'Legacy', REC:'The Reckoning'
};
const PRODUCT_SET_ORDER = ['OGN','OGS','SFD','UNL','VEN','RAD','LGC','REC'];

// Official Riot stores for non-TCG merch, shown in the Products disclaimer.
// Leave a url blank to hide that line until a confirmed link is added.
const MERCH_LINKS = [
  { region:'United States', url:'https://merch.riotgames.com/en-us/' },
  { region:'France',        url:'https://merch.riotgames.com/fr-fr/' },
  { region:'Korea',         url:'https://www.riot-store.co.kr/' },
  { region:'China',         url:'https://lolriotmall.qq.com/#/' }
];

const productState = {
  search:'', status:'', type:'', language:'', set:'', sort:'row', view:'grid',
  owned:{}, qty:{}
};

function productReleased(p){ return p.st === 'ok'; }
// Sealed packs listed in both tabs (products.json "pl" = the promo id): one shared check and count,
// stored on the promo entry, so marking either tab marks both without a second binder entry.
function productOwned(p){ return productReleased(p) && (p.pl ? !!state.owned[p.pl] : !!productState.owned[p.id]); }
function productLink(id){ const p = PRODUCTS.find(x=>x.id===id); return p && p.pl ? p.pl : null; }

// Products are served by the get-products Supabase Edge Function (same
// pattern as get-promos / get-cards): 200 per call, rate-limited per IP.
function productApiUrl(){ return `${SUPABASE_URL}/functions/v1/get-products`; }
async function fetchProductPage(offset){
  for(let attempt=0; attempt<4; attempt++){
    const res = await fetch(`${productApiUrl()}?offset=${offset}`, {
      headers: { 'Authorization': `Bearer ${SUPABASE_ANON_KEY}`, 'apikey': SUPABASE_ANON_KEY }
    });
    if(res.ok) return res.json();
    if(res.status === 429){ await new Promise(r=>setTimeout(r, 2000 * (attempt+1))); continue; }
    throw new Error(`HTTP ${res.status}`);
  }
  throw new Error('rate limited');
}
async function fetchAllProducts(){
  const first = await fetchProductPage(0);
  const pageSize = (first.data && first.data.length) || 200;
  const total = first.total || first.data.length;
  const jobs = [];
  for(let off = pageSize; off < total; off += pageSize) jobs.push(fetchProductPage(off));
  const rest = await Promise.all(jobs);
  return [first, ...rest].flatMap(p => p.data);
}

async function loadProducts(){
  PRODUCT_LOAD_ERROR = false;
  try{
    const raw = await fetchAllProducts();
    return raw.map(p=>({
      id:p.id, row:p.r, name:p.nm, set:p.se, type:p.ty, tags:p.tg || '', pl:p.pl || null,
      language:p.la, img:p.img || '', st:p.st || 'ok', imagePending:!!p.ip, tp:p.tp || null, tn:p.tn || ''
    }));
  }catch(e){
    console.error('Failed to load products', e);
    PRODUCT_LOAD_ERROR = true;
    return [];
  }
}

async function loadProductOwnership(){
  const owned = {}, qty = {};
  try{
    const res = await window.storage.list('prodowned:');
    if(res && res.keys) for(const k of res.keys){
      try{ const r = await window.storage.get(k, false); if(r && r.value === '1') owned[k.slice('prodowned:'.length)] = true; }catch(e){}
    }
    const qres = await window.storage.list('prodqty:');
    if(qres && qres.keys) for(const k of qres.keys){
      try{ const r = await window.storage.get(k, false); const n = r ? (parseInt(r.value,10)||0) : 0; if(n>0) qty[k.slice('prodqty:'.length)] = n; }catch(e){}
    }
  }catch(e){ /* storage unavailable */ }
  productState.owned = owned;
  productState.qty = qty;
}

function getProductQty(id){ const l = productLink(id); return l ? getQty(l) : (productState.qty[id] || 0); }

async function setProductQty(id, n){
  n = Math.max(0, n|0);
  const link = productLink(id);
  if(link){
    if(n > 0 && !state.owned[link]){ if(!canAddMoreItems(true)) return; await toggleOwned(link); }
    await setQty(link, n);
    renderProductAll(); refreshBinderIfVisible(); return;
  }
  if(n > 0 && !productState.owned[id]){
    if(!canAddMoreItems(true)) return;
    productState.owned[id] = true;
    try{ await window.storage.set('prodowned:'+id, '1', false); }catch(e){}
  }
  productState.qty[id] = n;
  try{ await window.storage.set('prodqty:'+id, String(n), false); }catch(e){}
  const el = document.getElementById('prodQtyValue-'+id);
  if(el) el.textContent = n;
  renderProductAll();
  refreshBinderIfVisible();
  queueCloudSave();
}

async function toggleProductOwned(id){
  const p = PRODUCTS.find(x=>x.id===id);
  if(!p || !productReleased(p)) return;
  if(p.pl){ await toggleOwned(p.pl); renderProductAll(); return; }
  const next = !productState.owned[id];
  if(next && !canAddMoreItems(true)) return;
  productState.owned[id] = next;
  try{ await window.storage.set('prodowned:'+id, next ? '1':'0', false); }catch(e){}
  renderProductAll();
  refreshBinderIfVisible();
  queueCloudSave();
}

async function markAllProductsOwned(){
  let toMark = PRODUCTS.filter(p=>productReleased(p) && !productState.owned[p.id] && productMatches(p));
  if(toMark.length === 0){ alert('Every released product in this view is already marked as HAVE.'); return; }
  const limit = getTierLimit();
  let cappedNote = '';
  if(limit !== Infinity){
    const room = Math.max(0, limit - getTotalBinderCount());
    if(room === 0){ canAddMoreItems(true); return; }
    if(toMark.length > room){
      toMark = toMark.slice(0, room);
      cappedNote = ` Your ${tierDisplayName(currentUserTier)} plan caps your binder at ${limit} items, so only ${room} could be added — upgrade to add the rest.`;
    }
  }
  if(!confirm(`Mark ${toMark.length} released product${toMark.length!==1?'s':''} in this view as HAVE?`)) return;
  for(const p of toMark){
    productState.owned[p.id] = true;
    try{ await window.storage.set('prodowned:'+p.id, '1', false); }catch(e){}
  }
  renderProductAll();
  queueCloudSave();
  if(cappedNote) alert(cappedNote.trim());
}

/* ---------- Filtering / sorting ---------- */

function productMatches(p){
  const q = productState.search.trim().toLowerCase();
  if(q){
    const hay = [p.name, p.set, PRODUCT_SET_NAMES[p.set]||'', p.type, p.tags, p.language].join(' ').toLowerCase();
    if(!hay.includes(q)) return false;
  }
  const s = productState.status;
  // Default view hides TBD (not yet released in that language) entries.
  if(s === '' && p.st === 'tbd') return false;
  if(s === 'released' && !productReleased(p)) return false;
  if(s === 'tbd' && p.st !== 'tbd') return false;
  if(s === 'soon' && p.st !== 'soon') return false;
  if(s === 'pending' && !(productReleased(p) && (p.imagePending || !p.img))) return false;
  if(s === 'HAVE' && !productOwned(p)) return false;
  if(s === 'NEED' && !(productReleased(p) && !productOwned(p))) return false;
  if(productState.type && p.type !== productState.type) return false;
  if(productState.language && p.language !== productState.language) return false;
  if(productState.set && p.set !== productState.set) return false;
  return true;
}

function sortProducts(list){
  const arr = [...list];
  const langIdx = l => ['English','Chinese','French','Korean'].indexOf(l);
  if(productState.sort === 'name') arr.sort((a,b)=>a.name.localeCompare(b.name) || langIdx(a.language)-langIdx(b.language));
  else if(productState.sort === 'status'){
    const rank = p => productOwned(p) ? 0 : productReleased(p) ? 1 : p.st === 'tbd' ? 2 : 3;
    arr.sort((a,b)=>rank(a)-rank(b) || a.row-b.row || langIdx(a.language)-langIdx(b.language));
  }
  else arr.sort((a,b)=>a.row-b.row || langIdx(a.language)-langIdx(b.language));
  return arr;
}

function getFilteredProductList(){ return sortProducts(PRODUCTS.filter(productMatches)); }

/* ---------- Tiles ---------- */

function productPlaceholderHtml(p){
  if(p.st === 'soon') return `<div class="prod-ph soon"><span class="prod-ph-tag">Coming soon</span><span class="prod-ph-sub">Details will be added once announced</span></div>`;
  if(p.st === 'tbd') return `<div class="prod-ph tbd"><span class="prod-ph-tag">TBD</span><span class="prod-ph-sub">Not yet released in ${escapeHtml(p.language)} — will be updated once available</span></div>`;
  return `<div class="prod-ph pending"><span class="prod-ph-tag">Image Pending</span><span class="prod-ph-sub">${escapeHtml(p.language)} image will be added soon</span></div>`;
}

function productImageHtml(p){
  if(p.st !== 'ok' || !p.img) return productPlaceholderHtml(p);
  const pending = productPlaceholderHtml({ ...p, st:'ok' }).replace(/"/g,'&quot;');
  return `<img class="prod-img" src="${escapeHtml(p.img)}" alt="${escapeHtml(p.name)}" loading="lazy" draggable="false" oncontextmenu="return false" onerror="this.parentElement.querySelector('.prod-img-slot').innerHTML='${pending}';this.remove();"/><span class="prod-img-slot"></span>`;
}

function productStatusBadge(p){
  if(p.st === 'soon') return `<span class="prod-badge soon">Coming soon</span>`;
  if(p.st === 'tbd') return `<span class="prod-badge tbd">TBD</span>`;
  if(p.imagePending || !p.img) return `<span class="prod-badge pending">Image pending</span>`;
  return '';
}

function productCardHtml(p){
  const owned = productOwned(p);
  const released = productReleased(p);
  return `
  <div class="card product-card ${owned?'is-have':''} ${released?'':'is-unreleased'}" data-id="${p.id}" onclick="openModal('${p.id}')" role="button" tabindex="0">
    <div class="img-wrap product-wrap">
      ${productImageHtml(p)}
      ${productStatusBadge(p)}
      ${wishHeartHtml('prod:' + p.id)}
      ${trendOverlayHtml(productTrendBadgeHtml(p))}
      <div class="br-badges">${langFlagHtml(p.language)}</div>
      ${released ? `<div class="check-seal" onclick="event.stopPropagation(); toggleProductOwned('${p.id}')" title="Toggle owned">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><path d="M20 6 9 17l-5-5"/></svg>
      </div>${qtyBubbleHtml(getProductQty(p.id))}` : ''}
    </div>
    <div class="card-body">
      <div class="card-title">${escapeHtml(p.name)}${productReturnBadge(p)}</div>
      <div class="card-meta">${escapeHtml(p.set || '')}${PRODUCT_SET_NAMES[p.set] ? ' &middot; '+escapeHtml(PRODUCT_SET_NAMES[p.set]) : ''}</div>
      <div class="chip-row">
        ${p.type ? `<span class="pip">${escapeHtml(p.type)}</span>` : ''}
        ${langPipHtml(p.language)}
      </div>
      <div class="card-footer">
        <span class="num"></span>
        <button class="info-btn" onclick="event.stopPropagation(); openModal('${p.id}')">Details &rarr;</button>
      </div>
    </div>
  </div>`;
}

function renderProductResults(){
  const container = document.getElementById('productResults');
  if(!container) return;
  if(typeof cbUpdateLangBars === 'function') cbUpdateLangBars();
  if(PRODUCT_LOAD_ERROR){
    container.innerHTML = `<div class="empty-state">Products couldn't load right now. Please refresh the page in a moment.</div>`;
    return;
  }
  const list = getFilteredProductList();
  if(list.length === 0){
    if(productState.language && !PRODUCTS.some(p=>p.language===productState.language)){
      container.innerHTML = comingSoonPanel(`${productState.language} products are on the way`,
        `${productState.language} products haven't been added to the tracker yet. Check back soon.`);
    } else {
      container.innerHTML = `<div class="empty-state">No products match your filters.</div>`;
    }
    return;
  }
  const gridCls = `grid ${productState.view==='list'?'list-mode':''}`;
  if(productState.sort === 'row' && !productState.set){
    const groups = {};
    list.forEach(p=>{ (groups[p.set] = groups[p.set] || []).push(p); });
    const keys = Object.keys(groups).sort((a,b)=>{
      const ia = PRODUCT_SET_ORDER.indexOf(a), ib = PRODUCT_SET_ORDER.indexOf(b);
      return (ia<0?99:ia) - (ib<0?99:ib);
    });
    container.innerHTML = keys.map(k=>`
      <div class="group-heading">${escapeHtml(PRODUCT_SET_NAMES[k] || k)} <span class="count">${groups[k].length} item${groups[k].length!==1?'s':''}</span></div>
      <div class="${gridCls}">${groups[k].map(productCardHtml).join('')}</div>`).join('');
  } else {
    container.innerHTML = `<div class="${gridCls}">${list.map(productCardHtml).join('')}</div>`;
  }
}

function renderProductStats(){
  const bar = document.getElementById('productStatsBar');
  if(!bar) return;
  const released = PRODUCTS.filter(productReleased);
  const have = released.filter(productOwned).length;
  const need = released.length - have;
  const upcoming = PRODUCTS.length - released.length;
  const pct = released.length ? Math.round(have/released.length*100) : 0;
  const count = arr => ({ owned: arr.filter(productOwned).length, total: arr.length });
  const langChips = ['English','Chinese','French','Korean'].map(l=>({
    label:l, kind:'lang', value:l, ...count(released.filter(p=>p.language===l))
  }));
  const setChips = PRODUCT_SET_ORDER.filter(s=>PRODUCTS.some(p=>p.set===s)).map(s=>({
    label:s, kind:'set', value:s, ...count(released.filter(p=>p.set===s))
  }));
  bar.innerHTML = `
    <div class="stat total"><div class="n">${released.length}</div><div class="l">Released items</div></div>
    <div class="stat have"><div class="n">${have}</div><div class="l">Have &middot; ${pct}%</div>
      <div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div>
    </div>
    <div class="stat need"><div class="n">${need}</div><div class="l">Still need</div></div>
    <div class="stat"><div class="n" style="color:var(--gold-bright)">${upcoming}</div><div class="l">Upcoming / TBD</div></div>
    <div class="stat-breakdown">
      ${langChips.map(c=>chipButtonHtml(c, productState.language===c.value, 'filterProductsByChip')).join('')}
      ${setChips.map(c=>chipButtonHtml(c, productState.set===c.value, 'filterProductsByChip')).join('')}
    </div>`;
}

function renderProductAll(){
  renderProductStats();
  renderProductResults();
  if(typeof refreshBinderIfVisible === 'function') refreshBinderIfVisible();
  const open = document.getElementById('modalBackdrop').classList.contains('open');
  if(open && currentModalKind === 'product' && currentModalId) openProductModal(currentModalId);
}

function filterProductsByChip(btn){
  const kind = btn.getAttribute('data-chip-kind');
  const value = btn.getAttribute('data-chip-value');
  if(kind === 'lang'){
    productState.language = productState.language === value ? '' : value;
    const sel = document.getElementById('productLanguageFilter');
    if(sel) sel.value = productState.language;
    syncCardLangPicker(productState.language);
  } else {
    productState.set = productState.set === value ? '' : value;
    const sel = document.getElementById('productSetFilter');
    if(sel) sel.value = productState.set;
  }
  renderProductStats();
  renderProductResults();
  scrollToResults('productResults');
}

/* ---------- Details window ---------- */

function openProductModal(id){
  const p = PRODUCTS.find(x=>x.id===id);
  if(!p) return;
  currentModalId = id;
  currentModalKind = 'product';
  const released = productReleased(p);
  const owned = productOwned(p);
  const statusLabel = p.st === 'soon' ? 'Coming soon' : p.st === 'tbd' ? 'TBD' : (owned ? 'HAVE' : 'NEED');
  const statusCls = p.st === 'ok' ? statusLabel : 'ORDERED';
  const siblings = PRODUCTS.filter(x=>x.row===p.row && x.id!==p.id);
  const tagsHtml = p.tags ? `<ul class="prod-contents">${p.tags.split('\n').map(t=>`<li>${escapeHtml(t)}</li>`).join('')}</ul>` : '&mdash;';
  let note = '';
  if(p.st === 'soon') note = 'This product has been announced but its details aren’t available yet. It will be updated once they are.';
  else if(p.st === 'tbd') note = `Not yet released in ${p.language}. This listing will be updated once it’s available.`;
  else if(p.imagePending || !p.img) note = `Image pending — the ${p.language} product photo will be added soon. Product details are current.`;
  const qty = getProductQty(p.id);

  document.getElementById('modalBody').innerHTML = `
    <button class="modal-close" onclick="closeModal()">&times;</button>
    <h2>${escapeHtml(p.name)}${productTrendBadgeHtml(p)}</h2>
    <div class="modal-sub">${escapeHtml(p.type)} &middot; ${escapeHtml(PRODUCT_SET_NAMES[p.set] || p.set)} &middot; <span class="status-chip ${statusCls}" style="position:static;display:inline-block;">${escapeHtml(statusLabel)}</span></div>
    <div class="modal-imgs-row">
      <div class="modal-imgs"><div class="modal-img-wrap product-modal-img">${productImageHtml(p)}<div class="br-badges">${langFlagHtml(p.language)}</div></div></div>
    </div>
    ${note ? `<div class="prod-note">${escapeHtml(note)}</div>` : ''}
    <div class="modal-grid">
      <div><div class="k">Set</div><div class="v">${escapeHtml(p.set)}${PRODUCT_SET_NAMES[p.set] ? ' — '+escapeHtml(PRODUCT_SET_NAMES[p.set]) : ''}</div></div>
      <div><div class="k">Product type</div><div class="v">${escapeHtml(p.type)||'&mdash;'}</div></div>
      <div><div class="k">Language</div><div class="v">${languageFieldHtml(p.language, siblings)}</div></div>
      <div><div class="k">Status</div><div class="v">${released ? 'Released' : p.st === 'tbd' ? 'Not yet released' : 'Coming soon'}</div></div>
    </div>
    <div class="modal-desc"><div class="k" style="margin-bottom:6px;">Contents &amp; details</div>${tagsHtml}</div>
    ${released ? `
    <div class="qty-row">
      <span class="qty-label">Copies owned</span>
      <div class="qty-stepper">
        <button type="button" onclick="setProductQty('${p.id}', getProductQty('${p.id}')-1)">&minus;</button>
        <span id="prodQtyValue-${p.id}">${qty}</span>
        <button type="button" onclick="setProductQty('${p.id}', getProductQty('${p.id}')+1)">+</button>
      </div>
    </div>
    ${versionSectionHtml('prod:' + p.id)}${paidSectionHtml([{ key: 'prod:' + p.id, label: '' }])}
    <div class="modal-actions">
      <a href="#" onclick="toggleProductOwned('${p.id}');return false;">${owned ? 'Mark as not owned' : 'Mark as owned'}</a>
    </div>` : ''}
    <div class="modal-actions"><a href="#" onclick="toggleWish('prod:${p.id}');reopenCurrentModal();return false;">${wishOn('prod:' + p.id) ? '&#9829; On your wishlist' : '&#9825; Add to wishlist'}</a></div>
    <div id="cbEbay"></div>
  `;
  document.getElementById('modalBackdrop').classList.add('open');
  updateModalNavButtons();
  fillEbayPrice('prod', p);
}

/* ---------- eBay asking price (get-ebay-price) ----------
   Every sealed product (everyone) and every promo (VIP) is looked up from its own name, so
   new items get it automatically. Lowest current eBay asking price, English items only.
   Nothing shows when eBay has fewer than 3 matching listings. */
const ebayPriceCache = new Map();
async function fillEbayPrice(kind, item){
  const box = document.getElementById('cbEbay'); if(!box || !sb) return;
  if(kind === 'promo' && !isVipTier()) return;
  if(kind === 'prod' && item.language && item.language !== 'English') return;
  const key = kind + ':' + item.id;
  let res = ebayPriceCache.get(key);
  if(!res){
    try{
      const r = await sb.functions.invoke('get-ebay-price', { body:{ kind, id:item.id } });
      res = (!r.error && r.data) || { none:true };
    }catch(e){ res = { none:true }; }
    ebayPriceCache.set(key, res);
  }
  const el = document.getElementById('cbEbay');
  if(!el || currentModalId !== item.id || !(res.low > 0)) return;
  const url = ebayLink('https://www.ebay.com/sch/i.html?_nkw=' + encodeURIComponent(res.query || item.name) + '&_sop=15&LH_BIN=1');
  el.innerHTML = `<div class="cbp-k">eBay asking price</div>
    <div class="cbp-meta"><b>${escapeHtml(displayMoney(res.low))}</b> lowest of ${res.count} matching eBay listings${kind === 'prod' ? ' (new)' : ''}, before shipping. Asking prices, not sold prices.
    <a href="${escapeHtml(url)}" target="_blank" rel="noopener sponsored">See them on eBay &#8599;</a></div>`;
}

/* ---------- Disclaimer ---------- */

function renderMerchDisclaimer(){
  const el = document.getElementById('merchLinks');
  if(!el) return;
  el.innerHTML = MERCH_LINKS.filter(m=>m.url).map(m=>
    `<a href="${escapeHtml(m.url)}" target="_blank" rel="noopener">${escapeHtml(m.region)} &#8599;</a>`).join('');
}

/* ---------- Wiring ---------- */

function populateProductFilters(){
  const fill = (id, values, label) => {
    const el = document.getElementById(id);
    if(!el) return;
    el.innerHTML = `<option value="">${label}</option>` + values.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');
  };
  const types = [...new Set(PRODUCTS.map(p=>p.type).filter(Boolean))].sort();
  fill('productTypeFilter', types, 'All product types');
  fill('productLanguageFilter', ['English','Chinese','French','Korean'], 'All languages');
  const setSel = document.getElementById('productSetFilter');
  if(setSel){
    setSel.innerHTML = '<option value="">All sets</option>' + PRODUCT_SET_ORDER
      .filter(s=>PRODUCTS.some(p=>p.set===s))
      .map(s=>`<option value="${s}">${s} — ${escapeHtml(PRODUCT_SET_NAMES[s])}</option>`).join('');
  }
}

function cbInitProducts(){
  renderMerchDisclaimer();
  populateProductFilters();
  const on = (id, ev, fn) => { const el = document.getElementById(id); if(el) el.addEventListener(ev, fn); };
  on('productSearchInput','input', e=>{ productState.search = e.target.value; renderProductResults(); });
  on('productStatusFilter','change', e=>{ productState.status = e.target.value; renderProductResults(); });
  on('productTypeFilter','change', e=>{ productState.type = e.target.value; renderProductResults(); });
  on('productLanguageFilter','change', e=>{ productState.language = e.target.value; syncCardLangPicker(e.target.value); renderProductStats(); renderProductResults(); });
  on('productSetFilter','change', e=>{ productState.set = e.target.value; renderProductStats(); renderProductResults(); });
  on('productSortSelect','change', e=>{ productState.sort = e.target.value; renderProductResults(); });
  on('productGridBtn','click', ()=>{ productState.view='grid'; document.getElementById('productGridBtn').classList.add('active'); document.getElementById('productListBtn').classList.remove('active'); renderProductResults(); });
  on('productListBtn','click', ()=>{ productState.view='list'; document.getElementById('productListBtn').classList.add('active'); document.getElementById('productGridBtn').classList.remove('active'); renderProductResults(); });
  on('productResetBtn','click', ()=>{
    Object.assign(productState, { search:'', status:'', type:'', language:'', set:'', sort:'row' });
    ['productSearchInput','productStatusFilter','productTypeFilter','productLanguageFilter','productSetFilter'].forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
    const s = document.getElementById('productSortSelect'); if(s) s.value = 'row';
    renderProductStats(); renderProductResults();
  });
  on('productMarkAllBtn','click', markAllProductsOwned);
  on('productResults','keydown', e=>{
    if(e.key !== 'Enter' && e.key !== ' ') return;
    const card = e.target.closest('.card');
    if(!card) return;
    e.preventDefault();
    openModal(card.dataset.id);
  });
  on('importBtn3','click', ()=> document.getElementById('importFileInput').click());
  on('exportBtn3','click', openExportGate);
  // Keep the Products language in step with the top Card language picker.
  const picker = document.getElementById('cardLangSelect');
  if(picker) picker.addEventListener('change', e=>{
    const L = CARD_LANGS.find(l=>l.code===e.target.value);
    productState.language = L ? L.data : '';
    const sel = document.getElementById('productLanguageFilter');
    if(sel) sel.value = productState.language;
    renderProductStats(); renderProductResults();
  });
  if(picker && picker.value){
    const L = CARD_LANGS.find(l=>l.code===picker.value);
    if(L){ productState.language = L.data; const sel = document.getElementById('productLanguageFilter'); if(sel) sel.value = L.data; }
  }
}


/* ---------- "Showing French only" bars ----------
   When a language filter is on (from the top picker, a tab's Language
   dropdown, or a chip), each tab says so above its results, with a
   one-click way back to every language. */

function langBarHtml(lang, what){
  return `<span>Showing <span class="lfb-lang" data-lang="${escapeHtml(lang)}">${escapeHtml(lang)}</span> ${what} only</span>
    <button type="button" onclick="clearLanguageEverywhere()">Show all languages</button>`;
}

function cbUpdateLangBars(){
  if(typeof cbUpdatePromoSetNote === 'function') cbUpdatePromoSetNote();
  const bars = [
    ['promoLangBar',   typeof state !== 'undefined' ? state.language : '',  'promos &amp; collectibles'],
    ['setLangBar',     typeof setState !== 'undefined' ? setState.language : '', 'cards'],
    ['productLangBar', productState.language, 'products']
  ];
  bars.forEach(([id, lang, what])=>{
    const el = document.getElementById(id);
    if(!el) return;
    if(lang){ el.innerHTML = langBarHtml(lang, what); el.hidden = false; }
    else { el.innerHTML = ''; el.hidden = true; }
  });
}

function clearLanguageEverywhere(){
  try{ localStorage.setItem('cb:cardLang', ''); }catch(e){}
  const picker = document.getElementById('cardLangSelect');
  if(picker) picker.value = '';
  productState.language = '';
  const pf = document.getElementById('productLanguageFilter');
  if(pf) pf.value = '';
  applyCardLanguage('');   // clears Promos + Card Sets and re-renders them
  renderProductStats();
  renderProductResults();
}

// Refresh the bars whenever any tab re-draws its results.
(function(){
  const wrap = name => {
    const orig = window[name];
    if(typeof orig !== 'function') return;
    const wrapped = function(){ const r = orig.apply(this, arguments); cbUpdateLangBars(); return r; };
    window[name] = wrapped;
  };
  ['renderResults','renderSetResults'].forEach(wrap);
})();


/* =====================================================================
   STAMP BOXES + CLICK-TO-ENLARGE
   ===================================================================== */

// Red box drawn over the stamp on specific promo images, for photos that
// don't already have one. Values are % of the image: left, top, width, height.
// Nudge the numbers if a box sits slightly off.
const STAMP_BOXES = {
  'item-213': { x:63.5, y:45.8, w:30.9, h:19.6 }   // Miss Fortune - Buccaneer (Competitor Badge)
};
const TILE_IMG_SCALE = 1.07; // tiles zoom images slightly (see .img-wrap img)

function stampBoxHtml(id, onTile){
  const b = STAMP_BOXES[id];
  if(!b) return '';
  // On tiles the photo is scaled from its centre, so scale the box to match.
  const k = onTile ? TILE_IMG_SCALE : 1;
  const x = 50 + (b.x - 50) * k, y = 50 + (b.y - 50) * k;
  return `<span class="stamp-box" aria-hidden="true" style="left:${x.toFixed(2)}%;top:${y.toFixed(2)}%;width:${(b.w*k).toFixed(2)}%;height:${(b.h*k).toFixed(2)}%"></span>`;
}

// Ask the image host for a bigger copy when one is available.
function largeImageUrl(src){
  if(!src || src.startsWith('data:')) return src;
  if(/drive\.google\.com\/thumbnail/.test(src)) return src.replace(/([?&])sz=w\d+/, '$1sz=w1600');
  if(/cmsassets\.rgpub\.io|cdn\.sanity\.io/.test(src)) return src.replace(/([?&])w=\d+/, '$1w=1200');
  return src;
}

function cbEnsureLightbox(){
  let lb = document.getElementById('cbLightbox');
  if(lb) return lb;
  lb = document.createElement('div');
  lb.id = 'cbLightbox';
  lb.className = 'cb-lightbox';
  lb.setAttribute('role','dialog');
  lb.setAttribute('aria-modal','true');
  lb.setAttribute('aria-label','Enlarged image');
  lb.innerHTML = `
    <div class="lb-bar">
      <span class="lb-title" id="cbLightboxTitle"></span>
      <button type="button" class="lb-zoom" id="cbLightboxZoom">Zoom in</button>
      <button type="button" class="lb-close" id="cbLightboxClose" aria-label="Close enlarged image">&times;</button>
    </div>
    <div class="lb-scroll"><div class="lb-frame" id="cbLightboxFrame"></div></div>
    <div class="lb-credit">Shared from unravelingtherift.com</div>`;
  (document.getElementById('collectBoundApp') || document.body).appendChild(lb);
  lb.addEventListener('click', e=>{ if(e.target === lb) closeLightbox(); });
  document.getElementById('cbLightboxClose').addEventListener('click', closeLightbox);
  document.getElementById('cbLightboxZoom').addEventListener('click', toggleLightboxZoom);
  return lb;
}

function toggleLightboxZoom(){
  const lb = document.getElementById('cbLightbox');
  if(!lb) return;
  const zoomed = lb.classList.toggle('zoomed');
  document.getElementById('cbLightboxZoom').textContent = zoomed ? 'Fit to screen' : 'Zoom in';
}

let cbLightboxReturnFocus = null;
function openLightbox(img){
  if(!img || !img.getAttribute('src')) return;
  const lb = cbEnsureLightbox();
  cbLightboxReturnFocus = document.activeElement;
  const wrap = img.closest('.modal-img-wrap, .pkg-thumb');
  const box = wrap ? wrap.querySelector('.stamp-box') : null;
  const frame = document.getElementById('cbLightboxFrame');
  const src = img.getAttribute('src');
  frame.classList.toggle('wm-light', !!(wrap && wrap.classList.contains('wm-light')));
  frame.innerHTML = `<img alt="${escapeHtml(img.alt || '')}" draggable="false" oncontextmenu="return false"/>${box ? box.outerHTML : ''}`;
  const big = frame.querySelector('img');
  big.onerror = () => { if(big.src !== src) big.src = src; };   // fall back to the smaller copy
  big.src = largeImageUrl(src);
  big.addEventListener('click', toggleLightboxZoom);
  document.getElementById('cbLightboxTitle').textContent = img.alt || '';
  lb.classList.remove('zoomed');
  document.getElementById('cbLightboxZoom').textContent = 'Zoom in';
  lb.classList.add('open');
  document.getElementById('cbLightboxClose').focus();
}

function closeLightbox(){
  const lb = document.getElementById('cbLightbox');
  if(!lb || !lb.classList.contains('open')) return;
  lb.classList.remove('open', 'zoomed');
  document.getElementById('cbLightboxFrame').innerHTML = '';
  if(cbLightboxReturnFocus && cbLightboxReturnFocus.focus) cbLightboxReturnFocus.focus();
}

// Any picture in a details window opens the viewer when clicked, tapped,
// or (via keyboard) when focused and Enter/Space is pressed.
document.addEventListener('click', e=>{
  const wrap = e.target.closest && e.target.closest('#modalBody .modal-img-wrap, #modalBody .pkg-thumb');
  if(!wrap) return;
  const img = wrap.querySelector('img');
  if(img){ e.preventDefault(); openLightbox(img); }
});
// Esc closes the viewer first, leaving the details window open underneath.
document.addEventListener('keydown', e=>{
  const lb = document.getElementById('cbLightbox');
  if(!lb || !lb.classList.contains('open')) return;
  if(e.key === 'Escape'){ e.preventDefault(); e.stopImmediatePropagation(); closeLightbox(); }
  else if(e.key === 'ArrowLeft' || e.key === 'ArrowRight'){ e.stopImmediatePropagation(); }
}, true);

// Make details-window pictures reachable by keyboard and add a small hint.
new MutationObserver(()=>{
  document.querySelectorAll('#modalBody .modal-img-wrap, #modalBody .pkg-thumb').forEach(w=>{
    if(w.dataset.zoomReady) return;
    w.dataset.zoomReady = '1';
    w.setAttribute('role','button');
    w.setAttribute('tabindex','0');
    w.setAttribute('aria-label','Enlarge image');
    w.title = 'Click to enlarge';
    w.addEventListener('keydown', ev=>{
      if(ev.key === 'Enter' || ev.key === ' '){ ev.preventDefault(); const im = w.querySelector('img'); if(im) openLightbox(im); }
    });
  });
  const row = document.querySelector('#modalBody .modal-imgs-row');
  if(row && !row.querySelector('.zoom-hint') && row.querySelector('img')){
    const hint = document.createElement('span');
    hint.className = 'zoom-hint';
    hint.textContent = 'Click the image to enlarge';
    row.appendChild(hint);
  }
}).observe(document.getElementById('modalBody'), { childList:true });

if(!MEMBERSHIP_ENABLED){
  const jb = document.getElementById('joinChaseBtn'); if(jb) jb.style.display = 'none';
  ['exportBtn1','exportBtn2','exportBtn3'].forEach(id=>{ const b = document.getElementById(id); if(b) b.textContent = 'Export Collection'; });
}

(async function init(){
  loadLegality();
  loadTrends();
  loadDecks();
  const cardsStart = cbLoadCardsCached();   // start card download now, in parallel with the rest
  ITEMS = await loadItems();
  promosLoaded = true;

  populateFilters();
  await loadOwned();
  await loadQty();
  await migrateMergedPromos();
  await loadGrading();
  await loadExtras();
  renderAll();

  const cardLoad = await cardsStart;
  CARDS = cardLoad.cards;
  populateSetFilters();
  await loadCardOwnership();
  renderSetAll();
  maybeShowUnlZhNotice();
  cbInitCardLanguage();
  PRODUCTS = await loadProducts();
  await loadProductOwnership();
  await migrateMergedProducts();
  cbInitProducts();
  renderProductAll();
  // Sign-in can finish before cards load, so recount once everything's in.
  updateAuthUI();
  fitSidePanels();
  // Cached cards were shown instantly; quietly swap in fresh data when it arrives.
  if(cardLoad.refresh){
    cardLoad.refresh.then(fresh=>{
      if(fresh.length && CARD_LOAD_ERRORS.length === 0){
        CARDS = fresh;
        cbWriteCardCache(fresh);
        populateSetFilters();
        renderSetAll();
        updateAuthUI();
      }
    }).catch(()=>{});
  }
  // Promos were shown from the saved copy: fetch the latest list now so new
  // items, pictures and fixes appear without anyone refreshing the page.
  if(promosFromCache) setTimeout(async ()=>{ await reloadPromosForTier(); await migrateMergedPromos(); }, 1500);
  // Page left open in a tab: when it comes back into view after 10+ minutes, quietly update.
  let lastFresh = Date.now();
  document.addEventListener('visibilitychange', async ()=>{
    if(document.visibilityState !== 'visible' || Date.now() - lastFresh < 10 * 60 * 1000) return;
    lastFresh = Date.now();
    await reloadPromosForTier(); await migrateMergedPromos();
    try{
      const fresh = await loadCards();
      if(fresh.length && CARD_LOAD_ERRORS.length === 0){ CARDS = fresh; cbWriteCardCache(fresh); populateSetFilters(); renderSetAll(); updateAuthUI(); }
    }catch(e){}
  });
})();

/* Note about picture quality, shown under the tabs. */
(function(){
  var first = document.querySelector('#collectBoundApp .growth-note');
  if(!first || document.getElementById('imgQualityNote')) return;
  var n = first.cloneNode(true);
  n.id = 'imgQualityNote';
  n.querySelector('.growth-note-icon').innerHTML = '&#128247;';
  n.querySelector('.growth-note-text').textContent = 'About the pictures: Riot Games does not supply pictures of promos and collectibles. We find them through careful research of publicly available pictures online and from the collector community, so some may be lower quality or photos of the real item. We replace them with sharper ones whenever we find them. Pictures are shown only to help you identify items. Card art and game content belong to Riot Games and their artists.';
  first.parentNode.insertBefore(n, first.nextSibling);
})();
